window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["MAT"]={"book":"MAT","editions":{"fin-biblia1776":[[1,1,"Jesuksen Kristuksen syntymäkirja, Davidin pojan, Abrahamin pojan.","Jesuksen Kristuksen syntymäkirja, Davidin pojan, Abrahamin pojan."],[1,2,"Abraham siitti Isaakin. Mutta Isaak siitti Jakobin. Jakob siitti Juudan, ja hänen veljensä,","Abraham siitti Isaakin. Mutta Isaak siitti Jakobin. Jakob siitti Juudan, ja hänen veljensä,"],[1,3,"Juuda siitti Phareksen ja Saramin Tamarista. Phares siitti Hetsronin. Hetsron siitti Aramin.","Juuda siitti Phareksen ja Saramin Tamarista. Phares siitti Hetsronin. Hetsron siitti Aramin."],[1,4,"Aram siitti Aminadabin. Aminadab siitti Nahassonin. Nahasson siitti Salmonin.","Aram siitti Aminadabin. Aminadab siitti Nahassonin. Nahasson siitti Salmonin."],[1,5,"Salmon siitti Boaksen Rahabista. Boas siitti Obedin Ruutista. Obed siitti Jessen.","Salmon siitti Boaksen Rahabista. Boas siitti Obedin Ruutista. Obed siitti Jessen."],[1,6,"Jesse siitti kuningas Davidin. Kuningas David siitti Salomonin Urian emännästä.","Jesse siitti kuningas Davidin. Kuningas David siitti Salomonin Urian emännästä."],[1,7,"Salomon siitti Rehabeamin. Rehabeam siitti Abian. Abia siitti Assan.","Salomon siitti Rehabeamin. Rehabeam siitti Abian. Abia siitti Assan."],[1,8,"Assa siitti Josaphatin. Josaphat siitti Joramin. Joram siitti Ussian.","Assa siitti Josaphatin. Josaphat siitti Joramin. Joram siitti Ussian."],[1,9,"Ussia siitti Jotamin. Jotam siitti Akaksen. Akas siitti Etsekian.","Ussia siitti Jotamin. Jotam siitti Akaksen. Akas siitti Etsekian."],[1,10,"Etsekia siitti Manassen. Manasse siitti Amonin. Amon siitti Josian.","Etsekia siitti Manassen. Manasse siitti Amonin. Amon siitti Josian."],[1,11,"Josia siitti (Jojakimin. Jojakim siitti) Jekonian ja hänen veljensä, Babelin vankiudessa.","Josia siitti (Jojakimin. Jojakim siitti) Jekonian ja hänen veljensä, Babelin vankiudessa."],[1,12,"Mutta Babelin vankiuden jälkeen siitti Jekonia Sealtielin. Sealtiel siitti Zorobabelin.","Mutta Babelin vankiuden jälkeen siitti Jekonia Sealtielin. Sealtiel siitti Zorobabelin."],[1,13,"Zorobabel siitti Abiudin. Abiud siitti Eliakimin. Eliakim siitti Asorin.","Zorobabel siitti Abiudin. Abiud siitti Eliakimin. Eliakim siitti Asorin."],[1,14,"Asor siitti Sadokin. Sadok siitti Akimin. Akim siitti Eliudin.","Asor siitti Sadokin. Sadok siitti Akimin. Akim siitti Eliudin."],[1,15,"Eliud siitti Eleatsarin. Eleatsar siitti Matanin. Matan siitti Jakobin.","Eliud siitti Eleatsarin. Eleatsar siitti Matanin. Matan siitti Jakobin."],[1,16,"Jakob siitti Josephin, Marian miehen, josta (Mariasta) on syntynyt Jesus, joka kutsutaan Kristus.","Jakob siitti Josephin, Marian miehen, josta (Mariasta) on syntynyt Jesus, joka kutsutaan Kristus."],[1,17,"Niin ovat kaikki polvet Abrahamista Davidiin asti neljätoistakymmentä polvea; Davidista Babelin vankiuteen myös neljätoistakymmentä polvea, ja Babelin vankiudesta Kristukseen asti neljätoistakymmentä polvea.","Niin ovat kaikki polvet Abrahamista Davidiin asti neljätoistakymmentä polvea; Davidista Babelin vankiuteen myös neljätoistakymmentä polvea, ja Babelin vankiudesta Kristukseen asti neljätoistakymmentä polvea."],[1,18,"Jesuksen Kristuksen syntymys oli näin: koska Maria hänen äitinsä oli Josephiin kihlattu, ennen kuin he yhteen tulivat, löyttiin hän raskaaksi Pyhästä Hengestä.","Jesuksen Kristuksen syntymys oli näin: koska Maria hänen äitinsä oli Josephiin kihlattu, ennen kuin he yhteen tulivat, löyttiin hän raskaaksi Pyhästä Hengestä."],[1,19,"Mutta että Joseph hänen miehensä oli hurskas ja ei tahtonut häntä huutoon saattaa, ajatteli hän salaisesti hyljätä hänen.","Mutta että Joseph hänen miehensä oli hurskas ja ei tahtonut häntä huutoon saattaa, ajatteli hän salaisesti hyljätä hänen."],[1,20,"Kuin hän näitä ajatteli, katso, niin Herran enkeli ilmestyi hänelle unessa ja sanoi: Joseph, Davidin poika! älä pelkää ottaakses Mariaa puolisoas tykös; sillä se, mikä hänessä on siinnyt, on Pyhästä Hengestä.","Kuin hän näitä ajatteli, katso, niin Herran enkeli ilmestyi hänelle unessa ja sanoi: Joseph, Davidin poika! älä pelkää ottaakses Mariaa puolisoas tykös; sillä se, mikä hänessä on siinnyt, on Pyhästä Hengestä."],[1,21,"Ja hänen pitää synnyttämän Pojan, jonka nimen sinun pitää kutsuman Jesus; sillä hän on vapahtava kansansa heidän synneistänsä.","Ja hänen pitää synnyttämän Pojan, jonka nimen sinun pitää kutsuman Jesus; sillä hän on vapahtava kansansa heidän synneistänsä."],[1,22,"Mutta tämä on kaikki tapahtunut, että täytettäisiin, mitä Herralta on sanottu prophetan kautta, joka sanoo:","Mutta tämä on kaikki tapahtunut, että täytettäisiin, mitä Herralta on sanottu prophetan kautta, joka sanoo:"],[1,23,"Katso, neitseen pitää raskaaksi tuleman ja synnyttämän Pojan, ja hänen nimensä pitää kutsuttaman Emmanuel; se on niin paljo sanottu: Jumala meidän kanssamme.","Katso, neitseen pitää raskaaksi tuleman ja synnyttämän Pojan, ja hänen nimensä pitää kutsuttaman Emmanuel; se on niin paljo sanottu: Jumala meidän kanssamme."],[1,24,"Kuin Joseph unesta heräsi, niin hän teki kuin Herran enkeli hänen käski, ja otti puolisonsa tykönsä,","Kuin Joseph unesta heräsi, niin hän teki kuin Herran enkeli hänen käski, ja otti puolisonsa tykönsä,"],[1,25,"Ja ei tuntenut häntä, siihenasti kuin hän poikansa esikoisensa synnytti, ja kutsui hänen nimensä Jesus.","Ja ei tuntenut häntä, siihenasti kuin hän poikansa esikoisensa synnytti, ja kutsui hänen nimensä Jesus."],[2,1,"Koska siis Jesus syntynyt oli Betlehemissä Juudan maalla, kuningas Herodeksen aikaan, katso, tietäjät tulivat idästä Jerusalemiin ja sanoivat:","Koska siis Jesus syntynyt oli Betlehemissä Juudan maalla, kuningas Herodeksen aikaan, katso, tietäjät tulivat idästä Jerusalemiin ja sanoivat:"],[2,2,"Kussa on se syntynyt Juudalaisten kuningas? sillä me näimme hänen tähtensä idässä, ja tulimme häntä kumartaen rukoilemaan.","Kussa on se syntynyt Juudalaisten kuningas? sillä me näimme hänen tähtensä idässä, ja tulimme häntä kumartaen rukoilemaan."],[2,3,"Kuin kuningas Herodes sen kuuli, hämmästyi hän ja kaikki Jerusalem hänen kanssansa,","Kuin kuningas Herodes sen kuuli, hämmästyi hän ja kaikki Jerusalem hänen kanssansa,"],[2,4,"Ja kokosi kaikki ylimmät papit ja kirjanoppineet kansan seassa, ja kyseli heiltä, kussa Kristuksen syntymän piti.","Ja kokosi kaikki ylimmät papit ja kirjanoppineet kansan seassa, ja kyseli heiltä, kussa Kristuksen syntymän piti."],[2,5,"Ja he sanoivat hänelle: Betlehemissä Juudan maalla; sillä niin on prophetan kautta kirjoitettu:","Ja he sanoivat hänelle: Betlehemissä Juudan maalla; sillä niin on prophetan kautta kirjoitettu:"],[2,6,"Ja sinä Betlehem Juudan maassa, et sinä ole suinkaan vähin Juudan pääruhtinasten seassa; sillä sinusta on tuleva se Ruhtinas, jonka minun kansaani Israelia pitää hallitseman.","Ja sinä Betlehem Juudan maassa, et sinä ole suinkaan vähin Juudan pääruhtinasten seassa; sillä sinusta on tuleva se Ruhtinas, jonka minun kansaani Israelia pitää hallitseman."],[2,7,"Silloin kutsui Herodes tietäjät salaa, ja tutkisteli visusti heiltä, millä ajalla tähti ilmestyi,","Silloin kutsui Herodes tietäjät salaa, ja tutkisteli visusti heiltä, millä ajalla tähti ilmestyi,"],[2,8,"Ja lähetti heidät Betlehemiin, ja sanoi: menkäät ja kysykäät visusti lapsesta, ja kuin te löydätte, niin ilmoittakaat minulle, että minäkin tulisin ja kumartaisin häntä.","Ja lähetti heidät Betlehemiin, ja sanoi: menkäät ja kysykäät visusti lapsesta, ja kuin te löydätte, niin ilmoittakaat minulle, että minäkin tulisin ja kumartaisin häntä."],[2,9,"Kuin he olivat kuninkaan kuulleet, menivät he matkaansa, ja katso, tähti, jonka he olivat nähneet idässä, kävi heidän edellänsä, niinkauvan kuin hän edellä käyden seisahti sen paikan päälle, jossa lapsi oli.","Kuin he olivat kuninkaan kuulleet, menivät he matkaansa, ja katso, tähti, jonka he olivat nähneet idässä, kävi heidän edellänsä, niinkauvan kuin hän edellä käyden seisahti sen paikan päälle, jossa lapsi oli."],[2,10,"Kuin he tähden näkivät, ihastuivat he sangen suurella ilolla,","Kuin he tähden näkivät, ihastuivat he sangen suurella ilolla,"],[2,11,"Ja menivät huoneeseen, löysivät lapsen äitinsä Marian kanssa, maahan lankesivat ja rukoilivat häntä, ja avasivat tavaransa, ja lahjoittivat hänelle kultaa ja pyhää savua ja mirhamia.","Ja menivät huoneeseen, löysivät lapsen äitinsä Marian kanssa, maahan lankesivat ja rukoilivat häntä, ja avasivat tavaransa, ja lahjoittivat hänelle kultaa ja pyhää savua ja mirhamia."],[2,12,"Ja Jumala kielsi heitä unessa Herodeksen tykö palajamasta; ja he menivät toista tietä omalle maallensa.","Ja Jumala kielsi heitä unessa Herodeksen tykö palajamasta; ja he menivät toista tietä omalle maallensa."],[2,13,"Mutta kuin he olivat menneet pois, katso, niin Herran enkeli ilmestyi Josephille unessa, sanoen: nouse ja ota lapsi äitinensä tykös, ja pakene Egyptiin, ja ole siellä siihen asti kuin minä sinulle sanon; sillä Herodes on etsivä lasta, hukuttaaksensa häntä.","Mutta kuin he olivat menneet pois, katso, niin Herran enkeli ilmestyi Josephille unessa, sanoen: nouse ja ota lapsi äitinensä tykös, ja pakene Egyptiin, ja ole siellä siihen asti kuin minä sinulle sanon; sillä Herodes on etsivä lasta, hukuttaaksensa häntä."],[2,14,"Niin hän nousi ja otti lapsen äitinensä yöllä tykönsä, ja pakeni Egyptiin,","Niin hän nousi ja otti lapsen äitinensä yöllä tykönsä, ja pakeni Egyptiin,"],[2,15,"Ja oli siellä Herodeksen kuolemaan asti: että täytettäisiin mitä sanottu oli Herralta prophetan kautta, joka sanoo: Egyptistä kutsuin minä poikani.","Ja oli siellä Herodeksen kuolemaan asti: että täytettäisiin mitä sanottu oli Herralta prophetan kautta, joka sanoo: Egyptistä kutsuin minä poikani."],[2,16,"Kuin Herodes näki itsensä tietäjiltä vietellyksi, vihastui hän sangen kovin, ja lähetti tappamaan kaikki poikalapset Betlehemissä ja kaikissa sen äärissä, jotka kaksivuotiset olivat taikka nuoremmat, sen ajan jälkeen, jonka hän oli tarkasti tietäjiltä tutkinut.","Kuin Herodes näki itsensä tietäjiltä vietellyksi, vihastui hän sangen kovin, ja lähetti tappamaan kaikki poikalapset Betlehemissä ja kaikissa sen äärissä, jotka kaksivuotiset olivat taikka nuoremmat, sen ajan jälkeen, jonka hän oli tarkasti tietäjiltä tutkinut."],[2,17,"Silloin se täytettiin, mitä Jeremialta prophetalta sanottu oli, joka sanoo:","Silloin se täytettiin, mitä Jeremialta prophetalta sanottu oli, joka sanoo:"],[2,18,"Ramassa on ääni kuulunut, suuri valitus, itku ja iso parku: Rakel itkee lapsiansa, ja ei tahtonut itsiänsä antaa lohdutettaa, ettei he ole.","Ramassa on ääni kuulunut, suuri valitus, itku ja iso parku: Rakel itkee lapsiansa, ja ei tahtonut itsiänsä antaa lohdutettaa, ettei he ole."],[2,19,"Mutta kuin Herodes oli kuollut, katso, niin Herran enkeli ilmestyi Josephille unessa Egyptissä ja sanoi:","Mutta kuin Herodes oli kuollut, katso, niin Herran enkeli ilmestyi Josephille unessa Egyptissä ja sanoi:"],[2,20,"Nouse ja ota lapsi äitinensä, ja mene Israelin maalle; sillä ne ovat kuolleet, jotka lapsen henkeä väijyivät.","Nouse ja ota lapsi äitinensä, ja mene Israelin maalle; sillä ne ovat kuolleet, jotka lapsen henkeä väijyivät."],[2,21,"Niin hän nousi ja otti lapsen äitinensä, ja meni Israelin maalle.","Niin hän nousi ja otti lapsen äitinensä, ja meni Israelin maalle."],[2,22,"Mutta kuin hän kuuli, että Arkelaus oli kuningas Juudeassa, isänsä Herodeksen siassa, pelkäsi hän sinne mennä. Ja hän sai Jumalalta käskyn unessa, ja poikkesi Galilean ääriin,","Mutta kuin hän kuuli, että Arkelaus oli kuningas Juudeassa, isänsä Herodeksen siassa, pelkäsi hän sinne mennä. Ja hän sai Jumalalta käskyn unessa, ja poikkesi Galilean ääriin,"],[2,23,"Ja tuli ja asui kaupungissa, joka kutsutaan Natsaret, että täytettäisiin mitä prophetain kautta sanottu oli: hän pitää Natsarealaiseksi kutsuttaman.","Ja tuli ja asui kaupungissa, joka kutsutaan Natsaret, että täytettäisiin mitä prophetain kautta sanottu oli: hän pitää Natsarealaiseksi kutsuttaman."],[3,1,"Niinä päivinä tuli Johannes Kastaja, ja saarnasi Juudean korvessa,","Niinä päivinä tuli Johannes Kastaja, ja saarnasi Juudean korvessa,"],[3,2,"Ja sanoi: tehkäät parannus; sillä taivaan valtakunta on lähestynyt.","Ja sanoi: tehkäät parannus; sillä taivaan valtakunta on lähestynyt."],[3,3,"Sillä tämä on se, josta sanottu on Jesaialta prophetalta, joka sanoo: huutavan ääni on korvessa, valmistakaat Herran tietä, tehkäät hänen polkunsa oikiaksi.","Sillä tämä on se, josta sanottu on Jesaialta prophetalta, joka sanoo: huutavan ääni on korvessa, valmistakaat Herran tietä, tehkäät hänen polkunsa oikiaksi."],[3,4,"Mutta Johanneksella oli vaate kamelin karvoista ja hihnainen vyö hänen vyöllänsä, ja hänen ruokansa oli heinäsirkat ja metsähunaja.","Mutta Johanneksella oli vaate kamelin karvoista ja hihnainen vyö hänen vyöllänsä, ja hänen ruokansa oli heinäsirkat ja metsähunaja."],[3,5,"Silloin meni hänen tykönsä Jerusalem, ja koko Juudea, ja kaikki maakunta Jordanin ympäriltä.","Silloin meni hänen tykönsä Jerusalem, ja koko Juudea, ja kaikki maakunta Jordanin ympäriltä."],[3,6,"Ja he kastettiin häneltä Jordanissa, ja tunnustivat heidän syntinsä.","Ja he kastettiin häneltä Jordanissa, ja tunnustivat heidän syntinsä."],[3,7,"Mutta kuin hän monta Pharisealaisista ja Saddukealaisista näki tulevan kasteensa tykö, sanoi hän heille: te kyykärmetten sikiät, kuka teitä neuvoi pakenemaan tulevaista vihaa?","Mutta kuin hän monta Pharisealaisista ja Saddukealaisista näki tulevan kasteensa tykö, sanoi hän heille: te kyykärmetten sikiät, kuka teitä neuvoi pakenemaan tulevaista vihaa?"],[3,8,"Tehkäät siis parannuksen soveliaita hedelmiä.","Tehkäät siis parannuksen soveliaita hedelmiä."],[3,9,"Ja älkäät ajatelko itsellenne sanoa: Abraham on meidän isämme. Millä minä sanon teille: Jumala voi näistä kivistä Abrahamille lapset herättää.","Ja älkäät ajatelko itsellenne sanoa: Abraham on meidän isämme. Millä minä sanon teille: Jumala voi näistä kivistä Abrahamille lapset herättää."],[3,10,"Mutta jo myös on kirves pantu puiden juurelle: sentähden jokainen puu, joka ei tee hyvää hedelmää, hakataan pois ja tuleen heitetään.","Mutta jo myös on kirves pantu puiden juurelle: sentähden jokainen puu, joka ei tee hyvää hedelmää, hakataan pois ja tuleen heitetään."],[3,11,"Minä tosin kastan teitä vedellä parannukseen; mutta se, joka minun jälkeeni tulee, on väkevämpi minua, jonka kenkiä en minä ole kelvollinen kantamaan, hän kastaa teitä Pyhällä Hengellä ja tulella.","Minä tosin kastan teitä vedellä parannukseen; mutta se, joka minun jälkeeni tulee, on väkevämpi minua, jonka kenkiä en minä ole kelvollinen kantamaan, hän kastaa teitä Pyhällä Hengellä ja tulella."],[3,12,"Jonka viskin on hänen kädessänsä, ja hän perkaa riihensä ja kokoo nisunsa aittaansa, mutta ruumenet polttaa hän sammumattomalla tulella.","Jonka viskin on hänen kädessänsä, ja hän perkaa riihensä ja kokoo nisunsa aittaansa, mutta ruumenet polttaa hän sammumattomalla tulella."],[3,13,"Silloin tuli Jesus Galileasta Jordaniin Johanneksen tykö, kastettaa häneltä;","Silloin tuli Jesus Galileasta Jordaniin Johanneksen tykö, kastettaa häneltä;"],[3,14,"Mutta Johannes kielsi häneltä, sanoen: minä tarvitsen sinulta kastettaa, ja sinä tulet minun tyköni?","Mutta Johannes kielsi häneltä, sanoen: minä tarvitsen sinulta kastettaa, ja sinä tulet minun tyköni?"],[3,15,"Niin vastasi Jesus ja sanoi hänelle: salli nyt; sillä näin meidän sopii kaikkea vanhurskautta täyttää. Ja hän salli hänen.","Niin vastasi Jesus ja sanoi hänelle: salli nyt; sillä näin meidän sopii kaikkea vanhurskautta täyttää. Ja hän salli hänen."],[3,16,"Kuin Jesus kastettu oli, astui hän kohta ylös vedestä: ja katso, taivaat aukenivat hänelle, ja hän näki Jumalan Hengen tulevan alas, niinkuin kyyhkyisen, ja tulevan hänen päällensä,","Kuin Jesus kastettu oli, astui hän kohta ylös vedestä: ja katso, taivaat aukenivat hänelle, ja hän näki Jumalan Hengen tulevan alas, niinkuin kyyhkyisen, ja tulevan hänen päällensä,"],[3,17,"Ja katso, ääni taivaasta sanoi: tämä on se minun rakas Poikani, johonka minä mielistyin.","Ja katso, ääni taivaasta sanoi: tämä on se minun rakas Poikani, johonka minä mielistyin."],[4,1,"Silloin vietiin Jesus hengeltä korpeen kiusattaa perkeleeltä.","Silloin vietiin Jesus hengeltä korpeen kiusattaa perkeleeltä."],[4,2,"Ja kuin hän oli paastonnut neljäkymmentä päivää ja neljäkymmentä yötä, sitte hän isosi.","Ja kuin hän oli paastonnut neljäkymmentä päivää ja neljäkymmentä yötä, sitte hän isosi."],[4,3,"Ja kiusaaja tuli hänen tykönsä ja sanoi: jos sinä olet Jumalan Poika, niin sano, että nämät kivet leiviksi tulevat.","Ja kiusaaja tuli hänen tykönsä ja sanoi: jos sinä olet Jumalan Poika, niin sano, että nämät kivet leiviksi tulevat."],[4,4,"Mutta hän vastasi ja sanoi: kirjoitettu on: ei ihminen elä ainoasti leivästä, mutta jokaisesta sanasta, joka Jumalan suusta lähtee.","Mutta hän vastasi ja sanoi: kirjoitettu on: ei ihminen elä ainoasti leivästä, mutta jokaisesta sanasta, joka Jumalan suusta lähtee."],[4,5,"Silloin otti perkele hänen kanssansa pyhään kaupunkiin, ja asetti hänen templin harjalle,","Silloin otti perkele hänen kanssansa pyhään kaupunkiin, ja asetti hänen templin harjalle,"],[4,6,"Ja sanoi hänelle: jos sinä olet Jumalan Poika, niin laske sinus alaspäin; sillä kirjoitettu on: hän antaa käskyn enkeleillensä sinusta, ja he käsissä kantavat sinun, ettet joskus jalkaas kiveen loukkaa.","Ja sanoi hänelle: jos sinä olet Jumalan Poika, niin laske sinus alaspäin; sillä kirjoitettu on: hän antaa käskyn enkeleillensä sinusta, ja he käsissä kantavat sinun, ettet joskus jalkaas kiveen loukkaa."],[4,7,"Niin Jesus sanoi hänelle: taas on kirjoitettu: ei sinun pidä kiusaaman Herraa sinun Jumalaas.","Niin Jesus sanoi hänelle: taas on kirjoitettu: ei sinun pidä kiusaaman Herraa sinun Jumalaas."],[4,8,"Taas vei hänen perkele sangen korkialle vuorelle, ja osoitti hänelle kaikki maailman valtakunnat ja niiden kunnian,","Taas vei hänen perkele sangen korkialle vuorelle, ja osoitti hänelle kaikki maailman valtakunnat ja niiden kunnian,"],[4,9,"Ja sanoi hänelle: nämät kaikki minä annan sinulle, jos sinä lankeat maahan ja rukoilet minua.","Ja sanoi hänelle: nämät kaikki minä annan sinulle, jos sinä lankeat maahan ja rukoilet minua."],[4,10,"Niin sanoi Jesus hänelle: mene pois, saatana! Sillä kirjoitettu on: Herraa sinun Jumalaas pitää sinun kumartaman, ja häntä ainoaa palveleman.","Niin sanoi Jesus hänelle: mene pois, saatana! Sillä kirjoitettu on: Herraa sinun Jumalaas pitää sinun kumartaman, ja häntä ainoaa palveleman."],[4,11,"Silloin jätti hänen perkele; ja katso, enkelit tulivat ja palvelivat häntä.","Silloin jätti hänen perkele; ja katso, enkelit tulivat ja palvelivat häntä."],[4,12,"Mutta kuin Jesus kuuli, että Johannes oli vankiuteen annettu ylön, poikkesi hän Galileaan,","Mutta kuin Jesus kuuli, että Johannes oli vankiuteen annettu ylön, poikkesi hän Galileaan,"],[4,13,"Ja jätti Natsaretin, tuli ja asui Kapernaumissa, joka on merikaupunki, Zebulonin ja Naphtalin äärissä;","Ja jätti Natsaretin, tuli ja asui Kapernaumissa, joka on merikaupunki, Zebulonin ja Naphtalin äärissä;"],[4,14,"Että täytettäisiin se mikä sanottu oli Jesaias prophetan kautta, joka sanoo:","Että täytettäisiin se mikä sanottu oli Jesaias prophetan kautta, joka sanoo:"],[4,15,"Zebulonin maa ja Naphtalin maa, läsnä meritietä, sillä puolella Jordanin, pakanain Galilea,","Zebulonin maa ja Naphtalin maa, läsnä meritietä, sillä puolella Jordanin, pakanain Galilea,"],[4,16,"Kansa, joka pimiässä istui, näki suuren valkeuden, ja niille, jotka kuoleman maassa ja varjossa istuivat, koitti valkeus.","Kansa, joka pimiässä istui, näki suuren valkeuden, ja niille, jotka kuoleman maassa ja varjossa istuivat, koitti valkeus."],[4,17,"Siitä ajasta rupesi Jesus saarnaamaan ja sanomaan: tehtäät parannus; sillä taivaan valtakunta lähestyi.","Siitä ajasta rupesi Jesus saarnaamaan ja sanomaan: tehtäät parannus; sillä taivaan valtakunta lähestyi."],[4,18,"Mutta kuin Jesus käveli Galilean meren tykönä, näki hän kaksi veljestä, Simonin, joka kutsutaan Pietariksi, ja Andreaksen hänen veljensä, laskevan verkkoa mereen; (Sillä he olivat kalamiehet,)","Mutta kuin Jesus käveli Galilean meren tykönä, näki hän kaksi veljestä, Simonin, joka kutsutaan Pietariksi, ja Andreaksen hänen veljensä, laskevan verkkoa mereen; (Sillä he olivat kalamiehet,)"],[4,19,"Ja sanoi heille: seuratkaat minua, ja minä teen teidät ihmisten kalamiehiksi.","Ja sanoi heille: seuratkaat minua, ja minä teen teidät ihmisten kalamiehiksi."],[4,20,"Niin he jättivät kohta verkot ja seurasivat häntä.","Niin he jättivät kohta verkot ja seurasivat häntä."],[4,21,"Ja kuin hän sieltä edemmä kävi, näki hän toiset kaksi veljestä, Jakobin Zebedeuksen pojan ja Johanneksen hänen veljensä, venheessä isänsä Zebedeuksen kanssa, parantavan verkkojansa; ja hän kutsui heitä.","Ja kuin hän sieltä edemmä kävi, näki hän toiset kaksi veljestä, Jakobin Zebedeuksen pojan ja Johanneksen hänen veljensä, venheessä isänsä Zebedeuksen kanssa, parantavan verkkojansa; ja hän kutsui heitä."],[4,22,"Niin he kohta jättivät venheen ja isänsä, ja seurasivat häntä.","Niin he kohta jättivät venheen ja isänsä, ja seurasivat häntä."],[4,23,"Ja Jesus vaelsi ympäri kaiken Galilean, ja opetti heidän synagogissansa, ja saarnasi valtakunnan evankeliumia, ja paransi kaikkinaiset taudit ja kaiken sairauden kansan seassa.","Ja Jesus vaelsi ympäri kaiken Galilean, ja opetti heidän synagogissansa, ja saarnasi valtakunnan evankeliumia, ja paransi kaikkinaiset taudit ja kaiken sairauden kansan seassa."],[4,24,"Ja sanoma kuului hänestä kaikkeen Syrian maahan. Ja he toivat hänen tykönsä kaikkinaisia sairaita, moninaisilla taudeilla ja kivuilla vaivatuita ja piruilta riivatuita, ja kuutaudillisia ja halvatuita; ja hän paransi ne.","Ja sanoma kuului hänestä kaikkeen Syrian maahan. Ja he toivat hänen tykönsä kaikkinaisia sairaita, moninaisilla taudeilla ja kivuilla vaivatuita ja piruilta riivatuita, ja kuutaudillisia ja halvatuita; ja hän paransi ne."],[4,25,"Ja häntä seurasi paljo väkeä Galileasta ja kymmenestä kaupungista, ja Jerusalemista ja Juudeasta, ja maakunnista sillä puolella Jordania.","Ja häntä seurasi paljo väkeä Galileasta ja kymmenestä kaupungista, ja Jerusalemista ja Juudeasta, ja maakunnista sillä puolella Jordania."],[5,1,"Mutta kuin hän näki kansan, astui hän ylös vuorelle, ja kuin hän oli istunut, tulivat hänen opetuslapsensa hänen tykönsä.","Mutta kuin hän näki kansan, astui hän ylös vuorelle, ja kuin hän oli istunut, tulivat hänen opetuslapsensa hänen tykönsä."],[5,2,"Niin hän avasi suunsa, opetti heitä ja sanoi:","Niin hän avasi suunsa, opetti heitä ja sanoi:"],[5,3,"Autuaat ovat hengellisesti vaivaiset; sillä heidän on taivaan valtakunta.","Autuaat ovat hengellisesti vaivaiset; sillä heidän on taivaan valtakunta."],[5,4,"Autuaat ovat murheelliset; sillä he saavat lohdutuksen.","Autuaat ovat murheelliset; sillä he saavat lohdutuksen."],[5,5,"Autuaat ovat siviät; sillä he saavat maan periä.","Autuaat ovat siviät; sillä he saavat maan periä."],[5,6,"Autuaat ovat, jotka isoovat ja janoovat vanhurskautta; sillä he ravitaan.","Autuaat ovat, jotka isoovat ja janoovat vanhurskautta; sillä he ravitaan."],[5,7,"Autuaat ovat laupiaat; sillä he saavat laupiuden.","Autuaat ovat laupiaat; sillä he saavat laupiuden."],[5,8,"Autuaat ovat puhtaat sydämestä; sillä he saavat nähdä Jumalan.","Autuaat ovat puhtaat sydämestä; sillä he saavat nähdä Jumalan."],[5,9,"Autuaat ovat rauhan tekiät; sillä ne pitää Jumalan pojiksi kutsuttaman.","Autuaat ovat rauhan tekiät; sillä ne pitää Jumalan pojiksi kutsuttaman."],[5,10,"Autuaat ovat, jotka vanhurskauden tähden vainotaan; sillä heidän on taivaan valtakunta.","Autuaat ovat, jotka vanhurskauden tähden vainotaan; sillä heidän on taivaan valtakunta."],[5,11,"Autuaat olette te, kuin he pilkkaavat ja vainoovat teitä, ja puhuvat kaikkinaista pahuutta teitä vastaan, valhetellen minun tähteni.","Autuaat olette te, kuin he pilkkaavat ja vainoovat teitä, ja puhuvat kaikkinaista pahuutta teitä vastaan, valhetellen minun tähteni."],[5,12,"Iloitkaat ja riemuitkaat; sillä teidän palkkanne on suuri taivaissa. Sillä näin he vainosivat prophetaita, jotka teidän edellänne olivat.","Iloitkaat ja riemuitkaat; sillä teidän palkkanne on suuri taivaissa. Sillä näin he vainosivat prophetaita, jotka teidän edellänne olivat."],[5,13,"Te olette maan suola: jos siis suola tulee mauttomaksi, millä sitte suolataan? ei se enään kelpaa mihinkään, vaan heitettää pois ja ihmisiltä tallattaa.","Te olette maan suola: jos siis suola tulee mauttomaksi, millä sitte suolataan? ei se enään kelpaa mihinkään, vaan heitettää pois ja ihmisiltä tallattaa."],[5,14,"Te olette maailman valkeus. Ei sitä kaupunkia taideta peittää, joka vuorella on,","Te olette maailman valkeus. Ei sitä kaupunkia taideta peittää, joka vuorella on,"],[5,15,"Eikä kynttilää sytytetä ja panna vakan alle, vaan kynttiläjalkaan, valaisemaan kaikkia, jotka huoneessa ovat.","Eikä kynttilää sytytetä ja panna vakan alle, vaan kynttiläjalkaan, valaisemaan kaikkia, jotka huoneessa ovat."],[5,16,"Näin valistakoon teidän valkeutenne ihmisten edessä, että he näkisivät teidän hyvät työnne, ja kunnioittaisivat teidän Isäänne, joka on taivaissa.","Näin valistakoon teidän valkeutenne ihmisten edessä, että he näkisivät teidän hyvät työnne, ja kunnioittaisivat teidän Isäänne, joka on taivaissa."],[5,17,"Älkäät luulko, että minä tulin lakia ja prophetaita päästämään: en minä tullut päästämään, vaan täyttämään.","Älkäät luulko, että minä tulin lakia ja prophetaita päästämään: en minä tullut päästämään, vaan täyttämään."],[5,18,"Sillä totisesti sanon minä teille: siihenasti kuin taivas ja maa katoo, ei pidä vähinkään piirto eikä joku rahtu laista katooman, siihenasti kuin kaikki tapahtuvat.","Sillä totisesti sanon minä teille: siihenasti kuin taivas ja maa katoo, ei pidä vähinkään piirto eikä joku rahtu laista katooman, siihenasti kuin kaikki tapahtuvat."],[5,19,"Kuka siis jonkun näistä vähimmistä käskyistä päästää, ja näin ihmisiä opettaa, hän pitää taivaan valtakunnassa vähimmäksi kutsuttaman; mutta joka sen tekee ja opettaa, se pitää suureksi taivaan valtakunnassa kutsuttaman.","Kuka siis jonkun näistä vähimmistä käskyistä päästää, ja näin ihmisiä opettaa, hän pitää taivaan valtakunnassa vähimmäksi kutsuttaman; mutta joka sen tekee ja opettaa, se pitää suureksi taivaan valtakunnassa kutsuttaman."],[5,20,"Sillä minä sanon teille: ellei teidän vanhurskautenne ole paljoa enempi kuin kirjanoppineiden ja Pharisealaisten, niin ette tule taivaan valtakuntaan.","Sillä minä sanon teille: ellei teidän vanhurskautenne ole paljoa enempi kuin kirjanoppineiden ja Pharisealaisten, niin ette tule taivaan valtakuntaan."],[5,21,"Te kuulitte mitä sanottu oli vanhoille: ei sinun pidä tappaman; mutta jokainen, joka tappaa, hänen pitää tuomioon vikapää oleman.","Te kuulitte mitä sanottu oli vanhoille: ei sinun pidä tappaman; mutta jokainen, joka tappaa, hänen pitää tuomioon vikapää oleman."],[5,22,"Mutta minä sanon teille: että jokainen, joka tyhmästi vihastuu veljellensä, hänen pitää tuomioon vikapää oleman; mutta jokainen, joka sanoo veljellensä: raka, hänen pitää neuvon alle vikapää oleman; mutta jokainen, joka sanoo: sinä tyhmä, hänen pitää helvetin tuleen vikapää oleman.","Mutta minä sanon teille: että jokainen, joka tyhmästi vihastuu veljellensä, hänen pitää tuomioon vikapää oleman; mutta jokainen, joka sanoo veljellensä: raka, hänen pitää neuvon alle vikapää oleman; mutta jokainen, joka sanoo: sinä tyhmä, hänen pitää helvetin tuleen vikapää oleman."],[5,23,"Sentähden, jos sinä uhraat lahjas alttarille, ja siellä muistat, että veljelläs on jotakin sinua vastaan:","Sentähden, jos sinä uhraat lahjas alttarille, ja siellä muistat, että veljelläs on jotakin sinua vastaan:"],[5,24,"Niin jätä sinne lahjas alttarin eteen, ja mene ensin sopimaan veljes kanssa, ja tule sitte lahjas uhraamaan.","Niin jätä sinne lahjas alttarin eteen, ja mene ensin sopimaan veljes kanssa, ja tule sitte lahjas uhraamaan."],[5,25,"Sovi nopiasti riitaveljes kanssa, koskas vielä hänen kanssansa tiellä olet, ettei riitaveljes anna sinua joskus tuomarille, ja tuomari antaa sinun palvelialle, ja sinä heitetään torniin.","Sovi nopiasti riitaveljes kanssa, koskas vielä hänen kanssansa tiellä olet, ettei riitaveljes anna sinua joskus tuomarille, ja tuomari antaa sinun palvelialle, ja sinä heitetään torniin."],[5,26,"Totisesti sanon minä sinulle: et sinä suinkaan pääse sieltä ulos, siihenasti kuin sinä maksat viimeisen rovon.","Totisesti sanon minä sinulle: et sinä suinkaan pääse sieltä ulos, siihenasti kuin sinä maksat viimeisen rovon."],[5,27,"Te kuulitte sanotuksi vanhoille: ei sinun pidä huorin tekemän.","Te kuulitte sanotuksi vanhoille: ei sinun pidä huorin tekemän."],[5,28,"Mutta minä sanon teille: jokainen, joka katsoo vaimon päälle himoitaksensa häntä, hän teki jo huorin hänen kanssansa sydämessänsä.","Mutta minä sanon teille: jokainen, joka katsoo vaimon päälle himoitaksensa häntä, hän teki jo huorin hänen kanssansa sydämessänsä."],[5,29,"Jos oikia silmäs pahentaa sinun, niin puhkaise se ulos, ja heitä pois tyköäs; sillä parempi on sinulle, että yksi jäsenistäs hukutetaan, kuin että koko ruumis pitäis heitettämän helvettiin.","Jos oikia silmäs pahentaa sinun, niin puhkaise se ulos, ja heitä pois tyköäs; sillä parempi on sinulle, että yksi jäsenistäs hukutetaan, kuin että koko ruumis pitäis heitettämän helvettiin."],[5,30,"Ja jos oikia kätes pahentaa sinun, niin hakkaa se poikki, ja heitä pois tyköäs! sillä parempi on sinulle, että yksi jäsenistäs hukutetaan, kuin että koko ruumis pitäis helvettiin heitettämän.","Ja jos oikia kätes pahentaa sinun, niin hakkaa se poikki, ja heitä pois tyköäs! sillä parempi on sinulle, että yksi jäsenistäs hukutetaan, kuin että koko ruumis pitäis helvettiin heitettämän."],[5,31,"On myös sanottu: jokainen joka emäntänsä hylkää, hän antakaan hänelle erokirjan.","On myös sanottu: jokainen joka emäntänsä hylkää, hän antakaan hänelle erokirjan."],[5,32,"Mutta minä sanon teille: joka emäntänsä hylkää, muutoin kuin huoruuden tähden, hän saattaa hänen huorin tekemään; ja joka nai sen hyljätyn, hän tekee huorin.","Mutta minä sanon teille: joka emäntänsä hylkää, muutoin kuin huoruuden tähden, hän saattaa hänen huorin tekemään; ja joka nai sen hyljätyn, hän tekee huorin."],[5,33,"Taas te kuulitte sanotuksi vanhoille: älä vanno väärin, vaan pidä valas Herralle.","Taas te kuulitte sanotuksi vanhoille: älä vanno väärin, vaan pidä valas Herralle."],[5,34,"Mutta minä sanon teille: älkäät ensinkään vannoko, ei taivaan kautta, sillä se on Jumalan istuin;","Mutta minä sanon teille: älkäät ensinkään vannoko, ei taivaan kautta, sillä se on Jumalan istuin;"],[5,35,"Eikä maan kautta, sillä se on hänen astinlautansa: ei myös Jerusalemin kautta, sillä se on suuren kuninkaan kaupunki:","Eikä maan kautta, sillä se on hänen astinlautansa: ei myös Jerusalemin kautta, sillä se on suuren kuninkaan kaupunki:"],[5,36,"Ei sinun myös pidä vannoman pääs kautta, sillä et sinä voi yhtään hiusta valkiaksi eli mustaksi tehdä.","Ei sinun myös pidä vannoman pääs kautta, sillä et sinä voi yhtään hiusta valkiaksi eli mustaksi tehdä."],[5,37,"Vaan teidän puheenne pitää oleman: on, on, ei, ei; mutta mitä siihen lisätään, se on pahasta.","Vaan teidän puheenne pitää oleman: on, on, ei, ei; mutta mitä siihen lisätään, se on pahasta."],[5,38,"Te kuulitte sanotuksi: silmä silmästä, ja hammas hampaasta.","Te kuulitte sanotuksi: silmä silmästä, ja hammas hampaasta."],[5,39,"Mutta minä sanon teille: älkäät olko pahaa vastaan; vaan joka sinua lyö oikialle poskelle, niin käännä myös hänelle toinen.","Mutta minä sanon teille: älkäät olko pahaa vastaan; vaan joka sinua lyö oikialle poskelle, niin käännä myös hänelle toinen."],[5,40,"Ja joka sinua tahtoo oikeuden eteen, jo ottaa hamees, niin salli myös hänelle muukin vaate.","Ja joka sinua tahtoo oikeuden eteen, jo ottaa hamees, niin salli myös hänelle muukin vaate."],[5,41,"Ja joka sinua vaatii peninkulman, mene hänen kanssansa kaksi.","Ja joka sinua vaatii peninkulman, mene hänen kanssansa kaksi."],[5,42,"Anna sille, joka sinulta anoo, ja älä käänny siltä pois, joka lainan pyytää.","Anna sille, joka sinulta anoo, ja älä käänny siltä pois, joka lainan pyytää."],[5,43,"Te kuulitte sanotuksi: rakasta lähimmäistäs, ja vihaa vihollistas;","Te kuulitte sanotuksi: rakasta lähimmäistäs, ja vihaa vihollistas;"],[5,44,"Mutta minä sanon teille: rakastakaat vihollisianne; siunatkaat niitä, jotka teitä sadattavat; tehkäät niille hyvin, jotka teitä vihaavat, ja rukoilkaat niiden edestä, jotka teitä vainoovat ja vahingoittavat,","Mutta minä sanon teille: rakastakaat vihollisianne; siunatkaat niitä, jotka teitä sadattavat; tehkäät niille hyvin, jotka teitä vihaavat, ja rukoilkaat niiden edestä, jotka teitä vainoovat ja vahingoittavat,"],[5,45,"Että te olisitte teidän Isänne pojat, joka on taivaissa; sillä hän sallii aurinkonsa koittaa niin pahain ylitse kuin hyväinkin, ja antaa sataa niin väärille kuin vanhurskaillekin.","Että te olisitte teidän Isänne pojat, joka on taivaissa; sillä hän sallii aurinkonsa koittaa niin pahain ylitse kuin hyväinkin, ja antaa sataa niin väärille kuin vanhurskaillekin."],[5,46,"Sillä jos te rakastatte niitä, jotka teitäkin rakastavat, mitä teidän siitä palkkaa on? eikö Publikanit myös niin tee?","Sillä jos te rakastatte niitä, jotka teitäkin rakastavat, mitä teidän siitä palkkaa on? eikö Publikanit myös niin tee?"],[5,47,"Ja jos te ainoastaan veljeinne kanssa soveliaat olette, mitä te sen kanssa erinomaista teette? eikö Publikanit myös niin tee?","Ja jos te ainoastaan veljeinne kanssa soveliaat olette, mitä te sen kanssa erinomaista teette? eikö Publikanit myös niin tee?"],[5,48,"Olkaat siis te täydelliset, niinkuin teidän taivaallinen Isänne täydellinen on.","Olkaat siis te täydelliset, niinkuin teidän taivaallinen Isänne täydellinen on."],[6,1,"Kavahtakaat, ettette anna almujanne ihmisten edessä, että te heiltä nähtäisiin: niin ette saa palkkaa Isältänne, joka on taivaissa.","Kavahtakaat, ettette anna almujanne ihmisten edessä, että te heiltä nähtäisiin: niin ette saa palkkaa Isältänne, joka on taivaissa."],[6,2,"Kuin siis almua annat, niin älä edelläs torvella soita, niinkuin ulkokullatut synagogissa ja kujilla tekevät, että he ihmisiltä kunnioitettaisiin. Totisesti sanon minä teille: he ovat saaneet palkkansa.","Kuin siis almua annat, niin älä edelläs torvella soita, niinkuin ulkokullatut synagogissa ja kujilla tekevät, että he ihmisiltä kunnioitettaisiin. Totisesti sanon minä teille: he ovat saaneet palkkansa."],[6,3,"Mutta kuin sinä almua annat, niin älköön vasen kätes tietäkö, mitä oikia kätes tekee,","Mutta kuin sinä almua annat, niin älköön vasen kätes tietäkö, mitä oikia kätes tekee,"],[6,4,"Että almus olis salaisuudessa, ja Isäs, joka salaisuudessa näkee, maksais sinulle julkisesti.","Että almus olis salaisuudessa, ja Isäs, joka salaisuudessa näkee, maksais sinulle julkisesti."],[6,5,"Ja kuin rukoilet, niin ei sinun pidä oleman niinkuin ulkokullatut; sillä he mielellänsä seisovat ja rukoilevat synagogissa ja kujain kulmissa, että he ihmisiltä nähtäisiin. Totisesti sanon minä teille: he ovat saaneet palkkansa.","Ja kuin rukoilet, niin ei sinun pidä oleman niinkuin ulkokullatut; sillä he mielellänsä seisovat ja rukoilevat synagogissa ja kujain kulmissa, että he ihmisiltä nähtäisiin. Totisesti sanon minä teille: he ovat saaneet palkkansa."],[6,6,"Vaan kuin sinä rukoilet, niin mene kammioos, ja sulje oves, ja rukoile Isääs, joka on salaisuudessa: ja Isäs, joka salaisuudessa näkee, maksaa sinulle julkisesti.","Vaan kuin sinä rukoilet, niin mene kammioos, ja sulje oves, ja rukoile Isääs, joka on salaisuudessa: ja Isäs, joka salaisuudessa näkee, maksaa sinulle julkisesti."],[6,7,"Ja kuin te rukoilette, niin älkää olko paljon puhuvaiset, niinkuin pakanat; sillä he luulevat heitä paljon puheensa tähden kuultavan.","Ja kuin te rukoilette, niin älkää olko paljon puhuvaiset, niinkuin pakanat; sillä he luulevat heitä paljon puheensa tähden kuultavan."],[6,8,"Sentähden älkäät olko heidän kaltaisensa; sillä Isänne tietää kyllä, mitä tarvitsette, ennen kuin te häneltä rukoilettekaan.","Sentähden älkäät olko heidän kaltaisensa; sillä Isänne tietää kyllä, mitä tarvitsette, ennen kuin te häneltä rukoilettekaan."],[6,9,"Näin teidän siis pitää rukoileman: Isä meidän, joka olet taivaissa! Pyhitetty olkoon sinun nimes.","Näin teidän siis pitää rukoileman: Isä meidän, joka olet taivaissa! Pyhitetty olkoon sinun nimes."],[6,10,"Lähestyköön sinun valtakuntas. Olkoon sinun tahtos niin maassa kuin taivaassa.","Lähestyköön sinun valtakuntas. Olkoon sinun tahtos niin maassa kuin taivaassa."],[6,11,"Anna meille tänäpäivänä meidän jokapäiväinen leipämme.","Anna meille tänäpäivänä meidän jokapäiväinen leipämme."],[6,12,"Ja anna meille meidän velkamme anteeksi, niinkuin mekin anteeksi annamme meidän velvollistemme.","Ja anna meille meidän velkamme anteeksi, niinkuin mekin anteeksi annamme meidän velvollistemme."],[6,13,"Ja älä johdata meitä kiusaukseen. Mutta päästä meitä pahasta. Sillä sinun on valtakunta, ja voima, ja kunnia, ijankaikkisesti. Amen!","Ja älä johdata meitä kiusaukseen. Mutta päästä meitä pahasta. Sillä sinun on valtakunta, ja voima, ja kunnia, ijankaikkisesti. Amen!"],[6,14,"Sillä jos te anteeksi annatte ihmisille heidän rikoksensa, niin myös teidän taivaallinen Isänne antaa teille anteeksi.","Sillä jos te anteeksi annatte ihmisille heidän rikoksensa, niin myös teidän taivaallinen Isänne antaa teille anteeksi."],[6,15,"Vaan jollette anteeksi anna ihmisille heidän rikoksiansa, niin ei myös teidän Isänne anteeksi anna teidän rikoksianne.","Vaan jollette anteeksi anna ihmisille heidän rikoksiansa, niin ei myös teidän Isänne anteeksi anna teidän rikoksianne."],[6,16,"Mutta kuin te paastootte, niin älkäät olko surulliset niinkuin ulkokullatut; sillä he muuttavat muotonsa, että he ihmisiltä nähtäisiin paastoovan. Totisesti sanon minä teille: he ovat saaneet palkkansa.","Mutta kuin te paastootte, niin älkäät olko surulliset niinkuin ulkokullatut; sillä he muuttavat muotonsa, että he ihmisiltä nähtäisiin paastoovan. Totisesti sanon minä teille: he ovat saaneet palkkansa."],[6,17,"Vaan sinä kuin paastoot, niin voitele pääs ja pese kasvos,","Vaan sinä kuin paastoot, niin voitele pääs ja pese kasvos,"],[6,18,"Ettet ihmisiltä nähtäis paastoovan, mutta Isältäs, joka on salaisuudessa: ja Isäs, joka salaisuudessa näkee, maksaa sinulle julkisesti.","Ettet ihmisiltä nähtäis paastoovan, mutta Isältäs, joka on salaisuudessa: ja Isäs, joka salaisuudessa näkee, maksaa sinulle julkisesti."],[6,19,"Älkäät tavaraa kootko maan päällä, kussa koi ja ruoste raiskaavat, ja kussa varkaat kaivavat ja varastavat;","Älkäät tavaraa kootko maan päällä, kussa koi ja ruoste raiskaavat, ja kussa varkaat kaivavat ja varastavat;"],[6,20,"Vaan kootkaat teillenne tavaraa taivaassa, kussa ei koi eikä ruoste raiskaa, ja kussa ei varkaat kaiva eikä varasta.","Vaan kootkaat teillenne tavaraa taivaassa, kussa ei koi eikä ruoste raiskaa, ja kussa ei varkaat kaiva eikä varasta."],[6,21,"Sillä kussa teidän tavaranne on, siellä on myös teidän sydämenne.","Sillä kussa teidän tavaranne on, siellä on myös teidän sydämenne."],[6,22,"Silmä on ruumin valkeus; jos siis silmäs on yksinkertainen, niin koko ruumiis on valaistu.","Silmä on ruumin valkeus; jos siis silmäs on yksinkertainen, niin koko ruumiis on valaistu."],[6,23,"Mutta jos silmäs on paha, niin koko ruumiis on pimiä. Jos siis se valkeus, joka sinussa on, on pimeys, kuinka suuri on itse pimeys?","Mutta jos silmäs on paha, niin koko ruumiis on pimiä. Jos siis se valkeus, joka sinussa on, on pimeys, kuinka suuri on itse pimeys?"],[6,24,"Ei kenkään voi palvella kahta herraa; sillä taikka hän tätä vihaa ja toista rakastaa, taikka hän tähän suostuu ja toisen ylönkatsoo. Ette voi palvella Jumalaa ja mammonaa.","Ei kenkään voi palvella kahta herraa; sillä taikka hän tätä vihaa ja toista rakastaa, taikka hän tähän suostuu ja toisen ylönkatsoo. Ette voi palvella Jumalaa ja mammonaa."],[6,25,"Sentähden sanon minä teille: älkäät murehtiko henkenne tähden, mitä te syötte ja mitä te juotte, eikä ruumiinne tähden, millä te teitänne verhootte. Eikö henki enempi ole kuin ruoka? ja ruumis parempi kuin vaate?","Sentähden sanon minä teille: älkäät murehtiko henkenne tähden, mitä te syötte ja mitä te juotte, eikä ruumiinne tähden, millä te teitänne verhootte. Eikö henki enempi ole kuin ruoka? ja ruumis parempi kuin vaate?"],[6,26,"Katsokaat taivaan lintuja, ei he kylvä eikä niitä, ei myös kokoa riiheen, ja teidän taivaallinen Isänne ruokkii heidät. Ettekö te paljoa enempi ole kuin he?","Katsokaat taivaan lintuja, ei he kylvä eikä niitä, ei myös kokoa riiheen, ja teidän taivaallinen Isänne ruokkii heidät. Ettekö te paljoa enempi ole kuin he?"],[6,27,"Mutta kuka teistä voi surullansa lisätä yhden kyynärän pituudellensa?","Mutta kuka teistä voi surullansa lisätä yhden kyynärän pituudellensa?"],[6,28,"Ja mitä te surette vaatteista? Katsokaat kukkasia kedolla, kuinka he kasvavat: ei he työtä tee, eikä kehrää.","Ja mitä te surette vaatteista? Katsokaat kukkasia kedolla, kuinka he kasvavat: ei he työtä tee, eikä kehrää."],[6,29,"Kuitenkin sanon minä teille, ettei Salomon kaikessa kunniassansa ollut niin vaatetettu kuin yksi heistä.","Kuitenkin sanon minä teille, ettei Salomon kaikessa kunniassansa ollut niin vaatetettu kuin yksi heistä."],[6,30,"Jos Jumala näin vaatettaa pellon ruohon, joka tänäpänä seisoo ja huomenna pätsiin heitetään, eikö hän paljoa enemmin teidän sitä tee, te vähäuskoiset?","Jos Jumala näin vaatettaa pellon ruohon, joka tänäpänä seisoo ja huomenna pätsiin heitetään, eikö hän paljoa enemmin teidän sitä tee, te vähäuskoiset?"],[6,31,"Älkäät siis surulliset olko, sanoen: mitä me syömme, taikka mitä me juomme? eli millä me meitämme verhoomme?","Älkäät siis surulliset olko, sanoen: mitä me syömme, taikka mitä me juomme? eli millä me meitämme verhoomme?"],[6,32,"Sillä kaikkia näitä pakanat etsivät; sillä teidän taivaallinen Isänne kyllä tietää teidän kaikkia näitä tarvitsevan.","Sillä kaikkia näitä pakanat etsivät; sillä teidän taivaallinen Isänne kyllä tietää teidän kaikkia näitä tarvitsevan."],[6,33,"Vaan etsikäät ensin Jumalan valtakuntaa ja hänen vanhurskauttansa, ja niin kaikki nämät teille annetaan.","Vaan etsikäät ensin Jumalan valtakuntaa ja hänen vanhurskauttansa, ja niin kaikki nämät teille annetaan."],[6,34,"Älkäät sentähden sureko huomisesta päivästä; sillä huomisella päivällä on suru itsestänsä. Tyytykään kukin päivä surullensa.","Älkäät sentähden sureko huomisesta päivästä; sillä huomisella päivällä on suru itsestänsä. Tyytykään kukin päivä surullensa."],[7,1,"Älkäät tuomitko, ettei teitä tuomittaisi.","Älkäät tuomitko, ettei teitä tuomittaisi."],[7,2,"Sillä millä tuomiolla te tuomitsette, pitää teitä tuomittaman, ja sillä mitalla, jolla te mittaatte, pitää teille jälleen mitattaman.","Sillä millä tuomiolla te tuomitsette, pitää teitä tuomittaman, ja sillä mitalla, jolla te mittaatte, pitää teille jälleen mitattaman."],[7,3,"Miksis siis näet raiskan, joka on veljes silmässä, ja et äkkää malkaa omassa silmässäs?","Miksis siis näet raiskan, joka on veljes silmässä, ja et äkkää malkaa omassa silmässäs?"],[7,4,"Taikka, kuinka sinä sanot veljelles: pidäs, minä otan raiskan silmästäs; ja katso, malka on omassa silmässäs?","Taikka, kuinka sinä sanot veljelles: pidäs, minä otan raiskan silmästäs; ja katso, malka on omassa silmässäs?"],[7,5,"Sinä ulkokullattu, heitä ensin malka ulos sinun silmästäs, ja katso sitte, kuinka saisit raiskan ulos veljes silmästä.","Sinä ulkokullattu, heitä ensin malka ulos sinun silmästäs, ja katso sitte, kuinka saisit raiskan ulos veljes silmästä."],[7,6,"Älkäät antako koirille pyhää, ja älkäät päärlyjänne heittäkö sikain eteen, ettei he niitä joskus tallaa jaloillansa, ja käännä itsiänsä, ja repele teitä.","Älkäät antako koirille pyhää, ja älkäät päärlyjänne heittäkö sikain eteen, ettei he niitä joskus tallaa jaloillansa, ja käännä itsiänsä, ja repele teitä."],[7,7,"Anokaat, niin teille annetaan: etsikäät, niin te löydätte: kolkuttakaat, niin teille avataan.","Anokaat, niin teille annetaan: etsikäät, niin te löydätte: kolkuttakaat, niin teille avataan."],[7,8,"Sillä jokainen, joka anoo, hän saa, ja joka etsii, hän löytää, ja kolkuttavalle avataan.","Sillä jokainen, joka anoo, hän saa, ja joka etsii, hän löytää, ja kolkuttavalle avataan."],[7,9,"Eli onko teistä joku ihminen, jolta hänen poikansa anois leipää: antaisko hän hänelle kiven?","Eli onko teistä joku ihminen, jolta hänen poikansa anois leipää: antaisko hän hänelle kiven?"],[7,10,"Eli jos hän kalaa anois: antaisko hän hänelle käärmeen?","Eli jos hän kalaa anois: antaisko hän hänelle käärmeen?"],[7,11,"Jos siis te, jotka pahat olette, taidatte hyviä lahjoja antaa teidän lapsillenne, kuinka paljoa enempi teidän Isänne, joka on taivaissa, antaa niille hyviä, jotka häneltä anovat?","Jos siis te, jotka pahat olette, taidatte hyviä lahjoja antaa teidän lapsillenne, kuinka paljoa enempi teidän Isänne, joka on taivaissa, antaa niille hyviä, jotka häneltä anovat?"],[7,12,"Kaikki siis, mitä te tahdotte, että ihmiset pitää teille tekemän, niin te myös heille tehkäät; sillä tämä on laki ja prophetat.","Kaikki siis, mitä te tahdotte, että ihmiset pitää teille tekemän, niin te myös heille tehkäät; sillä tämä on laki ja prophetat."],[7,13,"Menkäät ahtaasta portista sisälle; sillä se portti on lavia ja avara tie, joka vie kadotukseen, ja niitä on monta, jotka siitä sisälle menevät;","Menkäät ahtaasta portista sisälle; sillä se portti on lavia ja avara tie, joka vie kadotukseen, ja niitä on monta, jotka siitä sisälle menevät;"],[7,14,"Ja se portti on ahdas, ja tie kaita, joka vie elämään, ja harvat ovat, jotka sen löytävät.","Ja se portti on ahdas, ja tie kaita, joka vie elämään, ja harvat ovat, jotka sen löytävät."],[7,15,"Mutta kavahtakaat teitänne vääristä prophetaista, jotka teidän tykönne lammasten vaatteilla tulevat, mutta sisältä he ovat raatelevaiset sudet.","Mutta kavahtakaat teitänne vääristä prophetaista, jotka teidän tykönne lammasten vaatteilla tulevat, mutta sisältä he ovat raatelevaiset sudet."],[7,16,"Heidän hedelmistänsä te tunnette heidät: hakeeko joku viinamarjoja orjantappuroista, taikka fikunia ohdakkeista?","Heidän hedelmistänsä te tunnette heidät: hakeeko joku viinamarjoja orjantappuroista, taikka fikunia ohdakkeista?"],[7,17,"Niin jokainen hyvä puu kasvaa hyvät hedelmät; mutta mädännyt puu kasvaa häijyt hedelmät.","Niin jokainen hyvä puu kasvaa hyvät hedelmät; mutta mädännyt puu kasvaa häijyt hedelmät."],[7,18,"Hyvä puu ei taida häijyjä hedelmiä kasvaa, eikä mädännyt puu hyviä hedelmiä kasvaa.","Hyvä puu ei taida häijyjä hedelmiä kasvaa, eikä mädännyt puu hyviä hedelmiä kasvaa."],[7,19,"Jokainen puu, joka ei kasva hyvää hedelmää, hakataan pois, ja tuleen heitetään.","Jokainen puu, joka ei kasva hyvää hedelmää, hakataan pois, ja tuleen heitetään."],[7,20,"Sentähden tuntekaat heitä hedelmistänsä.","Sentähden tuntekaat heitä hedelmistänsä."],[7,21,"Ei jokainen, joka sanoo minulle: Herra, Herra! pidä tuleman taivaan valtakuntaan; mutta joka tekee minun isäni tahdon, joka on taivaissa.","Ei jokainen, joka sanoo minulle: Herra, Herra! pidä tuleman taivaan valtakuntaan; mutta joka tekee minun isäni tahdon, joka on taivaissa."],[7,22,"Moni sanoo minulle sinä päivänä: Herra, Herra! emmekö me sinun nimes kautta ennustaneet, ja sinun nimelläs ajaneet ulos perkeleitä, ja ole sinun nimes kautta monta väkevää työtä tehneet?","Moni sanoo minulle sinä päivänä: Herra, Herra! emmekö me sinun nimes kautta ennustaneet, ja sinun nimelläs ajaneet ulos perkeleitä, ja ole sinun nimes kautta monta väkevää työtä tehneet?"],[7,23,"Ja silloin minä tunnustan, en minä teitä ikänä tuntenut: menkäät pois minun tyköäni, te väärintekiät.","Ja silloin minä tunnustan, en minä teitä ikänä tuntenut: menkäät pois minun tyköäni, te väärintekiät."],[7,24,"Sentähden jokaisen, joka minulta nämät puheet kuulee ja ne tekee, vertaan minä toimelliseen mieheen, joka huoneensa kalliolle rakensi.","Sentähden jokaisen, joka minulta nämät puheet kuulee ja ne tekee, vertaan minä toimelliseen mieheen, joka huoneensa kalliolle rakensi."],[7,25,"Ja sade lankesi, ja virrat tulivat, ja tuulet puhalsivat, ja sitä huonetta sysäsivät, joka ei kuitenkaan kukistunut; sillä se oli kalliolle perustettu.","Ja sade lankesi, ja virrat tulivat, ja tuulet puhalsivat, ja sitä huonetta sysäsivät, joka ei kuitenkaan kukistunut; sillä se oli kalliolle perustettu."],[7,26,"Ja jokainen, joka kuulee minulta nämä puheet, ja ei tee niitä, hän verrataan tyhmään mieheen, joka huoneensa sannalle rakensi.","Ja jokainen, joka kuulee minulta nämä puheet, ja ei tee niitä, hän verrataan tyhmään mieheen, joka huoneensa sannalle rakensi."],[7,27,"Ja sade lankesi, ja virrat tulivat, ja tuulet puhalsivat, ja sitä huonetta sysäsivät, joka kukistui, ja sen lankeemus oli suuri.","Ja sade lankesi, ja virrat tulivat, ja tuulet puhalsivat, ja sitä huonetta sysäsivät, joka kukistui, ja sen lankeemus oli suuri."],[7,28,"Ja se tapahtui, kuin Jesus oli lopettanut nämät puheet, että kansat hämmästyivät hänen oppiansa.","Ja se tapahtui, kuin Jesus oli lopettanut nämät puheet, että kansat hämmästyivät hänen oppiansa."],[7,29,"Sillä hän opetti heitä voimallisesti, ja ei niinkuin kirjanoppineet.","Sillä hän opetti heitä voimallisesti, ja ei niinkuin kirjanoppineet."],[8,1,"Kuin hän astui alas vuorelta, seurasi häntä paljo kansaa.","Kuin hän astui alas vuorelta, seurasi häntä paljo kansaa."],[8,2,"Ja katso, niin tuli spitalinen mies, kumarsi häntä ja sanoi: Herra, jos sinä tahdot, niin sinä voit minun puhdistaa.","Ja katso, niin tuli spitalinen mies, kumarsi häntä ja sanoi: Herra, jos sinä tahdot, niin sinä voit minun puhdistaa."],[8,3,"Niin Jesus ojensi kätensä ja rupesi häneen, sanoen: minä tahdon, ole puhdas. Ja hän puhdistettiin kohta spitalistansa.","Niin Jesus ojensi kätensä ja rupesi häneen, sanoen: minä tahdon, ole puhdas. Ja hän puhdistettiin kohta spitalistansa."],[8,4,"Ja Jesus sanoi hänelle: katso, ettet kenellekään sano: mutta mene ja näytä itses papille, ja uhraa lahjas, jonka Moses on käskenyt, heille todistukseksi.","Ja Jesus sanoi hänelle: katso, ettet kenellekään sano: mutta mene ja näytä itses papille, ja uhraa lahjas, jonka Moses on käskenyt, heille todistukseksi."],[8,5,"Mutta kuin Jesus meni Kapernaumiin, tuli sadanpäämies hänen tykönsä, ja rukoili häntä,","Mutta kuin Jesus meni Kapernaumiin, tuli sadanpäämies hänen tykönsä, ja rukoili häntä,"],[8,6,"Ja sanoi: Herra! minun palveliani sairastaa kotona halvattuna, ja kovin vaivataan.","Ja sanoi: Herra! minun palveliani sairastaa kotona halvattuna, ja kovin vaivataan."],[8,7,"Jesus sanoi hänelle: minä tulen ja parannan hänen.","Jesus sanoi hänelle: minä tulen ja parannan hänen."],[8,8,"Niin sadanpäämies vastasi ja sanoi: Herra, en ole minä mahdollinen, että sinä tulet minun kattoni alle; vaan sano ainoasti sana, niin palveliani paranee.","Niin sadanpäämies vastasi ja sanoi: Herra, en ole minä mahdollinen, että sinä tulet minun kattoni alle; vaan sano ainoasti sana, niin palveliani paranee."],[8,9,"Sillä minä olen myös ihminen toisen vallan alla, ja minun allani on sotamiehiä, ja sanon tälle: mene! ja hän menee, ja toiselle: tule! ja hän tulee, ja palvelialleni: tee tämä! ja hän tekee.","Sillä minä olen myös ihminen toisen vallan alla, ja minun allani on sotamiehiä, ja sanon tälle: mene! ja hän menee, ja toiselle: tule! ja hän tulee, ja palvelialleni: tee tämä! ja hän tekee."],[8,10,"Kuin Jesus tämän kuuli, ihmetteli hän, ja sanoi heille, jotka seurasivat: totisesti sanon minä teille: en ole minä löytänyt senkaltaista uskoa Israelissa.","Kuin Jesus tämän kuuli, ihmetteli hän, ja sanoi heille, jotka seurasivat: totisesti sanon minä teille: en ole minä löytänyt senkaltaista uskoa Israelissa."],[8,11,"Mutta minä sanon teille: monta tulevat idästä ja lännestä, ja pitää Abrahamin, Isaakin ja Jakobin kanssa taivaan valtakunnassa istuman.","Mutta minä sanon teille: monta tulevat idästä ja lännestä, ja pitää Abrahamin, Isaakin ja Jakobin kanssa taivaan valtakunnassa istuman."],[8,12,"Mutta valtakunnan lapset heitetään ulkonaiseen pimeyteen: siellä pitää oleman itku ja hammasten kiristys.","Mutta valtakunnan lapset heitetään ulkonaiseen pimeyteen: siellä pitää oleman itku ja hammasten kiristys."],[8,13,"Ja Jesus sanoi sadanpäämiehelle: mene, ja niinkuin sinä uskoit, niin sinulle tapahtukoon. Ja sillä hetkellä parani hänen palveliansa.","Ja Jesus sanoi sadanpäämiehelle: mene, ja niinkuin sinä uskoit, niin sinulle tapahtukoon. Ja sillä hetkellä parani hänen palveliansa."],[8,14,"Ja kuin Jesus tuli Pietarin huoneeseen, näki hän hänen anoppinsa makaavan ja sairastavan vilutautia.","Ja kuin Jesus tuli Pietarin huoneeseen, näki hän hänen anoppinsa makaavan ja sairastavan vilutautia."],[8,15,"Niin hän tarttui hänen käteensä, ja vilutauti luopui hänestä. Ja hän nousi, ja palveli heitä.","Niin hän tarttui hänen käteensä, ja vilutauti luopui hänestä. Ja hän nousi, ja palveli heitä."],[8,16,"Mutta kuin ehtoo tuli, niin he toivat hänen tykönsä monta pirulta riivattua; ja hän ajoi ulos sanalla henget, ja teki kaikkinaisia sairaita terveeksi;","Mutta kuin ehtoo tuli, niin he toivat hänen tykönsä monta pirulta riivattua; ja hän ajoi ulos sanalla henget, ja teki kaikkinaisia sairaita terveeksi;"],[8,17,"Että täytettäisiin, mitä sanottu oli Jesaias prophetan kautta, joka sanoo: hän on ottanut meidän heikkoutemme, ja hän kantoi meidän tautimme.","Että täytettäisiin, mitä sanottu oli Jesaias prophetan kautta, joka sanoo: hän on ottanut meidän heikkoutemme, ja hän kantoi meidän tautimme."],[8,18,"Kuin Jesus näki paljon kansaa ympärillänsä, käski hän mennä toiselle puolelle (merta).","Kuin Jesus näki paljon kansaa ympärillänsä, käski hän mennä toiselle puolelle (merta)."],[8,19,"Ja kirjanoppinut tuli ja sanoi hänelle: Mestari, minä tahdon sinua seurata, kuhunka ikänä sinä menet.","Ja kirjanoppinut tuli ja sanoi hänelle: Mestari, minä tahdon sinua seurata, kuhunka ikänä sinä menet."],[8,20,"Niin Jesus sanoi hänelle: ketuilla ovat luolat, ja taivaan linnuilla ovat pesät; mutta Ihmisen Pojalla ei ole, kuhunka hän päänsä kallistaa.","Niin Jesus sanoi hänelle: ketuilla ovat luolat, ja taivaan linnuilla ovat pesät; mutta Ihmisen Pojalla ei ole, kuhunka hän päänsä kallistaa."],[8,21,"Toinen hänen opetuslapsistansa sanoi hänelle: Herra, salli minun ensin mennä hautaamaan isääni.","Toinen hänen opetuslapsistansa sanoi hänelle: Herra, salli minun ensin mennä hautaamaan isääni."],[8,22,"Niin Jesus sanoi hänelle: seuraa minua, ja anna kuolleet haudata kuolleitansa.","Niin Jesus sanoi hänelle: seuraa minua, ja anna kuolleet haudata kuolleitansa."],[8,23,"Ja kuin hän oli haahteen astunut, seurasivat häntä hänen opetuslapsensa.","Ja kuin hän oli haahteen astunut, seurasivat häntä hänen opetuslapsensa."],[8,24,"Mutta katso, suuri ilma nousi merellä, niin että haaksi aalloilta peitettiin. Mutta hän makasi.","Mutta katso, suuri ilma nousi merellä, niin että haaksi aalloilta peitettiin. Mutta hän makasi."],[8,25,"Niin tulivat hänen opetuslapsensa ja herättivät hänen, ja sanoivat: Herra, auta meitä, me hukumme.","Niin tulivat hänen opetuslapsensa ja herättivät hänen, ja sanoivat: Herra, auta meitä, me hukumme."],[8,26,"Ja hän sanoi heille: te heikko-uskoiset, miksi te olette pelkurit? Niin hän nousi ja asetti tuulen ja meren, ja tuli juuri tyveneksi.","Ja hän sanoi heille: te heikko-uskoiset, miksi te olette pelkurit? Niin hän nousi ja asetti tuulen ja meren, ja tuli juuri tyveneksi."],[8,27,"Niin ihmiset ihmettelivät, sanoen: millainen tämä on? sillä tuulet ja meri ovat myös hänelle kuuliaiset.","Niin ihmiset ihmettelivät, sanoen: millainen tämä on? sillä tuulet ja meri ovat myös hänelle kuuliaiset."],[8,28,"Ja kuin hän tuli sille puolelle merta, Gerasalaisten maakuntaan, niin häntä vastaan juoksi kaksi pirulta riivattua, jotka olivat haudoista lähteneet, ja olivat sangen hirmuiset, niin ettei kenkään taitanut sitä tietä vaeltaa.","Ja kuin hän tuli sille puolelle merta, Gerasalaisten maakuntaan, niin häntä vastaan juoksi kaksi pirulta riivattua, jotka olivat haudoista lähteneet, ja olivat sangen hirmuiset, niin ettei kenkään taitanut sitä tietä vaeltaa."],[8,29,"Ja katso, he huusivat sanoen: Jesus, Jumalan Poika, mitä meidän on sinun kanssas? Oletkos tullut tänne meitä vaivaamaan ennen aikaa?","Ja katso, he huusivat sanoen: Jesus, Jumalan Poika, mitä meidän on sinun kanssas? Oletkos tullut tänne meitä vaivaamaan ennen aikaa?"],[8,30,"Ja kaukana heistä kävi sangen suuri sikalauma laitumella.","Ja kaukana heistä kävi sangen suuri sikalauma laitumella."],[8,31,"Niin perkeleet rukoilivat häntä ja sanoivat: jos ajat meidät ulos, niin salli meidän mennä sikalaumaan.","Niin perkeleet rukoilivat häntä ja sanoivat: jos ajat meidät ulos, niin salli meidän mennä sikalaumaan."],[8,32,"Ja hän sanoi heille: menkäät. Niin he läksivät ulos ja menivät sikalaumaan; ja katso, koko sikalauma syöksi äkisti itsensä jyrkältä mereen ja upposi.","Ja hän sanoi heille: menkäät. Niin he läksivät ulos ja menivät sikalaumaan; ja katso, koko sikalauma syöksi äkisti itsensä jyrkältä mereen ja upposi."],[8,33,"Mutta paimenet pakenivat ja menivät kaupunkiin ja ilmoittivat kaikki, ja kuinka pirulta riivatuille oli tapahtunut.","Mutta paimenet pakenivat ja menivät kaupunkiin ja ilmoittivat kaikki, ja kuinka pirulta riivatuille oli tapahtunut."],[8,34,"Ja katso, koko kaupunki meni ulos Jesusta vastaan. Ja kuin he hänen näkivät, rukoilivat he häntä menemään pois heidän maansa ääristä.","Ja katso, koko kaupunki meni ulos Jesusta vastaan. Ja kuin he hänen näkivät, rukoilivat he häntä menemään pois heidän maansa ääristä."],[9,1,"Ja hän astui haahteen, meni jälleen ylitse ja tuli omaan kaupunkiinsa.","Ja hän astui haahteen, meni jälleen ylitse ja tuli omaan kaupunkiinsa."],[9,2,"Ja katso, he toivat hänen eteensä halvatun, joka makasi vuoteella. Ja kuin Jesus näki heidän uskonsa, sanoi hän halvatulle: poikani, ole hyvässä turvassa, syntis annetaan anteeksi sinulle.","Ja katso, he toivat hänen eteensä halvatun, joka makasi vuoteella. Ja kuin Jesus näki heidän uskonsa, sanoi hän halvatulle: poikani, ole hyvässä turvassa, syntis annetaan anteeksi sinulle."],[9,3,"Ja katso, muutamat kirjanoppineista sanoivat keskenänsä: tämä pilkkaa (Jumalaa).","Ja katso, muutamat kirjanoppineista sanoivat keskenänsä: tämä pilkkaa (Jumalaa)."],[9,4,"Ja kuin Jesus näki heidän ajatuksensa, sanoi hän: miksi ajattelette pahaa sydämessänne?","Ja kuin Jesus näki heidän ajatuksensa, sanoi hän: miksi ajattelette pahaa sydämessänne?"],[9,5,"Sillä kumpi on keviämpi sanoa: synnit annetaan anteeksi sinulle, taikka sanoa: nouse ja käy?","Sillä kumpi on keviämpi sanoa: synnit annetaan anteeksi sinulle, taikka sanoa: nouse ja käy?"],[9,6,"Mutta että teidän pitää tietämän Ihmisen Pojalla olevan vallan maan päällä synnit anteeksi antaa, (niin sanoi hän halvatulle:) nouse ja ota vuotees, ja mene kotias.","Mutta että teidän pitää tietämän Ihmisen Pojalla olevan vallan maan päällä synnit anteeksi antaa, (niin sanoi hän halvatulle:) nouse ja ota vuotees, ja mene kotias."],[9,7,"Ja hän nousi ja meni kotiansa.","Ja hän nousi ja meni kotiansa."],[9,8,"Ja kuin kansa sen näki, ihmettelivät he ja kunnioittivat Jumalaa, joka oli ihmisille antanut senkaltaisen vallan.","Ja kuin kansa sen näki, ihmettelivät he ja kunnioittivat Jumalaa, joka oli ihmisille antanut senkaltaisen vallan."],[9,9,"Ja kuin Jesus sieltä kävi ohitse, näki hän ihmisen istuvan tullihuoneessa, nimeltä Matteus, ja sanoi hänelle: seuraa minua. Niin hän nousi ja seurasi häntä.","Ja kuin Jesus sieltä kävi ohitse, näki hän ihmisen istuvan tullihuoneessa, nimeltä Matteus, ja sanoi hänelle: seuraa minua. Niin hän nousi ja seurasi häntä."],[9,10,"Ja tapahtui, kuin hän atrioitsi huoneessa, katso, niin tuli monta Publikania ja syntistä, ja atrioitsivat Jesuksen ja hänen opetuslastensa kanssa.","Ja tapahtui, kuin hän atrioitsi huoneessa, katso, niin tuli monta Publikania ja syntistä, ja atrioitsivat Jesuksen ja hänen opetuslastensa kanssa."],[9,11,"Ja kuin Pharisealaiset sen näkivät, sanoivat he hänen opetuslapsillensa: miksi teidän Mestarinne syö Publikanien ja syntisten kanssa?","Ja kuin Pharisealaiset sen näkivät, sanoivat he hänen opetuslapsillensa: miksi teidän Mestarinne syö Publikanien ja syntisten kanssa?"],[9,12,"Mutta kuin Jesus sen kuuli, sanoi hän heille: ei terve tarvitse parantajaa, vaan sairaat.","Mutta kuin Jesus sen kuuli, sanoi hän heille: ei terve tarvitse parantajaa, vaan sairaat."],[9,13,"Mutta menkäät ja oppikaat, mikä se on: laupiutta minä tahdon, enkä uhria; sillä en minä tullut vanhurskaita kutsumaan, vaan syntisiä parannukseen.","Mutta menkäät ja oppikaat, mikä se on: laupiutta minä tahdon, enkä uhria; sillä en minä tullut vanhurskaita kutsumaan, vaan syntisiä parannukseen."],[9,14,"Silloin tulivat Johanneksen opetuslapset hänen tykönsä, ja sanoivat: minkätähden me ja Pharisealaiset niin paljo paastoomme, mutta ei sinun opetuslapses paastoo?","Silloin tulivat Johanneksen opetuslapset hänen tykönsä, ja sanoivat: minkätähden me ja Pharisealaiset niin paljo paastoomme, mutta ei sinun opetuslapses paastoo?"],[9,15,"Niin Jesus sanoi heille: taitaako hääjoukko niinkauvan murehtia, kuin ylkä on heidän kanssansa? mutta päivät tulevat, että ylkä otetaan heiltä pois, ja silloin heidän pitää paastooman.","Niin Jesus sanoi heille: taitaako hääjoukko niinkauvan murehtia, kuin ylkä on heidän kanssansa? mutta päivät tulevat, että ylkä otetaan heiltä pois, ja silloin heidän pitää paastooman."],[9,16,"Mutta ei kenkään paikkaa vanhaa vaatetta uuden veran tilalla; sillä paikka repee pois vaatteesta, ja läpi tulee pahemmaksi.","Mutta ei kenkään paikkaa vanhaa vaatetta uuden veran tilalla; sillä paikka repee pois vaatteesta, ja läpi tulee pahemmaksi."],[9,17,"Ei myös pane kenkään nuorta viinaa vanhoihin leileihin; muutoin leilit pakahtuvat, ja viina vuotaa pois, ja leilit turmellaan; vaan nuorta viinaa lasketaan uusiin leileihin, ja niin he molemmat tähdellä ovat.","Ei myös pane kenkään nuorta viinaa vanhoihin leileihin; muutoin leilit pakahtuvat, ja viina vuotaa pois, ja leilit turmellaan; vaan nuorta viinaa lasketaan uusiin leileihin, ja niin he molemmat tähdellä ovat."],[9,18,"Kuin hän nämät heille puhunut oli, katso, niin päämies tuli ja kumarsi häntä, sanoen: nyt on minun tyttäreni kuolemallansa; mutta tule ja pane kätes hänen päällensä, niin hän virkoaa.","Kuin hän nämät heille puhunut oli, katso, niin päämies tuli ja kumarsi häntä, sanoen: nyt on minun tyttäreni kuolemallansa; mutta tule ja pane kätes hänen päällensä, niin hän virkoaa."],[9,19,"Niin Jesus nousi ja seurasi häntä, ja hänen opetuslapsensa.","Niin Jesus nousi ja seurasi häntä, ja hänen opetuslapsensa."],[9,20,"Ja katso, vaimo, joka oli kaksitoistakymmentä ajastaikaa punaista tautia sairastanut, kävi takana, ja tarttui hänen vaatteensa liepeeseen;","Ja katso, vaimo, joka oli kaksitoistakymmentä ajastaikaa punaista tautia sairastanut, kävi takana, ja tarttui hänen vaatteensa liepeeseen;"],[9,21,"Sillä hän oli itsellensä sanonut; jos minä ainoastaan rupeen hänen vaatteesensa, niin minä tulen terveeksi.","Sillä hän oli itsellensä sanonut; jos minä ainoastaan rupeen hänen vaatteesensa, niin minä tulen terveeksi."],[9,22,"Niin Jesus käänsi itsensä, näki hänen ja sanoi: ole hyvässä turvassa, tyttäreni! sinun uskos on sinun terveeksi tehnyt. Ja vaimo tuli sillä hetkellä terveeksi.","Niin Jesus käänsi itsensä, näki hänen ja sanoi: ole hyvässä turvassa, tyttäreni! sinun uskos on sinun terveeksi tehnyt. Ja vaimo tuli sillä hetkellä terveeksi."],[9,23,"Ja kuin Jesus tuli päämiehen huoneeseen, ja näki pillein soittajat ja kansan hymisevän,","Ja kuin Jesus tuli päämiehen huoneeseen, ja näki pillein soittajat ja kansan hymisevän,"],[9,24,"Sanoi hän heille: menkäät pois; sillä ei piika ole kuollut, vaan hän makaa. Ja he nauroivat häntä.","Sanoi hän heille: menkäät pois; sillä ei piika ole kuollut, vaan hän makaa. Ja he nauroivat häntä."],[9,25,"Mutta kuin kansa oli ajettu ulos, meni hän sisälle ja tarttui hänen käteensä, ja piika nousi.","Mutta kuin kansa oli ajettu ulos, meni hän sisälle ja tarttui hänen käteensä, ja piika nousi."],[9,26,"Ja sen sanoma kuului kaikkeen siihen maahan.","Ja sen sanoma kuului kaikkeen siihen maahan."],[9,27,"Ja kuin Jesus sieltä läksi, seurasi häntä kaksi sokiaa, huutain ja sanoen: Davidin poika, armahda meitä.","Ja kuin Jesus sieltä läksi, seurasi häntä kaksi sokiaa, huutain ja sanoen: Davidin poika, armahda meitä."],[9,28,"Ja kuin hän tuli huoneeseen, tulivat sokiat hänen tykönsä, ja Jesus sanoi heille: uskotteko minun sen voivan teille tehdä? He sanoivat hänelle: Herra, me uskomme.","Ja kuin hän tuli huoneeseen, tulivat sokiat hänen tykönsä, ja Jesus sanoi heille: uskotteko minun sen voivan teille tehdä? He sanoivat hänelle: Herra, me uskomme."],[9,29,"Niin hän rupesi heidän silmiinsä, sanoen: tapahtukoon teille uskonne jälkeen.","Niin hän rupesi heidän silmiinsä, sanoen: tapahtukoon teille uskonne jälkeen."],[9,30,"Ja heidän silmänsä aukenivat. Niin Jesus haastoi heitä, sanoen: katsokaat, ettei kenkään saa tätä tietää.","Ja heidän silmänsä aukenivat. Niin Jesus haastoi heitä, sanoen: katsokaat, ettei kenkään saa tätä tietää."],[9,31,"Vaan kuin he menivät pois, niin he julistivat hänen sanomansa kaikessa siinä maassa.","Vaan kuin he menivät pois, niin he julistivat hänen sanomansa kaikessa siinä maassa."],[9,32,"Kuin nämät olivat menneet ulos, katso, niin he toivat mykän ja pirulta riivatun ihmisen hänen eteensä.","Kuin nämät olivat menneet ulos, katso, niin he toivat mykän ja pirulta riivatun ihmisen hänen eteensä."],[9,33,"Ja kuin perkele oli ajettu ulos, niin mykkä puhui. Ja kansa ihmetteli ja sanoi: ei senkaltaista ole ikänä Israelissa nähty.","Ja kuin perkele oli ajettu ulos, niin mykkä puhui. Ja kansa ihmetteli ja sanoi: ei senkaltaista ole ikänä Israelissa nähty."],[9,34,"Mutta Pharisealaiset sanoivat: hän ajaa ulos perkeleet perkeleitten pääruhtinasten kautta.","Mutta Pharisealaiset sanoivat: hän ajaa ulos perkeleet perkeleitten pääruhtinasten kautta."],[9,35,"Ja Jesus kävi kaikkia kaupungeita ja kyliä ympäri, ja opetti heidän synagogissansa, ja saarnasi valtakunnan evankeliumia, ja paransi kaikkinaisia tauteja ja kaikkea sairautta kansassa.","Ja Jesus kävi kaikkia kaupungeita ja kyliä ympäri, ja opetti heidän synagogissansa, ja saarnasi valtakunnan evankeliumia, ja paransi kaikkinaisia tauteja ja kaikkea sairautta kansassa."],[9,36,"Ja kuin hän näki kansat, armahti hän heidän päällensä, että he olivat niin nääntyneet ja hajoitetut kuin lampaat, joilla ei ole paimenta.","Ja kuin hän näki kansat, armahti hän heidän päällensä, että he olivat niin nääntyneet ja hajoitetut kuin lampaat, joilla ei ole paimenta."],[9,37,"Silloin hän sanoi opetuslapsillensa: eloa on tosin paljo, mutta työväkeä on vähä.","Silloin hän sanoi opetuslapsillensa: eloa on tosin paljo, mutta työväkeä on vähä."],[9,38,"Rukoilkaat sentähden elon Herraa, että hän työväkeä lähettäis eloonsa.","Rukoilkaat sentähden elon Herraa, että hän työväkeä lähettäis eloonsa."],[10,1,"Ja hän kutsui tykönsä kaksitoistakymmentä opetuslastansa, ja antoi heille vallan riettaisia henkiä vastaan, niitä ajaa ulos, ja parantaa kaikkinaisia tauteja ja kaikkea sairautta.","Ja hän kutsui tykönsä kaksitoistakymmentä opetuslastansa, ja antoi heille vallan riettaisia henkiä vastaan, niitä ajaa ulos, ja parantaa kaikkinaisia tauteja ja kaikkea sairautta."],[10,2,"Mutta nämät ovat kahdentoistakymmenen apostolin nimet: ensimmäinen Simon, joka Pietariksi kutsutaan, ja Andreas, hänen veljensä, Jakobus Zebedeuksen poika, ja Johannes, hänen veljensä,","Mutta nämät ovat kahdentoistakymmenen apostolin nimet: ensimmäinen Simon, joka Pietariksi kutsutaan, ja Andreas, hänen veljensä, Jakobus Zebedeuksen poika, ja Johannes, hänen veljensä,"],[10,3,"Philippus ja Bartolomeus, Tomas ja Matteus, Publikani, Jakobus Alpheuksen poika, ja Lebbeus, liialta nimeltä Taddeus,","Philippus ja Bartolomeus, Tomas ja Matteus, Publikani, Jakobus Alpheuksen poika, ja Lebbeus, liialta nimeltä Taddeus,"],[10,4,"Simon Kananeus ja Juudas Iskariot, joka myös hänen petti.","Simon Kananeus ja Juudas Iskariot, joka myös hänen petti."],[10,5,"Nämät kaksitoistakymmentä lähetti Jesus, joille hän oli käskenyt, sanoen: älkäät menkö pakanain teille, ja Samarialaisten kaupunkiin älkäät sisälle menkö;","Nämät kaksitoistakymmentä lähetti Jesus, joille hän oli käskenyt, sanoen: älkäät menkö pakanain teille, ja Samarialaisten kaupunkiin älkäät sisälle menkö;"],[10,6,"Mutta menkäät paremmin kadotettuin lammasten tykö Israelin huoneesta.","Mutta menkäät paremmin kadotettuin lammasten tykö Israelin huoneesta."],[10,7,"Niin menkäät ja saarnatkaat, sanoen: taivaan valtakunta on lähestynyt.","Niin menkäät ja saarnatkaat, sanoen: taivaan valtakunta on lähestynyt."],[10,8,"Sairaita parantakaat, spitalisia puhdistakaat, kuolleita herättäkäät, perkeleitä ajakaat ulos. Lahjaksi te saitte, niin myös lahjaksi antakaat.","Sairaita parantakaat, spitalisia puhdistakaat, kuolleita herättäkäät, perkeleitä ajakaat ulos. Lahjaksi te saitte, niin myös lahjaksi antakaat."],[10,9,"Ei teidän pidä varustaman itsiänne kullalla eikä hopialla, eikä vaskella teidän vyöllenne,","Ei teidän pidä varustaman itsiänne kullalla eikä hopialla, eikä vaskella teidän vyöllenne,"],[10,10,"Eikä evässäkillä matkalle, eikä kahdella hameella, eikä kengillä, eikä sauvalla; sillä työmies on ruokansa ansainnut.","Eikä evässäkillä matkalle, eikä kahdella hameella, eikä kengillä, eikä sauvalla; sillä työmies on ruokansa ansainnut."],[10,11,"Vaan kuhunka ikänä kaupunkiin taikka kylään te sisälle menette, niin kyselkäät, kuka siinä on mahdollinen, ja olkaat siellä siihenasti kuin te lähdette.","Vaan kuhunka ikänä kaupunkiin taikka kylään te sisälle menette, niin kyselkäät, kuka siinä on mahdollinen, ja olkaat siellä siihenasti kuin te lähdette."],[10,12,"Mutta kuin te huoneeseen sisälle menette, niin tervehtikäät sitä (ja sanokaat: rauha olkoon tälle huoneelle!)","Mutta kuin te huoneeseen sisälle menette, niin tervehtikäät sitä (ja sanokaat: rauha olkoon tälle huoneelle!)"],[10,13,"Ja jos huone on mahdollinen, niin tulkaan teidän rauhanne hänelle; jollei hän ole mahdollinen, niin teidän rauhanne teille palajaa.","Ja jos huone on mahdollinen, niin tulkaan teidän rauhanne hänelle; jollei hän ole mahdollinen, niin teidän rauhanne teille palajaa."],[10,14,"Ja kussa ei kenkään ota teitä vastaan eikä kuule teidän sanojanne, niin menkäät ulos siitä huoneesta taikka siitä kaupungista, ja puhdistakaat tomu jaloistanne.","Ja kussa ei kenkään ota teitä vastaan eikä kuule teidän sanojanne, niin menkäät ulos siitä huoneesta taikka siitä kaupungista, ja puhdistakaat tomu jaloistanne."],[10,15,"Totisesti sanon minä teille: huokeampi pitää oleman Sodoman ja Gomorran maalle tuomiopäivänä kuin sille kaupungille.","Totisesti sanon minä teille: huokeampi pitää oleman Sodoman ja Gomorran maalle tuomiopäivänä kuin sille kaupungille."],[10,16,"Katso, minä lähetän teidät niinkuin lampaat sutten keskelle: olkaat sentähden taitavat niinkuin käärmeet, ja vakaat niinkuin kyyhkyiset.","Katso, minä lähetän teidät niinkuin lampaat sutten keskelle: olkaat sentähden taitavat niinkuin käärmeet, ja vakaat niinkuin kyyhkyiset."],[10,17,"Mutta kavahtakaat ihmisiä; sillä he ylönantavat teidät raastupiinsa, ja synagogissansa he hosuvat teitä.","Mutta kavahtakaat ihmisiä; sillä he ylönantavat teidät raastupiinsa, ja synagogissansa he hosuvat teitä."],[10,18,"Te viedään myös päämiesten ja kuningasten eteen minun tähteni, heille ja pakanoille todistukseksi.","Te viedään myös päämiesten ja kuningasten eteen minun tähteni, heille ja pakanoille todistukseksi."],[10,19,"Kuin he teitä ylönantavat, älkäät murehtiko, kuinka eli mitä teidän pitää puhuman; sillä teille annetaan sillä hetkellä, mitä teidän pitää puhuman.","Kuin he teitä ylönantavat, älkäät murehtiko, kuinka eli mitä teidän pitää puhuman; sillä teille annetaan sillä hetkellä, mitä teidän pitää puhuman."],[10,20,"Sillä ette te ole, jotka puhutte, vaan teidän Isänne Henki, joka teissä puhuu.","Sillä ette te ole, jotka puhutte, vaan teidän Isänne Henki, joka teissä puhuu."],[10,21,"Mutta veli antaa ylön veljensä kuolemaan, ja isä pojan, ja lapset karkaavat vanhempia vastaan, ja antavat tappaa heitä,","Mutta veli antaa ylön veljensä kuolemaan, ja isä pojan, ja lapset karkaavat vanhempia vastaan, ja antavat tappaa heitä,"],[10,22,"Ja te tulette vihattavaksi kaikilta minun nimeni tähden. Mutta joka loppuun asti vahvana pysyy, hän tulee autuaaksi.","Ja te tulette vihattavaksi kaikilta minun nimeni tähden. Mutta joka loppuun asti vahvana pysyy, hän tulee autuaaksi."],[10,23,"Mutta koska he teitä siinä kaupungissa vainoovat, niin paetkaat toiseen. Totisesti sanon minä teille: ette ehdi kaikkia Israelin kaupungeita toimittaa, siihenasti kuin Ihmisen Poika tulee.","Mutta koska he teitä siinä kaupungissa vainoovat, niin paetkaat toiseen. Totisesti sanon minä teille: ette ehdi kaikkia Israelin kaupungeita toimittaa, siihenasti kuin Ihmisen Poika tulee."],[10,24,"Ei ole opetuslapsi parempi opettajaansa, eikä palvelia parempi isäntäänsä.","Ei ole opetuslapsi parempi opettajaansa, eikä palvelia parempi isäntäänsä."],[10,25,"Siinä on opetuslapselle kyllä, että hän on niinkuin hänen opettajansa, ja palvelia niinkuin hänen isäntänsä. Jos he ovat itse isännän beelsebubiksi kutsuneet, kuinka paljoa ennemmin he hänen perheensä kutsuvat?","Siinä on opetuslapselle kyllä, että hän on niinkuin hänen opettajansa, ja palvelia niinkuin hänen isäntänsä. Jos he ovat itse isännän beelsebubiksi kutsuneet, kuinka paljoa ennemmin he hänen perheensä kutsuvat?"],[10,26,"Älkäät sentähden heitä peljätkö; sillä ei ole mitään peitetty, joka ei pidä ilmoitettaman, ja salattu, joka ei tule tiettäväksi.","Älkäät sentähden heitä peljätkö; sillä ei ole mitään peitetty, joka ei pidä ilmoitettaman, ja salattu, joka ei tule tiettäväksi."],[10,27,"Jota minä teille pimeissä sanon, sitä sanokaat valkeudessa, ja mitä te korvissanne kuulette, sitä saarnatkaat kattoin päällä.","Jota minä teille pimeissä sanon, sitä sanokaat valkeudessa, ja mitä te korvissanne kuulette, sitä saarnatkaat kattoin päällä."],[10,28,"Ja älkäät peljätkö niitä, jotka ruumiin tappavat, ja ei voi sielua tappaa; mutta peljätkäät enemmin sitä, joka voi sekä sielun että ruumiin helvetissä hukuttaa.","Ja älkäät peljätkö niitä, jotka ruumiin tappavat, ja ei voi sielua tappaa; mutta peljätkäät enemmin sitä, joka voi sekä sielun että ruumiin helvetissä hukuttaa."],[10,29,"Eikö kaksi varpusta yhteen ropoon myydä? ja yksi heistä ei putoo maan päälle ilman teidän Isättänne;","Eikö kaksi varpusta yhteen ropoon myydä? ja yksi heistä ei putoo maan päälle ilman teidän Isättänne;"],[10,30,"Niin ovat myös kaikki teidän päänne hiukset luetut.","Niin ovat myös kaikki teidän päänne hiukset luetut."],[10,31,"Älkäät siis peljätkö: te olette paremmat, kuin monta varpusta.","Älkäät siis peljätkö: te olette paremmat, kuin monta varpusta."],[10,32,"Sentähden jokainen joka minun tunnustaa ihmisten edessä, sen tunnustan myös minä Isäni edessä, joka on taivaissa.","Sentähden jokainen joka minun tunnustaa ihmisten edessä, sen tunnustan myös minä Isäni edessä, joka on taivaissa."],[10,33,"Mutta joka minun kieltää ihmisten edessä, hänen minä myös kiellän Isäni edessä, joka on taivaissa.","Mutta joka minun kieltää ihmisten edessä, hänen minä myös kiellän Isäni edessä, joka on taivaissa."],[10,34,"Älkäät luulko, että minä olen tullut rauhaa lähettämään maan päälle: en ole minä tullut rauhaa, vaan miekkaa lähettämään.","Älkäät luulko, että minä olen tullut rauhaa lähettämään maan päälle: en ole minä tullut rauhaa, vaan miekkaa lähettämään."],[10,35,"Sillä minä tulin ihmistä isäänsä vastaan riitaiseksi tekemään, ja tytärtä äitiänsä vastaan ja miniää anoppiansa vastaan.","Sillä minä tulin ihmistä isäänsä vastaan riitaiseksi tekemään, ja tytärtä äitiänsä vastaan ja miniää anoppiansa vastaan."],[10,36,"Ja ihmisen vihamiehet on hänen perheensä.","Ja ihmisen vihamiehet on hänen perheensä."],[10,37,"Joka rakastaa isäänsä taikka äitiänsä enempi kuin minua, ei se ole minulle sovelias; joka rakastaa poikaansa taikka tytärtänsä enempi kuin minua, ei se ole minulle sovelias.","Joka rakastaa isäänsä taikka äitiänsä enempi kuin minua, ei se ole minulle sovelias; joka rakastaa poikaansa taikka tytärtänsä enempi kuin minua, ei se ole minulle sovelias."],[10,38,"Ja kuka ei ota ristiänsä ja seuraa minua, ei se ole minulle sovelias;","Ja kuka ei ota ristiänsä ja seuraa minua, ei se ole minulle sovelias;"],[10,39,"Joka löytää henkensä, hänen pitää sen hukuttaman, ja joka henkensä hukuttaa minun tähteni, hänen pitää sen löytämän.","Joka löytää henkensä, hänen pitää sen hukuttaman, ja joka henkensä hukuttaa minun tähteni, hänen pitää sen löytämän."],[10,40,"Joka teitä holhoo, hän holhoo minua, ja joka minua holhoo, hän holhoo sitä, joka minun lähetti.","Joka teitä holhoo, hän holhoo minua, ja joka minua holhoo, hän holhoo sitä, joka minun lähetti."],[10,41,"Joka prophetaa holhoo prophetan nimellä, hän saa prophetan palkan, ja joka vanhurskasta holhoo vanhurskaan nimellä, hän saa vanhurskaan palkan.","Joka prophetaa holhoo prophetan nimellä, hän saa prophetan palkan, ja joka vanhurskasta holhoo vanhurskaan nimellä, hän saa vanhurskaan palkan."],[10,42,"Ja kuka ikänä juottaa yhden näistä vähimmistä kylmällä vesipikarilla ainoastaan, opetuslapsen nimellä, totisesti sanon minä teille: ei hän pidä palkatta oleman.","Ja kuka ikänä juottaa yhden näistä vähimmistä kylmällä vesipikarilla ainoastaan, opetuslapsen nimellä, totisesti sanon minä teille: ei hän pidä palkatta oleman."],[11,1,"Ja tapahtui, kuin Jesus lakkasi senkaltaisia kahdelletoistakymmenelle opetuslapsellensa käskemästä, meni hän sieltä edemmä opettamaan ja saarnaamaan heidän kaupunkeihinsa.","Ja tapahtui, kuin Jesus lakkasi senkaltaisia kahdelletoistakymmenelle opetuslapsellensa käskemästä, meni hän sieltä edemmä opettamaan ja saarnaamaan heidän kaupunkeihinsa."],[11,2,"Mutta kuin Johannes vankiudessa kuuli Kristuksen työt, lähetti hän kaksi opetuslastansa,","Mutta kuin Johannes vankiudessa kuuli Kristuksen työt, lähetti hän kaksi opetuslastansa,"],[11,3,"Sanomaan hänelle: oletko sinä se tuleva, eli pitääkö meidän toista odottaman?","Sanomaan hänelle: oletko sinä se tuleva, eli pitääkö meidän toista odottaman?"],[11,4,"Niin Jesus vastasi ja sanoi heille: menkäät ja sanokaat jälleen Johannekselle, ne mitkä te kuulette ja näette:","Niin Jesus vastasi ja sanoi heille: menkäät ja sanokaat jälleen Johannekselle, ne mitkä te kuulette ja näette:"],[11,5,"Sokiat saavat näkönsä, ja ontuvat käyvät, spitaliset puhdistetaan, ja kuurot kuulevat, kuolleet herätetään, ja köyhille saarnataan evankeliumi,","Sokiat saavat näkönsä, ja ontuvat käyvät, spitaliset puhdistetaan, ja kuurot kuulevat, kuolleet herätetään, ja köyhille saarnataan evankeliumi,"],[11,6,"Ja autuas on se, joka ei pahene minusta.","Ja autuas on se, joka ei pahene minusta."],[11,7,"Kuin he menivät pois, rupesi Jesus sanomaan kansalle Johanneksesta: mitä te läksitte korpeen katsomaan? ruokoako, joka tuulelta häälytetään?","Kuin he menivät pois, rupesi Jesus sanomaan kansalle Johanneksesta: mitä te läksitte korpeen katsomaan? ruokoako, joka tuulelta häälytetään?"],[11,8,"Taikka mitä te läksitte katsomaan? ihmistäkö, vaatetettua pehmeillä vaatteilla? Katso, jotka pehmeitä kantavat, ne ovat kuningasten huoneissa.","Taikka mitä te läksitte katsomaan? ihmistäkö, vaatetettua pehmeillä vaatteilla? Katso, jotka pehmeitä kantavat, ne ovat kuningasten huoneissa."],[11,9,"Taikka mitä te läksitte katsomaan? Prophetaako? totisesti sanon minä teille: tämä on jalompi kuin propheta.","Taikka mitä te läksitte katsomaan? Prophetaako? totisesti sanon minä teille: tämä on jalompi kuin propheta."],[11,10,"Sillä tämä on se, josta kirjoitettu on: katso, minä lähetän enkelini sinun kasvois eteen, joka on valmistava sinun ties sinun etees.","Sillä tämä on se, josta kirjoitettu on: katso, minä lähetän enkelini sinun kasvois eteen, joka on valmistava sinun ties sinun etees."],[11,11,"Totisesti sanon minä teille: kaikkein niiden seassa, jotka vaimoista syntyneet ovat, ei ole yhtäkään suurempaa kuin Johannes Kastaja tullut; mutta kuitenkin se, joka vähin on taivaan valtakunnassa, on häntä suurempi.","Totisesti sanon minä teille: kaikkein niiden seassa, jotka vaimoista syntyneet ovat, ei ole yhtäkään suurempaa kuin Johannes Kastaja tullut; mutta kuitenkin se, joka vähin on taivaan valtakunnassa, on häntä suurempi."],[11,12,"Mutta hamasta Johannes Kastajan päivistä, niin tähän asti, kärsii taivaan valtakunta väkivaltaa, ja väkevät repivät sen itsellensä.","Mutta hamasta Johannes Kastajan päivistä, niin tähän asti, kärsii taivaan valtakunta väkivaltaa, ja väkevät repivät sen itsellensä."],[11,13,"Sillä kaikki prophetat ja laki ovat Johannekseen asti ennustaneet.","Sillä kaikki prophetat ja laki ovat Johannekseen asti ennustaneet."],[11,14,"Ja jos te tahdotte ottaa vastaan: hän on se Elias, joka tuleva on.","Ja jos te tahdotte ottaa vastaan: hän on se Elias, joka tuleva on."],[11,15,"Jolla on korvat kuulla, se kuulkaan!","Jolla on korvat kuulla, se kuulkaan!"],[11,16,"Vaan minkä verraksi minä tämän sukukunnan vedän? hän on lasten vertainen, jotka turulla istuvat ja huutavat kumppaneillensa,","Vaan minkä verraksi minä tämän sukukunnan vedän? hän on lasten vertainen, jotka turulla istuvat ja huutavat kumppaneillensa,"],[11,17,"Ja sanovat: me soitimme huilua teidän edessänne, ja ette hypänneet: me olemme veisanneet teille murhevirsiä, ja ette itkeneet.","Ja sanovat: me soitimme huilua teidän edessänne, ja ette hypänneet: me olemme veisanneet teille murhevirsiä, ja ette itkeneet."],[11,18,"Sillä Johannes tuli ei syöden eikä juoden, ja he sanovat: hänellä on perkele.","Sillä Johannes tuli ei syöden eikä juoden, ja he sanovat: hänellä on perkele."],[11,19,"Ihmisen Poika tuli syöden ja juoden, ja he sanovat: katso ihmistä, syömäriä ja viinan juomaria, Publikanein ja syntisten ystävää. Mutta viisaus vanhurskautetaan lapsiltansa.","Ihmisen Poika tuli syöden ja juoden, ja he sanovat: katso ihmistä, syömäriä ja viinan juomaria, Publikanein ja syntisten ystävää. Mutta viisaus vanhurskautetaan lapsiltansa."],[11,20,"Silloin hän rupesi soimaamaan niitä kaupungeita, joissa olivat tehdyt usiammat hänen väkevät työnsä, ettei he itsiänsä parantaneet.","Silloin hän rupesi soimaamaan niitä kaupungeita, joissa olivat tehdyt usiammat hänen väkevät työnsä, ettei he itsiänsä parantaneet."],[11,21,"Voi sinuas Koratsin, voi sinus Betsaida! Jos senkaltaiset väkevät työt olisivät tehdyt Tyrossa ja Sidonissa kuin teissä tehdyt ovat, niin he olisivat aikaa säkissä ja tuhassa tehneet parannuksen.","Voi sinuas Koratsin, voi sinus Betsaida! Jos senkaltaiset väkevät työt olisivät tehdyt Tyrossa ja Sidonissa kuin teissä tehdyt ovat, niin he olisivat aikaa säkissä ja tuhassa tehneet parannuksen."],[11,22,"Jonka tähden sanon minä teille: Tyrolle ja Sidonille pitää oleman huokiamman tuomiopäivänä kuin teille.","Jonka tähden sanon minä teille: Tyrolle ja Sidonille pitää oleman huokiamman tuomiopäivänä kuin teille."],[11,23,"Ja sinä Kapernaum, joka olet korotettu taivaaseen asti! sinä pitää hamaan helvettiin sysättämän; sillä jos Sodomassa olisivat senkaltaiset väkevät työt tehdyt kuin sinussa, niin he vielä tänäpänä seisoisivat.","Ja sinä Kapernaum, joka olet korotettu taivaaseen asti! sinä pitää hamaan helvettiin sysättämän; sillä jos Sodomassa olisivat senkaltaiset väkevät työt tehdyt kuin sinussa, niin he vielä tänäpänä seisoisivat."],[11,24,"Jonka tähden sanon minä teille: Sodoman maalle pitää huokiamman oleman tuomiopäivänä kuin sinulle.","Jonka tähden sanon minä teille: Sodoman maalle pitää huokiamman oleman tuomiopäivänä kuin sinulle."],[11,25,"Sillä ajalla vastasi Jesus ja sanoi: minä kiitän sinua, Isä, taivaan ja maan Herra, ettäs olet kätkenyt nämät viisailta ja toimellisilta, ja olet ne ilmoittanut pienille.","Sillä ajalla vastasi Jesus ja sanoi: minä kiitän sinua, Isä, taivaan ja maan Herra, ettäs olet kätkenyt nämät viisailta ja toimellisilta, ja olet ne ilmoittanut pienille."],[11,26,"Tosin Isä, sillä niin oli sinun hyvä tahtos.","Tosin Isä, sillä niin oli sinun hyvä tahtos."],[11,27,"Kaikki ovat minulle annetut minun Isältäni, ja ei kenkään tunne Poikaa, mutta Isä; eikä Isää tunne yksikään, mutta Poika, ja kenelle ikänä Poika tahtoo sen ilmoittaa.","Kaikki ovat minulle annetut minun Isältäni, ja ei kenkään tunne Poikaa, mutta Isä; eikä Isää tunne yksikään, mutta Poika, ja kenelle ikänä Poika tahtoo sen ilmoittaa."],[11,28,"Tulkaat minun tyköni kaikki, jotka työtä teette ja olette raskautetut, ja minä tahdon teitä virvoittaa.","Tulkaat minun tyköni kaikki, jotka työtä teette ja olette raskautetut, ja minä tahdon teitä virvoittaa."],[11,29,"Ottakaat minun ikeeni teidän päällenne, ja oppikaat minusta, että minä olen siviä ja nöyrä sydämestä: ja te löydätte levon teidän sieluillenne;","Ottakaat minun ikeeni teidän päällenne, ja oppikaat minusta, että minä olen siviä ja nöyrä sydämestä: ja te löydätte levon teidän sieluillenne;"],[11,30,"Sillä minun ikeeni on sovelias ja minun kuormani on keviä.","Sillä minun ikeeni on sovelias ja minun kuormani on keviä."],[12,1,"Siihen aikaan kävi Jesus sabbatina laihoin lävitse; niin hänen opetuslapsensa isosivat, ja rupesivat tähkäpäitä noukkimaan ja syömään.","Siihen aikaan kävi Jesus sabbatina laihoin lävitse; niin hänen opetuslapsensa isosivat, ja rupesivat tähkäpäitä noukkimaan ja syömään."],[12,2,"Mutta kuin Pharisealaiset sen näkivät, sanoivat he hänelle: katso, sinun opetuslapses tekevät sitä, mitä ei sovi sabbatina tehdä.","Mutta kuin Pharisealaiset sen näkivät, sanoivat he hänelle: katso, sinun opetuslapses tekevät sitä, mitä ei sovi sabbatina tehdä."],[12,3,"Mutta hän sanoi heille: ettekö te ole lukeneet, mitä David teki, kuin hän isosi, ja ne, jotka hänen kanssansa olivat?","Mutta hän sanoi heille: ettekö te ole lukeneet, mitä David teki, kuin hän isosi, ja ne, jotka hänen kanssansa olivat?"],[12,4,"Kuinka hän meni Jumalan huoneeseen, ja söi näkyleivät, joita ei hänen sopinut syödä, eikä niidenkään, jotka hänen kanssansa olivat, mutta ainoastaan pappein?","Kuinka hän meni Jumalan huoneeseen, ja söi näkyleivät, joita ei hänen sopinut syödä, eikä niidenkään, jotka hänen kanssansa olivat, mutta ainoastaan pappein?"],[12,5,"Taikka ettekö te laissa ole lukeneet, että papit sabbatina rikkovat templissä sabbatin, ja ovat kuitenkin nuhteettomat?","Taikka ettekö te laissa ole lukeneet, että papit sabbatina rikkovat templissä sabbatin, ja ovat kuitenkin nuhteettomat?"],[12,6,"Mutta minä sanon teille: tässä on se, joka on suurempi kuin templi.","Mutta minä sanon teille: tässä on se, joka on suurempi kuin templi."],[12,7,"Mutta jos te tietäisitte, mikä se on: laupiutta minä tahdon, ja en uhria, sitte ette suinkaan tuomitsisi viattomia.","Mutta jos te tietäisitte, mikä se on: laupiutta minä tahdon, ja en uhria, sitte ette suinkaan tuomitsisi viattomia."],[12,8,"Sillä Ihmisen Poika on myös sabbatin Herra.","Sillä Ihmisen Poika on myös sabbatin Herra."],[12,9,"Ja hän läksi sieltä, ja tuli heidän synagogaansa.","Ja hän läksi sieltä, ja tuli heidän synagogaansa."],[12,10,"Ja katso, siellä oli ihminen, jolla oli kuivettunut käsi. Ja he kysyivät häneltä, sanoen: sopiiko sabbatina parantaa? että he olisivat saaneet kantaa hänen päällensä.","Ja katso, siellä oli ihminen, jolla oli kuivettunut käsi. Ja he kysyivät häneltä, sanoen: sopiiko sabbatina parantaa? että he olisivat saaneet kantaa hänen päällensä."],[12,11,"Niin hän sanoi heille: kuka on teistä ihminen, jolla olis yksi lammas, ja jos se sabbatina putoais kaivoon, eikö hän tarttuisi siihen ja vetäisi ylös?","Niin hän sanoi heille: kuka on teistä ihminen, jolla olis yksi lammas, ja jos se sabbatina putoais kaivoon, eikö hän tarttuisi siihen ja vetäisi ylös?"],[12,12,"Kuinka paljoa jalompi on ihminen kuin lammas? Sentähden sopii kyllä sabbatina hyvää tehdä.","Kuinka paljoa jalompi on ihminen kuin lammas? Sentähden sopii kyllä sabbatina hyvää tehdä."],[12,13,"Niin hän sanoi sille ihmiselle: ojenna kätes! ja hän ojensi, ja se tuli terveeksi niinkuin toinenkin.","Niin hän sanoi sille ihmiselle: ojenna kätes! ja hän ojensi, ja se tuli terveeksi niinkuin toinenkin."],[12,14,"Mutta Pharisealaiset menivät ja neuvoa pitivät häntä vastaan, kuinka he hänen hukuttaisivat.","Mutta Pharisealaiset menivät ja neuvoa pitivät häntä vastaan, kuinka he hänen hukuttaisivat."],[12,15,"Mutta kuin Jesus sen ymmärsi, meni hän sieltä pois, ja paljo kansaa seurasi häntä, ja hän teki kaikki terveeksi.","Mutta kuin Jesus sen ymmärsi, meni hän sieltä pois, ja paljo kansaa seurasi häntä, ja hän teki kaikki terveeksi."],[12,16,"Ja hän haastoi heitä, häntä ilmoittamasta,","Ja hän haastoi heitä, häntä ilmoittamasta,"],[12,17,"Että täytettäisiin, mitä sanottu oli Jesaias prophetan kautta, joka sanoo:","Että täytettäisiin, mitä sanottu oli Jesaias prophetan kautta, joka sanoo:"],[12,18,"Katso, minun palveliani, jonka minä valitsin, minun rakkaani, johonka minun sieluni mielistyi: minä panen hänen päällensä minun henkeni, ja hänen pitää tuomion pakanoille julistaman.","Katso, minun palveliani, jonka minä valitsin, minun rakkaani, johonka minun sieluni mielistyi: minä panen hänen päällensä minun henkeni, ja hänen pitää tuomion pakanoille julistaman."],[12,19,"Ei hän riitele eikä huuda, eikä yhdenkään pidä kuuleman hänen ääntänsä kujilla.","Ei hän riitele eikä huuda, eikä yhdenkään pidä kuuleman hänen ääntänsä kujilla."],[12,20,"Särjettyä ruokoa ei hänen pidä murentaman ja suitsuvaista kynttilän sydäntä ei hänen pidä sammuttaman, siihenasti kuin hän saattaa tuomion voitoksi,","Särjettyä ruokoa ei hänen pidä murentaman ja suitsuvaista kynttilän sydäntä ei hänen pidä sammuttaman, siihenasti kuin hän saattaa tuomion voitoksi,"],[12,21,"Ja hänen nimensä päälle pitää pakanain toivoman.","Ja hänen nimensä päälle pitää pakanain toivoman."],[12,22,"Silloin tuotiin hänen tykönsä pirulta riivattu, sokia ja mykkä; ja hän paransi hänen, niin että sokia ja mykkä sekä puhui että näki.","Silloin tuotiin hänen tykönsä pirulta riivattu, sokia ja mykkä; ja hän paransi hänen, niin että sokia ja mykkä sekä puhui että näki."],[12,23,"Ja kaikki kansa hämmästyi ja sanoi: olleeko tämä se Davidin poika?","Ja kaikki kansa hämmästyi ja sanoi: olleeko tämä se Davidin poika?"],[12,24,"Mutta kuin Pharisealaiset sen kuulivat, sanoivat he: ei tämä aja ulos perkeleitä, vaan beelsebubin, perkeleitten päämiehen, kautta.","Mutta kuin Pharisealaiset sen kuulivat, sanoivat he: ei tämä aja ulos perkeleitä, vaan beelsebubin, perkeleitten päämiehen, kautta."],[12,25,"Mutta kuin Jesus tiesi heidän ajatuksensa, sanoi hän heille: jokainen valtakunta, itsiänsä vastaan erinnyt, tulee kylmille, ja jokainen kaupunki taikka huone, itsiänsä vastaan erinnyt, ei seiso.","Mutta kuin Jesus tiesi heidän ajatuksensa, sanoi hän heille: jokainen valtakunta, itsiänsä vastaan erinnyt, tulee kylmille, ja jokainen kaupunki taikka huone, itsiänsä vastaan erinnyt, ei seiso."],[12,26,"Ja jos saatana ajaa ulos saatanan, niin hän on erinnyt itsiänsä vastaan: kuinka siis hänen valtakuntansa seisois?","Ja jos saatana ajaa ulos saatanan, niin hän on erinnyt itsiänsä vastaan: kuinka siis hänen valtakuntansa seisois?"],[12,27,"Ja jos minä beelsebubin kautta ajaisin perkeleitä ulos, kenenkä kautta siis poikanne ajavat niitä ulos? Sentähden pitää heidän oleman teidän tuomarinne.","Ja jos minä beelsebubin kautta ajaisin perkeleitä ulos, kenenkä kautta siis poikanne ajavat niitä ulos? Sentähden pitää heidän oleman teidän tuomarinne."],[12,28,"Mutta jos minä ajan ulos perkeleitä Jumalan Hengellä, niin Jumalan valtakunta tuli teidän tykönne.","Mutta jos minä ajan ulos perkeleitä Jumalan Hengellä, niin Jumalan valtakunta tuli teidän tykönne."],[12,29,"Taikka kuinka joku taitaa jonkun väkevän huoneeseen mennä, ja hänen kaluansa ryöstää, ellei hän ensin sido väkevää, ja sitte ryöstä hänen huonettansa?","Taikka kuinka joku taitaa jonkun väkevän huoneeseen mennä, ja hänen kaluansa ryöstää, ellei hän ensin sido väkevää, ja sitte ryöstä hänen huonettansa?"],[12,30,"Joka ei ole minun kanssani, hän on minua vastaan, ja joka ei minun kanssani kokoo, hän hajoittaa.","Joka ei ole minun kanssani, hän on minua vastaan, ja joka ei minun kanssani kokoo, hän hajoittaa."],[12,31,"Sentähden sanon minä teille: kaikki synnit ja pilkka annetaan ihmisille anteeksi; mutta pilkkaa Henkeä vastaan ei anteeksi anneta ihmisille.","Sentähden sanon minä teille: kaikki synnit ja pilkka annetaan ihmisille anteeksi; mutta pilkkaa Henkeä vastaan ei anteeksi anneta ihmisille."],[12,32,"Ja kuka ikänä sanoo jonkun sanan Ihmisen Poikaa vastaan, se hänelle anteeksi annetaan; mutta joka sanoo jotakin Pyhää Henkeä vastaan, ei sitä hänelle anteeksi anneta, ei tässä eikä tulevaisessa maailmassa.","Ja kuka ikänä sanoo jonkun sanan Ihmisen Poikaa vastaan, se hänelle anteeksi annetaan; mutta joka sanoo jotakin Pyhää Henkeä vastaan, ei sitä hänelle anteeksi anneta, ei tässä eikä tulevaisessa maailmassa."],[12,33,"Taikka tehkäät hyvä puu, niin hänen hedelmänsä tulee hyväksi, taikka tehkäät mädännyt puu, niin hänen hedelmänsä tulee mädänneeksi; sillä hedelmästä puu tunnetaan.","Taikka tehkäät hyvä puu, niin hänen hedelmänsä tulee hyväksi, taikka tehkäät mädännyt puu, niin hänen hedelmänsä tulee mädänneeksi; sillä hedelmästä puu tunnetaan."],[12,34,"Te kyykärmetten sikiät, kuinka te taidatte hyvää puhua, koska te itse pahat olette? sillä sydämen kyllyydestä suu puhuu.","Te kyykärmetten sikiät, kuinka te taidatte hyvää puhua, koska te itse pahat olette? sillä sydämen kyllyydestä suu puhuu."],[12,35,"Hyvä ihminen tuo edes hyvästä sydämen tavarasta hyviä, ja paha ihminen tuo edes pahasta tavarasta pahoja.","Hyvä ihminen tuo edes hyvästä sydämen tavarasta hyviä, ja paha ihminen tuo edes pahasta tavarasta pahoja."],[12,36,"Mutta minä sanon teille: jokaisesta turhasta sanasta, jonka ihmiset puhuvat, pitää heidän luvun tekemän tuomiopäivänä;","Mutta minä sanon teille: jokaisesta turhasta sanasta, jonka ihmiset puhuvat, pitää heidän luvun tekemän tuomiopäivänä;"],[12,37,"Sillä sanoistas sinä hurskaaksi tehdään, ja sanoistas sinä tuomitaan.","Sillä sanoistas sinä hurskaaksi tehdään, ja sanoistas sinä tuomitaan."],[12,38,"Silloin vastasivat muutamat kirjanoppineista ja Pharisealaisista, sanoen: Mestari, me tahdomme nähdä sinulta merkkiä.","Silloin vastasivat muutamat kirjanoppineista ja Pharisealaisista, sanoen: Mestari, me tahdomme nähdä sinulta merkkiä."],[12,39,"Niin hän vastasi ja sanoi heille: tämä häijy ja huorintekiä suku etsii merkkiä, ja ei hänelle pidä merkkiä annettaman, vaan Jonan prophetan merkki.","Niin hän vastasi ja sanoi heille: tämä häijy ja huorintekiä suku etsii merkkiä, ja ei hänelle pidä merkkiä annettaman, vaan Jonan prophetan merkki."],[12,40,"Sillä niinkuin Jona oli valaskalan vatsassa kolme päivää ja kolme yötä, niin pitää myös Ihmisen Pojan maan sydämessä kolme päivää ja kolme yötä oleman.","Sillä niinkuin Jona oli valaskalan vatsassa kolme päivää ja kolme yötä, niin pitää myös Ihmisen Pojan maan sydämessä kolme päivää ja kolme yötä oleman."],[12,41,"Niniven miehet pitää nouseman tuomiolle tämän suvun kanssa ja hänen tuomitseman; sillä he paransivat heitänsä Jonan saarnasta. Ja katso, tässä on enempi kuin Jona.","Niniven miehet pitää nouseman tuomiolle tämän suvun kanssa ja hänen tuomitseman; sillä he paransivat heitänsä Jonan saarnasta. Ja katso, tässä on enempi kuin Jona."],[12,42,"Etelän kuningatar on nouseva tuomiolle tämän suvun kanssa ja hänen tuomitseva; sillä hän tuli maan ääristä kuulemaan Salomonin viisautta. Ja katso, tässä on enempi kuin Salomon.","Etelän kuningatar on nouseva tuomiolle tämän suvun kanssa ja hänen tuomitseva; sillä hän tuli maan ääristä kuulemaan Salomonin viisautta. Ja katso, tässä on enempi kuin Salomon."],[12,43,"Mutta kuin rietas henki on lähtenyt ihmisestä, niin hän vaeltaa lävitse kuivia paikkoja, etsein lepoa, ja ei löydä.","Mutta kuin rietas henki on lähtenyt ihmisestä, niin hän vaeltaa lävitse kuivia paikkoja, etsein lepoa, ja ei löydä."],[12,44,"Silloin hän sanoo: minä palajan jälleen minun huoneeseeni, kusta minä läksin. Ja kuin hän tulee, niin hän löytää sen tyhjäksi, käväistyksi ja kaunistetuksi.","Silloin hän sanoo: minä palajan jälleen minun huoneeseeni, kusta minä läksin. Ja kuin hän tulee, niin hän löytää sen tyhjäksi, käväistyksi ja kaunistetuksi."],[12,45,"Silloin hän menee ja ottaa kanssansa seitsemän muuta henkeä, itseänsä pahempaa, ja ne sisälle menevät ja asuvat siellä, ja sen ihmisen viimeiset tulevat pahemmaksi kuin ensimäiset. Näin myös tapahtuu tälle pahalle sukukunnalle.","Silloin hän menee ja ottaa kanssansa seitsemän muuta henkeä, itseänsä pahempaa, ja ne sisälle menevät ja asuvat siellä, ja sen ihmisen viimeiset tulevat pahemmaksi kuin ensimäiset. Näin myös tapahtuu tälle pahalle sukukunnalle."],[12,46,"Kuin hän vielä kansalle puhui, katso, hänen äitinsä ja veljensä seisoivat ulkona ja pyysivät häntä puhutella.","Kuin hän vielä kansalle puhui, katso, hänen äitinsä ja veljensä seisoivat ulkona ja pyysivät häntä puhutella."],[12,47,"Niin yksi sanoi hänelle: katso, äitis ja veljes seisovat ulkona, ja tahtovat sinua puhutella.","Niin yksi sanoi hänelle: katso, äitis ja veljes seisovat ulkona, ja tahtovat sinua puhutella."],[12,48,"Niin hän vastasi ja sanoi sille, joka hänelle sitä sanoi: kuka on minun äitini ja kutka ovat minun veljeni?","Niin hän vastasi ja sanoi sille, joka hänelle sitä sanoi: kuka on minun äitini ja kutka ovat minun veljeni?"],[12,49,"Ja hän ojensi kätensä opetuslastensa puoleen ja sanoi: minun äitini ja minun veljeni.","Ja hän ojensi kätensä opetuslastensa puoleen ja sanoi: minun äitini ja minun veljeni."],[12,50,"Sillä jokainen, joka tekee Isäni tahdon, joka on taivaissa, hän on minun veljeni, ja sisareni, ja äitini.","Sillä jokainen, joka tekee Isäni tahdon, joka on taivaissa, hän on minun veljeni, ja sisareni, ja äitini."],[13,1,"Mutta sinä päivänä läksi Jesus huoneesta ja istui meren tykönä.","Mutta sinä päivänä läksi Jesus huoneesta ja istui meren tykönä."],[13,2,"Ja hänen tykönsä kokoontui paljo kansaa, niin että hän meni haahteen, ja istui: ja kaikki kansa seisoi rannalla.","Ja hänen tykönsä kokoontui paljo kansaa, niin että hän meni haahteen, ja istui: ja kaikki kansa seisoi rannalla."],[13,3,"Ja hän puhui heille paljon vertauksilla, sanoen: katso, kylväjä meni kylvämään.","Ja hän puhui heille paljon vertauksilla, sanoen: katso, kylväjä meni kylvämään."],[13,4,"Ja hänen kylväissänsä lankesivat muutamat tien oheen, ja linnut tulivat ja söivät ne.","Ja hänen kylväissänsä lankesivat muutamat tien oheen, ja linnut tulivat ja söivät ne."],[13,5,"Muutamat taas lankesivat kivistöön, kussa ei heillä ollut paljo maata, ja nousivat pian päälle, ettei heillä ollut syvää maata;","Muutamat taas lankesivat kivistöön, kussa ei heillä ollut paljo maata, ja nousivat pian päälle, ettei heillä ollut syvää maata;"],[13,6,"Mutta kuin aurinko nousi, niin he poudittiin, ja ettei heillä ollut juurta, niin he kuivettuivat.","Mutta kuin aurinko nousi, niin he poudittiin, ja ettei heillä ollut juurta, niin he kuivettuivat."],[13,7,"Mutta muutamat lankesivat orjantappuroihin, ja orjantappurat kävivät ylös, ja tukahuttivat ne.","Mutta muutamat lankesivat orjantappuroihin, ja orjantappurat kävivät ylös, ja tukahuttivat ne."],[13,8,"Muutamat taas lankesivat hyvään maahan, ja tekivät hedelmän, muutama satakertaisen, muutama kuudenkymmenen kertaisen ja muutama kolmenkymmenen kertaisen.","Muutamat taas lankesivat hyvään maahan, ja tekivät hedelmän, muutama satakertaisen, muutama kuudenkymmenen kertaisen ja muutama kolmenkymmenen kertaisen."],[13,9,"Jolla on korvat kuulla, se kuulkaan!","Jolla on korvat kuulla, se kuulkaan!"],[13,10,"Niin opetuslapset tulivat ja sanoivat hänelle: miksi sinä puhut heille vertauksilla?","Niin opetuslapset tulivat ja sanoivat hänelle: miksi sinä puhut heille vertauksilla?"],[13,11,"Mutta hän vastasi ja sanoi: teille on annettu tuta taivaan valtakunnan salaisuudet, vaan ei heille ole annettu.","Mutta hän vastasi ja sanoi: teille on annettu tuta taivaan valtakunnan salaisuudet, vaan ei heille ole annettu."],[13,12,"Sillä jolla on, hänelle pitää annettaman, ja hänellä pitää kyllä oleman; mutta siltä, jolla ei ole, pitää sekin otettaman pois, mikä hänellä on.","Sillä jolla on, hänelle pitää annettaman, ja hänellä pitää kyllä oleman; mutta siltä, jolla ei ole, pitää sekin otettaman pois, mikä hänellä on."],[13,13,"Sentähden minä puhun heille vertauksilla, ettei he nähden näe, eikä kuullen kuule, ei myös ymmärrä.","Sentähden minä puhun heille vertauksilla, ettei he nähden näe, eikä kuullen kuule, ei myös ymmärrä."],[13,14,"Ja heissä täytetään Jesaiaan ennustus, joka sanoo: korvillanne pitää teidän kuuleman, ja ei ymmärtämän, ja nähden näkemän, ja ei äkkäämän.","Ja heissä täytetään Jesaiaan ennustus, joka sanoo: korvillanne pitää teidän kuuleman, ja ei ymmärtämän, ja nähden näkemän, ja ei äkkäämän."],[13,15,"Sillä tämän kansan sydän on kovettunut, ja he korvillansa työläästi kuulivat, ja silmänsä panivat umpeen, ettei he joskus näkisi silmillänsä, ja kuulisi korvillansa, ja ymmärtäisi sydämellänsä, ja palajaisivat, ja minä parantaisin heitä.","Sillä tämän kansan sydän on kovettunut, ja he korvillansa työläästi kuulivat, ja silmänsä panivat umpeen, ettei he joskus näkisi silmillänsä, ja kuulisi korvillansa, ja ymmärtäisi sydämellänsä, ja palajaisivat, ja minä parantaisin heitä."],[13,16,"Mutta autuaat ovat teidän silmänne, sillä he näkevät, ja teidän korvanne, sillä he kuulevat.","Mutta autuaat ovat teidän silmänne, sillä he näkevät, ja teidän korvanne, sillä he kuulevat."],[13,17,"Sillä totisesti sanon minä teille: monta prophetaa ja vanhurskasta pyysi nähdä, joita te näette, ja ei nähneet, ja kuulla, joita te kuulette, ja ei kuulleet.","Sillä totisesti sanon minä teille: monta prophetaa ja vanhurskasta pyysi nähdä, joita te näette, ja ei nähneet, ja kuulla, joita te kuulette, ja ei kuulleet."],[13,18,"Niin kuulkaat siis te kylväjän vertaus:","Niin kuulkaat siis te kylväjän vertaus:"],[13,19,"Kuin joku kuulee valtakunnan sanan ja ei ymmärrä, niin tulee pahuus ja tempaa pois sen mikä hänen sydämeensä kylvettiin. Tämä on se, joka tien oheen oli kylvetty.","Kuin joku kuulee valtakunnan sanan ja ei ymmärrä, niin tulee pahuus ja tempaa pois sen mikä hänen sydämeensä kylvettiin. Tämä on se, joka tien oheen oli kylvetty."],[13,20,"Mutta kivistöön kylvetty on se, joka kuulee sanan, ja kohta ilolla sen vastaan ottaa;","Mutta kivistöön kylvetty on se, joka kuulee sanan, ja kohta ilolla sen vastaan ottaa;"],[13,21,"Mutta ei ole hänellä juurta itsessänsä, vaan ajan pysyy: kuin siis vaiva eli vaino tulee sanan tähden, niin hän kohta pahenee.","Mutta ei ole hänellä juurta itsessänsä, vaan ajan pysyy: kuin siis vaiva eli vaino tulee sanan tähden, niin hän kohta pahenee."],[13,22,"Mutta orjantappurain sekaan kylvetty on se, joka sanan kuulee; ja tämän mailman suru ja rikkauden petos tukahuttaa sanan, ja hän tulee hedelmättömäksi.","Mutta orjantappurain sekaan kylvetty on se, joka sanan kuulee; ja tämän mailman suru ja rikkauden petos tukahuttaa sanan, ja hän tulee hedelmättömäksi."],[13,23,"Mutta hyvään maahan kylvetty on se, joka kuulee sanan ja ymmärtää, joka tosin tuottaa hedelmän ja tekee, muutama satakertaisen, muutama kuudenkymmenen kertaisen, muutama kolmenkymmenen kertaisen.","Mutta hyvään maahan kylvetty on se, joka kuulee sanan ja ymmärtää, joka tosin tuottaa hedelmän ja tekee, muutama satakertaisen, muutama kuudenkymmenen kertaisen, muutama kolmenkymmenen kertaisen."],[13,24,"Toisen vertauksen pani hän heidän eteensä, sanoen: taivaan valtakunta on ihmisen vertainen, joka kylvi hyvän siemenen peltoonsa.","Toisen vertauksen pani hän heidän eteensä, sanoen: taivaan valtakunta on ihmisen vertainen, joka kylvi hyvän siemenen peltoonsa."],[13,25,"Mutta ihmisten maatessa tuli hänen vihollisensa ja kylvi ohdakkeita nisuin sekaan, ja meni pois.","Mutta ihmisten maatessa tuli hänen vihollisensa ja kylvi ohdakkeita nisuin sekaan, ja meni pois."],[13,26,"Mutta kuin oras rupesi kasvamaan ja hedelmän kantoi, silloin näkyivät myös ohdakkeet.","Mutta kuin oras rupesi kasvamaan ja hedelmän kantoi, silloin näkyivät myös ohdakkeet."],[13,27,"Mutta perheen isännän palvelijat tulivat ja sanoivat hänelle: Herra, etkös hyvää siementä kylvänyt peltoos? kusta siis sillä on ohdakkeet?","Mutta perheen isännän palvelijat tulivat ja sanoivat hänelle: Herra, etkös hyvää siementä kylvänyt peltoos? kusta siis sillä on ohdakkeet?"],[13,28,"Niin sanoi hän heille: vihamies sen teki. Mutta palveliat sanoivat hänelle: tahdotkos, että me menemme ja kokoomme ne?","Niin sanoi hän heille: vihamies sen teki. Mutta palveliat sanoivat hänelle: tahdotkos, että me menemme ja kokoomme ne?"],[13,29,"Mutta hän sanoi: en, ettette ohdakkeita kootessanne myös tempaisi ynnä heidän kanssansa nisuja pois.","Mutta hän sanoi: en, ettette ohdakkeita kootessanne myös tempaisi ynnä heidän kanssansa nisuja pois."],[13,30,"Sallikaat molemmat kasvaa elon-aikaan asti; ja elon-ajalla sanon minä elomiehille: kootkaat ensin ohdakkeet, ja sitokaat heitä lyhteisiin poltettaa, mutta nisut kootkaat minun aittaani.","Sallikaat molemmat kasvaa elon-aikaan asti; ja elon-ajalla sanon minä elomiehille: kootkaat ensin ohdakkeet, ja sitokaat heitä lyhteisiin poltettaa, mutta nisut kootkaat minun aittaani."],[13,31,"Toisen vertauksen pani hän heidän eteensä, sanoen: taivaan valtakunta on sinapin siemenen vertainen, jonka ihminen otti ja kylvi peltoonsa;","Toisen vertauksen pani hän heidän eteensä, sanoen: taivaan valtakunta on sinapin siemenen vertainen, jonka ihminen otti ja kylvi peltoonsa;"],[13,32,"Joka on pienin kaikkia siemeniä, mutta kuin se kasvanut on, niin hän on suurin kaalein seassa, ja tulee puuksi, niin että taivaan linnut tulevat ja tekevät pesänsä sen oksille.","Joka on pienin kaikkia siemeniä, mutta kuin se kasvanut on, niin hän on suurin kaalein seassa, ja tulee puuksi, niin että taivaan linnut tulevat ja tekevät pesänsä sen oksille."],[13,33,"Toisen vertauksen sanoi hän heille: taivaan valtakunta on hapatuksen vertainen, jonka vaimo otti, ja sekoitti kolmeen vakkaan jauhoja, siihen asti kuin kaikki happani.","Toisen vertauksen sanoi hän heille: taivaan valtakunta on hapatuksen vertainen, jonka vaimo otti, ja sekoitti kolmeen vakkaan jauhoja, siihen asti kuin kaikki happani."],[13,34,"Nämät kaikki puhui Jesus kansalle vertauksilla, ja ilman vertauksia ei hän mitään puhunut heille,","Nämät kaikki puhui Jesus kansalle vertauksilla, ja ilman vertauksia ei hän mitään puhunut heille,"],[13,35,"Että täytettäisiin mitä oli prophetan kautta sanottu, joka sanoo: minä avaan suuni vertauksiin ja puhun ulos salatut maailman alusta.","Että täytettäisiin mitä oli prophetan kautta sanottu, joka sanoo: minä avaan suuni vertauksiin ja puhun ulos salatut maailman alusta."],[13,36,"Silloin laski Jesus kansan menemään, ja tuli kotia. Ja hänen opetuslapsensa tulivat hänen tykönsä, sanoen: selitä meille sen vertaus pellon ohdakkeista.","Silloin laski Jesus kansan menemään, ja tuli kotia. Ja hänen opetuslapsensa tulivat hänen tykönsä, sanoen: selitä meille sen vertaus pellon ohdakkeista."],[13,37,"Niin hän vastasi ja sanoi heille: joka kylvää hyvän siemenen, se on Ihmisen Poika.","Niin hän vastasi ja sanoi heille: joka kylvää hyvän siemenen, se on Ihmisen Poika."],[13,38,"Mutta pelto on maailma; vaan hyvä siemen, ne ovat valtakunnan lapset; mutta ohdakkeet ovat pahan lapset.","Mutta pelto on maailma; vaan hyvä siemen, ne ovat valtakunnan lapset; mutta ohdakkeet ovat pahan lapset."],[13,39,"Vihollinen, joka ne kylvi, on perkele; elonaika on maailman loppu; mutta elomiehet ovat enkelit.","Vihollinen, joka ne kylvi, on perkele; elonaika on maailman loppu; mutta elomiehet ovat enkelit."],[13,40,"Niinkuin siis ohdakkeet haetaan kokoon ja tulella poltetaan, niin pitää myös tämän maailman lopulla oleman.","Niinkuin siis ohdakkeet haetaan kokoon ja tulella poltetaan, niin pitää myös tämän maailman lopulla oleman."],[13,41,"Ihmisen Poika lähettää enkelinsä, ja heidän pitää kokooman hänen valtakunnastansa kaikki pahennukset, ja ne jotka vääryyttä tekevät,","Ihmisen Poika lähettää enkelinsä, ja heidän pitää kokooman hänen valtakunnastansa kaikki pahennukset, ja ne jotka vääryyttä tekevät,"],[13,42,"Ja heittävät heidät tuliseen pätsiin: siellä pitää oleman itku ja hammasten kiristys.","Ja heittävät heidät tuliseen pätsiin: siellä pitää oleman itku ja hammasten kiristys."],[13,43,"Silloin pitää vanhurskaat kiiltämän niinkuin aurinko isänsä valtakunnassa. Jolla on korvat kuulla, se kuulkaan!","Silloin pitää vanhurskaat kiiltämän niinkuin aurinko isänsä valtakunnassa. Jolla on korvat kuulla, se kuulkaan!"],[13,44,"Taas on taivaan valtakunta tavaran vertainen, joka on peltoon kätketty, jonka ihminen löysi, ja kätki sen: ja ilon tähden, mikä hänellä siitä oli, meni hän pois ja myi kaikki mitä hänellä oli ja osti sen pellon.","Taas on taivaan valtakunta tavaran vertainen, joka on peltoon kätketty, jonka ihminen löysi, ja kätki sen: ja ilon tähden, mikä hänellä siitä oli, meni hän pois ja myi kaikki mitä hänellä oli ja osti sen pellon."],[13,45,"Taas on taivaan valtakunta kauppamiehen vertainen, joka etsi hyviä päärlyjä.","Taas on taivaan valtakunta kauppamiehen vertainen, joka etsi hyviä päärlyjä."],[13,46,"Ja kuin hän löysi yhden kalliin päärlyn, meni hän pois, myi kaikki, mitä hänellä oli, ja osti sen.","Ja kuin hän löysi yhden kalliin päärlyn, meni hän pois, myi kaikki, mitä hänellä oli, ja osti sen."],[13,47,"Taas on taivaan valtakunta verkon vertainen, joka on mereen heitetty, ja kaikenlaisia kokosi.","Taas on taivaan valtakunta verkon vertainen, joka on mereen heitetty, ja kaikenlaisia kokosi."],[13,48,"Kuin se täyteen tuli, vetivät he sen rannalle, ja istuivat ja eroittivat hyvät astioihinsa, mutta mädänneet he heittivät pois.","Kuin se täyteen tuli, vetivät he sen rannalle, ja istuivat ja eroittivat hyvät astioihinsa, mutta mädänneet he heittivät pois."],[13,49,"Näin on tapahtuva maailman lopulla: Enkelit menevät ulos ja eroittavat pahat vanhurskasten keskeltä,","Näin on tapahtuva maailman lopulla: Enkelit menevät ulos ja eroittavat pahat vanhurskasten keskeltä,"],[13,50,"Ja heittävät heidät tuliseen pätsiin: siellä pitää oleman itku ja hammasten kiristys.","Ja heittävät heidät tuliseen pätsiin: siellä pitää oleman itku ja hammasten kiristys."],[13,51,"Sanoi Jesus heille: ymmärsittekö te nämät kaikki? He sanoivat hänelle: ymmärsimme, Herra.","Sanoi Jesus heille: ymmärsittekö te nämät kaikki? He sanoivat hänelle: ymmärsimme, Herra."],[13,52,"Mutta hän sanoi heille: sentähden jokainen kirjanoppinut, joka on taivaan valtakuntaan oppinut, se on perheenisännän vertainen, joka tavarastansa tuo edes uusia ja vanhoja.","Mutta hän sanoi heille: sentähden jokainen kirjanoppinut, joka on taivaan valtakuntaan oppinut, se on perheenisännän vertainen, joka tavarastansa tuo edes uusia ja vanhoja."],[13,53,"Ja tapahtui, kuin Jesus lopetti nämät vertaukset, läksi hän sieltä.","Ja tapahtui, kuin Jesus lopetti nämät vertaukset, läksi hän sieltä."],[13,54,"Ja kuin hän tuli isänsä maalle, opetti hän heitä heidän synagogassansa, niin että he hämmästyivät ja sanoivat: kusta tällä on tämä viisaus ja nämät väkevät työt?","Ja kuin hän tuli isänsä maalle, opetti hän heitä heidän synagogassansa, niin että he hämmästyivät ja sanoivat: kusta tällä on tämä viisaus ja nämät väkevät työt?"],[13,55,"Eikö tämä ole tuo sepän poika? eikö hänen äitinsä kutsuta Mariaksi ja hänen veljensä Jakob ja Joses, ja Simon ja Juudas?","Eikö tämä ole tuo sepän poika? eikö hänen äitinsä kutsuta Mariaksi ja hänen veljensä Jakob ja Joses, ja Simon ja Juudas?"],[13,56,"Ja hänen sisarensa, eikö ne kaikki ole meidän tykönämme? Kusta siis tällä on nämät kaikki?","Ja hänen sisarensa, eikö ne kaikki ole meidän tykönämme? Kusta siis tällä on nämät kaikki?"],[13,57,"Ja he pahenivat hänessä. Niin sanoi Jesus heille: ei prophetaa kussakaan halvempana pidetä kuin isänsä maalla ja kotonansa.","Ja he pahenivat hänessä. Niin sanoi Jesus heille: ei prophetaa kussakaan halvempana pidetä kuin isänsä maalla ja kotonansa."],[13,58,"Ja ei hän siellä monta väkevää työtä tehnyt, heidän epäuskonsa tähden.","Ja ei hän siellä monta väkevää työtä tehnyt, heidän epäuskonsa tähden."],[14,1,"Siihen aikaan kuuli Herodes tetrarka Jesuksen sanoman,","Siihen aikaan kuuli Herodes tetrarka Jesuksen sanoman,"],[14,2,"Ja sanoi palvelioillensa: tämä on Johannes Kastaja: hän on noussut kuolleista, ja sentähden tekee hän senkaltaisia väkeviä töitä.","Ja sanoi palvelioillensa: tämä on Johannes Kastaja: hän on noussut kuolleista, ja sentähden tekee hän senkaltaisia väkeviä töitä."],[14,3,"Sillä Herodes oli ottanut Johanneksen kiinni, sitonut ja vankiuteen pannut, Herodiaksen, veljensä Philippuksen emännän tähden.","Sillä Herodes oli ottanut Johanneksen kiinni, sitonut ja vankiuteen pannut, Herodiaksen, veljensä Philippuksen emännän tähden."],[14,4,"Sillä Johannes oli hänelle sanonut: ei sinulle ole luvallinen häntä pitää.","Sillä Johannes oli hänelle sanonut: ei sinulle ole luvallinen häntä pitää."],[14,5,"Ja kuin hän tahtoi hänen tappaa, pelkäsi hän kansaa; sillä he pitivät hänen prophetana.","Ja kuin hän tahtoi hänen tappaa, pelkäsi hän kansaa; sillä he pitivät hänen prophetana."],[14,6,"Mutta kun Herodeksen syntymäjuhlaa pidettiin, hyppäsi Herodiaksen tytär heidän edessänsä; ja se kelpasi Herodekselle.","Mutta kun Herodeksen syntymäjuhlaa pidettiin, hyppäsi Herodiaksen tytär heidän edessänsä; ja se kelpasi Herodekselle."],[14,7,"Sentähden lupasi hän hänelle vannotulla valalla antaa, mitä hän anois.","Sentähden lupasi hän hänelle vannotulla valalla antaa, mitä hän anois."],[14,8,"Mutta niinkuin hän äidiltänsä ennen neuvottu oli, anna minulle, hän sanoi, tässä vadissa Johannes Kastajan pää.","Mutta niinkuin hän äidiltänsä ennen neuvottu oli, anna minulle, hän sanoi, tässä vadissa Johannes Kastajan pää."],[14,9,"Ja kuningas tuli murheelliseksi; mutta kuitenkin valan tähden ja niiden, jotka ynnä atrioitsivat, käski hän antaa hänelle,","Ja kuningas tuli murheelliseksi; mutta kuitenkin valan tähden ja niiden, jotka ynnä atrioitsivat, käski hän antaa hänelle,"],[14,10,"Ja lähetti leikkaamaan Johanneksen kaulaa tornissa.","Ja lähetti leikkaamaan Johanneksen kaulaa tornissa."],[14,11,"Ja hänen päänsä kannettiin vadissa ja annettiin piialle, ja hän vei sen äidillensä.","Ja hänen päänsä kannettiin vadissa ja annettiin piialle, ja hän vei sen äidillensä."],[14,12,"Ja hänen opetuslapsensa tulivat, ja ottivat pois hänen ruumiinsa, ja hautasivat sen; ja menivät ja ilmoittivat Jesukselle.","Ja hänen opetuslapsensa tulivat, ja ottivat pois hänen ruumiinsa, ja hautasivat sen; ja menivät ja ilmoittivat Jesukselle."],[14,13,"Ja kuin Jesus sen kuuli, meni hän sieltä pois haahdella erämaahan yksinänsä. Ja kuin kansa se kuuli, noudattivat he häntä jalkaisin kaupungeista.","Ja kuin Jesus sen kuuli, meni hän sieltä pois haahdella erämaahan yksinänsä. Ja kuin kansa se kuuli, noudattivat he häntä jalkaisin kaupungeista."],[14,14,"Ja Jesus meni ulos, ja näki paljon kansaa, ja armahti heidän päällensä, ja paransi heidän sairaitansa.","Ja Jesus meni ulos, ja näki paljon kansaa, ja armahti heidän päällensä, ja paransi heidän sairaitansa."],[14,15,"Mutta kun ehtoo tuli, tulivat hänen opetuslapsensa hänen tykönsä, ja sanoivat: tämä on erämaa, ja aika on jo kulunut: laske kansa, että he menisivät kyliin itsellensä ruokaa ostamaan.","Mutta kun ehtoo tuli, tulivat hänen opetuslapsensa hänen tykönsä, ja sanoivat: tämä on erämaa, ja aika on jo kulunut: laske kansa, että he menisivät kyliin itsellensä ruokaa ostamaan."],[14,16,"Niin Jesus sanoi heille: ei tarvitse heidän mennä pois: antakaat te heidän syödä.","Niin Jesus sanoi heille: ei tarvitse heidän mennä pois: antakaat te heidän syödä."],[14,17,"Mutta he sanoivat hänelle: ei meillä ole tässä enempi kuin viisi leipää ja kaksi kalaa.","Mutta he sanoivat hänelle: ei meillä ole tässä enempi kuin viisi leipää ja kaksi kalaa."],[14,18,"Hän sanoi: tuokaat minulle ne tänne.","Hän sanoi: tuokaat minulle ne tänne."],[14,19,"Ja hän käski kansan istua ruoholle, ja otti ne viisi leipää ja kaksi kalaa, katsahti ylös taivaasen, kiitti, ja mursi, ja antoi leivät opetuslapsille, ja opetuslapset antoivat kansalle.","Ja hän käski kansan istua ruoholle, ja otti ne viisi leipää ja kaksi kalaa, katsahti ylös taivaasen, kiitti, ja mursi, ja antoi leivät opetuslapsille, ja opetuslapset antoivat kansalle."],[14,20,"Ja he söivät kaikki, ja ravittiin. Niin he kokosivat tähteistä muruja, kaksitoistakymmentä koria täyteen.","Ja he söivät kaikki, ja ravittiin. Niin he kokosivat tähteistä muruja, kaksitoistakymmentä koria täyteen."],[14,21,"Mutta niitä, jotka olivat syöneet, oli lähes viisituhatta miestä, ilman vaimoja ja lapsia.","Mutta niitä, jotka olivat syöneet, oli lähes viisituhatta miestä, ilman vaimoja ja lapsia."],[14,22,"Ja kohta vaati Jesus opetuslapsiansa haahteen astumaan, ja menemään hänen edellään toiselle rannalle, niinkauvan kuin hän kansan olis tyköänsä laskenut.","Ja kohta vaati Jesus opetuslapsiansa haahteen astumaan, ja menemään hänen edellään toiselle rannalle, niinkauvan kuin hän kansan olis tyköänsä laskenut."],[14,23,"Ja kuin hän oli kansan laskenut, astui hän yksinänsä vuorelle rukoilemaan. Ja kuin ehtoo joutui, oli hän siellä yksinänsä.","Ja kuin hän oli kansan laskenut, astui hän yksinänsä vuorelle rukoilemaan. Ja kuin ehtoo joutui, oli hän siellä yksinänsä."],[14,24,"Mutta haaksi oli jo keskellä merta, ja ahdistettiin aalloilta; sillä vastatuuli oli.","Mutta haaksi oli jo keskellä merta, ja ahdistettiin aalloilta; sillä vastatuuli oli."],[14,25,"Mutta yöllä, neljännessä vartiossa, tuli Jesus heidän tykönsä, käyden merellä.","Mutta yöllä, neljännessä vartiossa, tuli Jesus heidän tykönsä, käyden merellä."],[14,26,"Ja kuin opetuslapset näkivät hänen merellä käyvän, peljästyivät he, ja sanoivat: kyöpeli se on; ja huusivat pelvon tähden.","Ja kuin opetuslapset näkivät hänen merellä käyvän, peljästyivät he, ja sanoivat: kyöpeli se on; ja huusivat pelvon tähden."],[14,27,"Niin Jesus puhui kohta heille ja sanoi: olkaat hyvässä turvassa! minä olen: älkäät peljästykö.","Niin Jesus puhui kohta heille ja sanoi: olkaat hyvässä turvassa! minä olen: älkäät peljästykö."],[14,28,"Niin vastasi Pietari häntä ja sanoi: Herra, jos sinä olet, niin käske minun tulla tykös vetten päällä.","Niin vastasi Pietari häntä ja sanoi: Herra, jos sinä olet, niin käske minun tulla tykös vetten päällä."],[14,29,"Niin hän sanoi: tule! Ja Pietari astui ulos haahdesta ja kävi vetten päällä, että hän menis Jesuksen tykö.","Niin hän sanoi: tule! Ja Pietari astui ulos haahdesta ja kävi vetten päällä, että hän menis Jesuksen tykö."],[14,30,"Ja kuin hän näki ankaran tuulen, niin hän peljästyi, ja rupesi vajoomaan, huusi sanoen: Herra, auta minua!","Ja kuin hän näki ankaran tuulen, niin hän peljästyi, ja rupesi vajoomaan, huusi sanoen: Herra, auta minua!"],[14,31,"Niin Jesus ojensi kohta kätensä, ja tarttui häneen, ja sanoi hänelle: oi sinä heikko-uskoinen, miksis epäilit?","Niin Jesus ojensi kohta kätensä, ja tarttui häneen, ja sanoi hänelle: oi sinä heikko-uskoinen, miksis epäilit?"],[14,32,"Kuin he astuivat haahteen, niin tuuli tyveni.","Kuin he astuivat haahteen, niin tuuli tyveni."],[14,33,"Mutta ne, jotka olivat haahdessa, tulivat ja kumarsivat häntä, ja sanoivat: totisesti olet sinä Jumalan Poika.","Mutta ne, jotka olivat haahdessa, tulivat ja kumarsivat häntä, ja sanoivat: totisesti olet sinä Jumalan Poika."],[14,34,"Ja kuin he olivat menneet ylitse, tulivat he Genesaretin maalle.","Ja kuin he olivat menneet ylitse, tulivat he Genesaretin maalle."],[14,35,"Ja kuin sen paikan miehet tunsivat hänen, lähettivät he ympäri kaikkea sitä maata, ja toivat hänen tykönsä kaikkinaisia sairaita,","Ja kuin sen paikan miehet tunsivat hänen, lähettivät he ympäri kaikkea sitä maata, ja toivat hänen tykönsä kaikkinaisia sairaita,"],[14,36,"Ja rukoilivat häntä, että he ainoastaan hänen vaatteensa palteeseen saisivat ruveta. Ja kaikki, jotka siihen rupesivat, tulivat terveiksi.","Ja rukoilivat häntä, että he ainoastaan hänen vaatteensa palteeseen saisivat ruveta. Ja kaikki, jotka siihen rupesivat, tulivat terveiksi."],[15,1,"Silloin tulivat Jesuksen tykö kirjanoppineet ja Pharisealaiset Jerusalemista, ja sanoivat:","Silloin tulivat Jesuksen tykö kirjanoppineet ja Pharisealaiset Jerusalemista, ja sanoivat:"],[15,2,"Miksi sinun opetuslapses rikkovat vanhinten säädyn? sillä ei he pese käsiänsä leipää syödessänsä.","Miksi sinun opetuslapses rikkovat vanhinten säädyn? sillä ei he pese käsiänsä leipää syödessänsä."],[15,3,"Niin hän vastaten sanoi heille: miksi tekin rikotte Jumalan käskyn, teidän säätynne tähden?","Niin hän vastaten sanoi heille: miksi tekin rikotte Jumalan käskyn, teidän säätynne tähden?"],[15,4,"Sillä Jumala käski, sanoen: kunnioita isääs ja äitiäs: ja joka kiroilee isää eli äitiä, hänen pitää kuolemalla kuoleman.","Sillä Jumala käski, sanoen: kunnioita isääs ja äitiäs: ja joka kiroilee isää eli äitiä, hänen pitää kuolemalla kuoleman."],[15,5,"Mutta te sanotte: jokainen sanokaan isälle taikka äidille: se on uhrattu, jolla sinua piti minulta autettaman: ja ei ensinkään kunnoittaisi isäänsä eikä äitiänsä.","Mutta te sanotte: jokainen sanokaan isälle taikka äidille: se on uhrattu, jolla sinua piti minulta autettaman: ja ei ensinkään kunnoittaisi isäänsä eikä äitiänsä."],[15,6,"Ja te olette rikkoneet Jumalan käskyn teidän säätynne tähden.","Ja te olette rikkoneet Jumalan käskyn teidän säätynne tähden."],[15,7,"Te ulkokullatut! Jesaias ennusti teistä oikein, sanoen:","Te ulkokullatut! Jesaias ennusti teistä oikein, sanoen:"],[15,8,"Tämä kansa lähestyy minua suullansa, ja kunnioittaa minua huulillansa; mutta heidän sydämensä on kaukana minusta.","Tämä kansa lähestyy minua suullansa, ja kunnioittaa minua huulillansa; mutta heidän sydämensä on kaukana minusta."],[15,9,"Vaan turhaan he minua palvelevat, opettain niitä opetuksia, jotka ovat ihmisten käskyt.","Vaan turhaan he minua palvelevat, opettain niitä opetuksia, jotka ovat ihmisten käskyt."],[15,10,"Ja hän kutsui kansan tykönsä, ja sanoi heille: kuulkaat ja ymmärtäkäät!","Ja hän kutsui kansan tykönsä, ja sanoi heille: kuulkaat ja ymmärtäkäät!"],[15,11,"Ei se ihmistä saastuta, mikä suusta menee sisälle, mutta se, mikä suusta tulee ulos, saastuttaa ihmisen.","Ei se ihmistä saastuta, mikä suusta menee sisälle, mutta se, mikä suusta tulee ulos, saastuttaa ihmisen."],[15,12,"Niin tulivat hänen opetuslapsensa, ja sanoivat hänelle: tiesitkös, että Pharisealaiset pahenivat, kuin he tämän puheen kuulivat?","Niin tulivat hänen opetuslapsensa, ja sanoivat hänelle: tiesitkös, että Pharisealaiset pahenivat, kuin he tämän puheen kuulivat?"],[15,13,"Mutta hän vastasi ja sanoi: jokainen istutus, jota ei minun taivaallinen Isäni ole istuttanut, pitää juurinensa revittämän ylös.","Mutta hän vastasi ja sanoi: jokainen istutus, jota ei minun taivaallinen Isäni ole istuttanut, pitää juurinensa revittämän ylös."],[15,14,"Antakaat heidän olla: he ovat sokiat sokiain taluttajat; jos sokia sokiaa taluttaa, niin he molemmat kuoppaan lankeevat.","Antakaat heidän olla: he ovat sokiat sokiain taluttajat; jos sokia sokiaa taluttaa, niin he molemmat kuoppaan lankeevat."],[15,15,"Niin vastasi Pietari ja sanoi hänelle: selitä meille tämä vertaus.","Niin vastasi Pietari ja sanoi hänelle: selitä meille tämä vertaus."],[15,16,"Niin Jesus sanoi: vieläkö tekin olette ymmärtämättömät?","Niin Jesus sanoi: vieläkö tekin olette ymmärtämättömät?"],[15,17,"Ettekö te vielä ymmärrä, että kaikki, mitä suuhun sisälle menee, se menee vatsaan, ja sillä on luonnollinen uloskäyminen.","Ettekö te vielä ymmärrä, että kaikki, mitä suuhun sisälle menee, se menee vatsaan, ja sillä on luonnollinen uloskäyminen."],[15,18,"Mutta jotka suusta tulevat ulos, ne lähtevät sydämestä ulos, ja saastuttavat ihmisen.","Mutta jotka suusta tulevat ulos, ne lähtevät sydämestä ulos, ja saastuttavat ihmisen."],[15,19,"Sillä sydämestä tulevat ulos pahat ajatukset, murhat, salavuoteudet, huoruudet, varkaudet, väärät todistukset, pilkat:","Sillä sydämestä tulevat ulos pahat ajatukset, murhat, salavuoteudet, huoruudet, varkaudet, väärät todistukset, pilkat:"],[15,20,"Nämät ovat ne, jotka saastuttavat ihmisen; mutta pesemättömillä käsillä syödä, ei saastuta ihmistä.","Nämät ovat ne, jotka saastuttavat ihmisen; mutta pesemättömillä käsillä syödä, ei saastuta ihmistä."],[15,21,"Ja Jesus läksi sieltä ja poikkesi Tyron ja Sidonin maan ääriin.","Ja Jesus läksi sieltä ja poikkesi Tyron ja Sidonin maan ääriin."],[15,22,"Ja katso, Kanaanean vaimo, joka niistä maan ääristä oli tullut, huusi häntä, sanoen: Herra, Davidin poika, armahda minua: minun tyttäreni vaivataan hirmuisesti perkeleeltä.","Ja katso, Kanaanean vaimo, joka niistä maan ääristä oli tullut, huusi häntä, sanoen: Herra, Davidin poika, armahda minua: minun tyttäreni vaivataan hirmuisesti perkeleeltä."],[15,23,"Mutta ei hän sanaakaan häntä vastannut. Niin hänen opetuslapsensa tulivat ja rukoilivat häntä, sanoen: eroita häntä sinustas; sillä hän huutaa meidän jälkeemme.","Mutta ei hän sanaakaan häntä vastannut. Niin hänen opetuslapsensa tulivat ja rukoilivat häntä, sanoen: eroita häntä sinustas; sillä hän huutaa meidän jälkeemme."],[15,24,"Niin hän vastaten sanoi: en ole minä lähetetty, vaan kadotettuin lammasten tykö Israelin huoneesta.","Niin hän vastaten sanoi: en ole minä lähetetty, vaan kadotettuin lammasten tykö Israelin huoneesta."],[15,25,"Mutta se tuli ja kumarsi häntä, sanoen: Herra, auta minua.","Mutta se tuli ja kumarsi häntä, sanoen: Herra, auta minua."],[15,26,"Niin hän vastaten sanoi: ei ole sovelias ottaa lasten leipää ja heittää penikoille.","Niin hän vastaten sanoi: ei ole sovelias ottaa lasten leipää ja heittää penikoille."],[15,27,"Niin se vastasi: totta Herra, syövät kuitenkin penikatkin niistä muruista, jotka heidän herrainsa pöydältä putoovat.","Niin se vastasi: totta Herra, syövät kuitenkin penikatkin niistä muruista, jotka heidän herrainsa pöydältä putoovat."],[15,28,"Silloin Jesus vastaten sanoi hänelle: oi vaimo, suuri on sinun uskos, tapahtukoon sinulle niinkuin sinä tahdot. Ja hänen tyttärensä tuli sillä hetkellä terveeksi.","Silloin Jesus vastaten sanoi hänelle: oi vaimo, suuri on sinun uskos, tapahtukoon sinulle niinkuin sinä tahdot. Ja hänen tyttärensä tuli sillä hetkellä terveeksi."],[15,29,"Ja Jesus läksi sieltä ja tuli Galilean meren tykö, ja astui vuorelle, ja istui siihen.","Ja Jesus läksi sieltä ja tuli Galilean meren tykö, ja astui vuorelle, ja istui siihen."],[15,30,"Ja paljo kansaa tuli hänen tykönsä, ja toivat kanssansa ontuvia, sokeita, mykkiä, raajarikkoja ja paljon muita, ja laskivat Jesuksen jalkain eteen; ja hän paransi heidät.","Ja paljo kansaa tuli hänen tykönsä, ja toivat kanssansa ontuvia, sokeita, mykkiä, raajarikkoja ja paljon muita, ja laskivat Jesuksen jalkain eteen; ja hän paransi heidät."],[15,31,"Niin että kansa ihmetteli, kuin he näkivät mykät puhuvan, raajarikot terveinä, ontuvat käyvän ja sokiat näkevän, ja kunnioittivat Israelin Jumalaa.","Niin että kansa ihmetteli, kuin he näkivät mykät puhuvan, raajarikot terveinä, ontuvat käyvän ja sokiat näkevän, ja kunnioittivat Israelin Jumalaa."],[15,32,"Ja Jesus kutsui opetuslapsensa tykönsä, ja sanoi: minä armahdan kansaa, että he ovat jo kolme päivää minun tykönäni viipyneet, ja ei ole heillä mitään syötävää: ja en minä tahdo heitä tyköäni syömättä laskea pois, ettei he tiellä vaipuisi.","Ja Jesus kutsui opetuslapsensa tykönsä, ja sanoi: minä armahdan kansaa, että he ovat jo kolme päivää minun tykönäni viipyneet, ja ei ole heillä mitään syötävää: ja en minä tahdo heitä tyköäni syömättä laskea pois, ettei he tiellä vaipuisi."],[15,33,"Niin sanoivat hänen opetuslapsensa hänelle: kusta me saamme tässä erämaassa niin monta leipää, että me ravitsemme niin paljon kansaa?","Niin sanoivat hänen opetuslapsensa hänelle: kusta me saamme tässä erämaassa niin monta leipää, että me ravitsemme niin paljon kansaa?"],[15,34,"Ja Jesus sanoi heille: kuinka monta leipää teillä on? He sanoivat: seitsemän, ja vähä kalasia.","Ja Jesus sanoi heille: kuinka monta leipää teillä on? He sanoivat: seitsemän, ja vähä kalasia."],[15,35,"Niin hän käski kansan istua maan päälle atrioitsemaan.","Niin hän käski kansan istua maan päälle atrioitsemaan."],[15,36,"Ja hän otti ne seitsemän leipää ja kalat, kiitti, mursi ja antoi opetuslapsillensa, ja opetuslapset antoivat kansalle.","Ja hän otti ne seitsemän leipää ja kalat, kiitti, mursi ja antoi opetuslapsillensa, ja opetuslapset antoivat kansalle."],[15,37,"Ja he söivät kaikki ja ravittiin, ja ottivat ylös mitä liiaksi jäi, seitsemän täysinäistä koria muruja.","Ja he söivät kaikki ja ravittiin, ja ottivat ylös mitä liiaksi jäi, seitsemän täysinäistä koria muruja."],[15,38,"Mutta niitä jotka söivät, oli neljätuhatta miestä, ilman vaimoja ja lapsia.","Mutta niitä jotka söivät, oli neljätuhatta miestä, ilman vaimoja ja lapsia."],[15,39,"Ja kuin hän oli kansan tyköänsä laskenut, astui hän haahteen, ja tuli Magdalan rajoille.","Ja kuin hän oli kansan tyköänsä laskenut, astui hän haahteen, ja tuli Magdalan rajoille."],[16,1,"Niin tulivat hänen tykönsä Pharisealaiset ja Saddukealaiset ja kiusaten anoivat häneltä, että hän merkin taivaasta osoittais heille.","Niin tulivat hänen tykönsä Pharisealaiset ja Saddukealaiset ja kiusaten anoivat häneltä, että hän merkin taivaasta osoittais heille."],[16,2,"Niin hän vastasi ja sanoi heille: kuin ehtoo tulee, niin te sanotte: seijes tulee; sillä taivas ruskottaa,","Niin hän vastasi ja sanoi heille: kuin ehtoo tulee, niin te sanotte: seijes tulee; sillä taivas ruskottaa,"],[16,3,"Ja huomeneltain: tänäpänä tulee kova ilma; sillä taivas ruskottaa ja on valju. Te ulkokullatut! te taidatte taivaan muodon tuomita, mutta aikain merkkejä ette taida tuomita?","Ja huomeneltain: tänäpänä tulee kova ilma; sillä taivas ruskottaa ja on valju. Te ulkokullatut! te taidatte taivaan muodon tuomita, mutta aikain merkkejä ette taida tuomita?"],[16,4,"Tämä häijy ja huorintekijä sukukunta etsii merkkiä, ja ei hänelle pidä merkkiä annettaman, vaan Jonan prophetan merkki. Ja hän jätti heidät, ja meni pois.","Tämä häijy ja huorintekijä sukukunta etsii merkkiä, ja ei hänelle pidä merkkiä annettaman, vaan Jonan prophetan merkki. Ja hän jätti heidät, ja meni pois."],[16,5,"Ja kuin hänen opetuslapsensa olivat tulleet ylitse toiselle rannalle, olivat he unohtaneet ottaa leipiä myötänsä.","Ja kuin hänen opetuslapsensa olivat tulleet ylitse toiselle rannalle, olivat he unohtaneet ottaa leipiä myötänsä."],[16,6,"Mutta Jesus sanoi heille: katsokaat ja kavahtakaat teitänne Pharisealaisten ja Saddukealaisten hapatuksesta.","Mutta Jesus sanoi heille: katsokaat ja kavahtakaat teitänne Pharisealaisten ja Saddukealaisten hapatuksesta."],[16,7,"Niin he ajattelivat itsellensä, sanoen: se on, ettemme ottaneet leipiä myötämme.","Niin he ajattelivat itsellensä, sanoen: se on, ettemme ottaneet leipiä myötämme."],[16,8,"Mutta kuin Jesus sen ymmärsi, sanoi hän heille: te vähäuskoiset! mitä te ajattelette keskenänne, ettette leipiä myötänne ottaneet?","Mutta kuin Jesus sen ymmärsi, sanoi hän heille: te vähäuskoiset! mitä te ajattelette keskenänne, ettette leipiä myötänne ottaneet?"],[16,9,"Ettekö vielä ymmärrä, taikka ettekö te muista niitä viittä leipää viidelletuhannelle, ja kuinka monta koria te korjasitte?","Ettekö vielä ymmärrä, taikka ettekö te muista niitä viittä leipää viidelletuhannelle, ja kuinka monta koria te korjasitte?"],[16,10,"Niin myös niitä seitsemää leipää neljälletuhannelle, ja kuinka monta koria te korjasitte?","Niin myös niitä seitsemää leipää neljälletuhannelle, ja kuinka monta koria te korjasitte?"],[16,11,"Kuinka ette ymmärrä, etten minä leivästä teille sitä sanonut, että teidän pitäis kavahtaman teitänne Pharisealaisten ja Saddukealaisten hapatuksesta?","Kuinka ette ymmärrä, etten minä leivästä teille sitä sanonut, että teidän pitäis kavahtaman teitänne Pharisealaisten ja Saddukealaisten hapatuksesta?"],[16,12,"Silloin he ymmärsivät, ettei hän käskenyt heitä kavahtamaan itsiänsä leivän hapatuksesta, vaan Pharisealaisten ja Saddukealaisten opista.","Silloin he ymmärsivät, ettei hän käskenyt heitä kavahtamaan itsiänsä leivän hapatuksesta, vaan Pharisealaisten ja Saddukealaisten opista."],[16,13,"Mutta kuin Jesus tuli Kesarean maan ääriin, joka kutsutaan Philippuksen, kysyi hän opetuslapsiltansa ja sanoi: kenenkä sanovat ihmiset minun, Ihmisen Pojan, olevan?","Mutta kuin Jesus tuli Kesarean maan ääriin, joka kutsutaan Philippuksen, kysyi hän opetuslapsiltansa ja sanoi: kenenkä sanovat ihmiset minun, Ihmisen Pojan, olevan?"],[16,14,"Niin he sanoivat: monikahdat Johannes Kastajan; mutta muutamat Eliaan; muutamat taas Jeremiaan, taikka jonkun prophetaista.","Niin he sanoivat: monikahdat Johannes Kastajan; mutta muutamat Eliaan; muutamat taas Jeremiaan, taikka jonkun prophetaista."],[16,15,"Sanoi hän heille: mutta kenenkä te sanotte minun olevan?","Sanoi hän heille: mutta kenenkä te sanotte minun olevan?"],[16,16,"Vastasi Simon Pietari ja sanoi: sinä olet Kristus, elävän Jumalan Poika.","Vastasi Simon Pietari ja sanoi: sinä olet Kristus, elävän Jumalan Poika."],[16,17,"Ja Jesus vastaten sanoi hänelle: autuas olet sinä, Simon Jonan poika! sillä ei liha eikä veri ilmoittanut sitä sinulle, vaan Isäni, joka on taivaissa.","Ja Jesus vastaten sanoi hänelle: autuas olet sinä, Simon Jonan poika! sillä ei liha eikä veri ilmoittanut sitä sinulle, vaan Isäni, joka on taivaissa."],[16,18,"Mutta minä myös sanon sinulle: sinä ole Pietari, ja tämän kallion päälle tahdon minä rakentaa minun seurakuntani, ja helvetin portit ei pidä häntä voittaman.","Mutta minä myös sanon sinulle: sinä ole Pietari, ja tämän kallion päälle tahdon minä rakentaa minun seurakuntani, ja helvetin portit ei pidä häntä voittaman."],[16,19,"Ja minä annan sinulle taivaan valtakunnan avaimet: ja mitä sinä maan päällä sidot, pitää sidotun oleman taivaissa, ja mitä sinä päästät maan päällä, sen pitää oleman päästetyn taivaissa.","Ja minä annan sinulle taivaan valtakunnan avaimet: ja mitä sinä maan päällä sidot, pitää sidotun oleman taivaissa, ja mitä sinä päästät maan päällä, sen pitää oleman päästetyn taivaissa."],[16,20,"Niin hän haastoi opetuslapsiansa kellenkään sanomasta, että hän oli Jesus Kristus.","Niin hän haastoi opetuslapsiansa kellenkään sanomasta, että hän oli Jesus Kristus."],[16,21,"Siitä ajasta rupesi Jesus julistamaan opetuslapsillensa, että hänen piti Jerusalemiin menemän, ja paljon vanhimmilta ja pappein päämiehiltä ja kirjanoppineilta kärsimän, ja tapettaman, ja kolmantena päivänä ylösnouseman.","Siitä ajasta rupesi Jesus julistamaan opetuslapsillensa, että hänen piti Jerusalemiin menemän, ja paljon vanhimmilta ja pappein päämiehiltä ja kirjanoppineilta kärsimän, ja tapettaman, ja kolmantena päivänä ylösnouseman."],[16,22,"Ja Pietari otti hänen erinänsä, rupesi häntä nuhtelemaan, sanoen: armahda itsiäs, Herra: älköön sinulle se tapahtuko!","Ja Pietari otti hänen erinänsä, rupesi häntä nuhtelemaan, sanoen: armahda itsiäs, Herra: älköön sinulle se tapahtuko!"],[16,23,"Niin hän käänsi itsensä ympäri ja sanoi Pietarille: mene pois minun tyköäni, saatana! sinä olet minulle pahennukseksi: ettes ymmärrä niitä, jotka Jumalan ovat, mutta ne, jotka ihmisen ovat.","Niin hän käänsi itsensä ympäri ja sanoi Pietarille: mene pois minun tyköäni, saatana! sinä olet minulle pahennukseksi: ettes ymmärrä niitä, jotka Jumalan ovat, mutta ne, jotka ihmisen ovat."],[16,24,"Silloin Jesus sanoi opetuslapsillensa: jos joku tahtoo minun perässäni tulla, hän kieltäkään itsensä, ja ottakaan ristinsä, ja seuratkaan minua;","Silloin Jesus sanoi opetuslapsillensa: jos joku tahtoo minun perässäni tulla, hän kieltäkään itsensä, ja ottakaan ristinsä, ja seuratkaan minua;"],[16,25,"Sillä joka tahtoo henkensä vapahtaa, hän hukuttaa sen; mutta joka henkensä hukuttaa minun tähteni, hän löytää sen.","Sillä joka tahtoo henkensä vapahtaa, hän hukuttaa sen; mutta joka henkensä hukuttaa minun tähteni, hän löytää sen."],[16,26,"Sillä mitä se auttaa ihmistä, jos hän kaiken maailman voittais, ja sielullensa sais vahingon? taikka mitä antaa ihminen sielunsa lunastukseksi?","Sillä mitä se auttaa ihmistä, jos hän kaiken maailman voittais, ja sielullensa sais vahingon? taikka mitä antaa ihminen sielunsa lunastukseksi?"],[16,27,"Sillä Ihmisen Poika on tuleva Isänsä kunniassa enkelittensä kanssa, ja silloin hän maksaa kullekin töittensä jälkeen.","Sillä Ihmisen Poika on tuleva Isänsä kunniassa enkelittensä kanssa, ja silloin hän maksaa kullekin töittensä jälkeen."],[16,28,"Totisesti minä sanon teille: muutamat seisovat tässä, joiden ei suinkaan pidä kuolemaa maistaman, siihenasti kuin he näkevät Ihmisen Pojan tulevan hänen valtakunnassansa.","Totisesti minä sanon teille: muutamat seisovat tässä, joiden ei suinkaan pidä kuolemaa maistaman, siihenasti kuin he näkevät Ihmisen Pojan tulevan hänen valtakunnassansa."],[17,1,"Ja kuuden päivän perästä otti Jesus Pietarin ja Jakobin ja Johanneksen hänen veljensä, ja vei heidät erinänsä korkialle vuorelle.","Ja kuuden päivän perästä otti Jesus Pietarin ja Jakobin ja Johanneksen hänen veljensä, ja vei heidät erinänsä korkialle vuorelle."],[17,2,"Ja kirkastettiin heidän edessänsä, ja hänen kasvonsa paistivat niinkuin aurinko, ja hänen vaatteensa tulivat valkiaksi niinkuin valkeus.","Ja kirkastettiin heidän edessänsä, ja hänen kasvonsa paistivat niinkuin aurinko, ja hänen vaatteensa tulivat valkiaksi niinkuin valkeus."],[17,3,"Ja katso, heille näkyivät Moses ja Elias, jotka puhuivat hänen kanssansa.","Ja katso, heille näkyivät Moses ja Elias, jotka puhuivat hänen kanssansa."],[17,4,"Niin vastasi Pietari ja sanoi Jesukselle: Herra, meidän on tässä hyvä olla: jos sinä tahdot, niin me teemme tähän kolme majaa, sinulle yhden, ja Mosekselle yhden, ja Eliaalle yhden.","Niin vastasi Pietari ja sanoi Jesukselle: Herra, meidän on tässä hyvä olla: jos sinä tahdot, niin me teemme tähän kolme majaa, sinulle yhden, ja Mosekselle yhden, ja Eliaalle yhden."],[17,5,"Vielä hänen puhuissansa, katso, paistava pilvi ympäri varjosi heidät, ja katso, ääni pilvestä sanoi: tämä on minun rakas Poikani, johonka minä mielistyin: kuulkaat häntä.","Vielä hänen puhuissansa, katso, paistava pilvi ympäri varjosi heidät, ja katso, ääni pilvestä sanoi: tämä on minun rakas Poikani, johonka minä mielistyin: kuulkaat häntä."],[17,6,"Ja kuin opetuslapset sen kuulivat, lankesivat he kasvoillensa, ja peljästyivät sangen kovin.","Ja kuin opetuslapset sen kuulivat, lankesivat he kasvoillensa, ja peljästyivät sangen kovin."],[17,7,"Ja Jesus tuli, ja rupesi heihin, ja sanoi: nouskaat, ja älkäät peljätkö.","Ja Jesus tuli, ja rupesi heihin, ja sanoi: nouskaat, ja älkäät peljätkö."],[17,8,"Mutta kuin he silmänsä nostivat, ei he ketään nähneet, vaan Jesuksen yksinänsä.","Mutta kuin he silmänsä nostivat, ei he ketään nähneet, vaan Jesuksen yksinänsä."],[17,9,"Ja kuin he menivät vuorelta alas, haastoi Jesus heitä, sanoen: älkäät kellenkään tätä näkyä sanoko, siihenasti kuin Ihmisen Poika kuolleista nousee.","Ja kuin he menivät vuorelta alas, haastoi Jesus heitä, sanoen: älkäät kellenkään tätä näkyä sanoko, siihenasti kuin Ihmisen Poika kuolleista nousee."],[17,10,"Niin hänen opetuslapsensa kysyivät häneltä, sanoen: miksi siis kirjanoppineet sanovat, että Eliaan pitää ennen tuleman?","Niin hänen opetuslapsensa kysyivät häneltä, sanoen: miksi siis kirjanoppineet sanovat, että Eliaan pitää ennen tuleman?"],[17,11,"Niin Jesus vastaten sanoi heille: Elias tosin tulee ennen, ja kohentaa kaikki.","Niin Jesus vastaten sanoi heille: Elias tosin tulee ennen, ja kohentaa kaikki."],[17,12,"Mutta minä sanon teille: Elias on jo tullut; ja ei he tunteneet häntä, mutta tekivät hänelle mitä he tahtoivat. Niin myös Ihmisen Poika on heiltä kärsivä.","Mutta minä sanon teille: Elias on jo tullut; ja ei he tunteneet häntä, mutta tekivät hänelle mitä he tahtoivat. Niin myös Ihmisen Poika on heiltä kärsivä."],[17,13,"Silloin ymmärsivät opetuslapset hänen Johannes Kastajasta sanoneen heille.","Silloin ymmärsivät opetuslapset hänen Johannes Kastajasta sanoneen heille."],[17,14,"Ja kuin he kansan tykö tulivat, tuli yksi mies hänen tykönsä ja lankesi polvillensa hänen eteensä,","Ja kuin he kansan tykö tulivat, tuli yksi mies hänen tykönsä ja lankesi polvillensa hänen eteensä,"],[17,15,"Ja sanoi: Herra, armahda minun poikaani, sillä hän on kuutaudillinen ja kovin vaivataan; sillä hän lankee usein tuleen ja usein veteen.","Ja sanoi: Herra, armahda minun poikaani, sillä hän on kuutaudillinen ja kovin vaivataan; sillä hän lankee usein tuleen ja usein veteen."],[17,16,"Ja minä toin hänen opetuslastes tykö, ja ei he voineet häntä parantaa.","Ja minä toin hänen opetuslastes tykö, ja ei he voineet häntä parantaa."],[17,17,"Niin Jesus vastaten sanoi: oi epäuskoinen ja nurja sukukunta! kuinka kauvan minun pitää teidän kanssanne oleman? kuinka kauvan minun pitää teitä kärsimän? Tuokaat häntä minulle tänne.","Niin Jesus vastaten sanoi: oi epäuskoinen ja nurja sukukunta! kuinka kauvan minun pitää teidän kanssanne oleman? kuinka kauvan minun pitää teitä kärsimän? Tuokaat häntä minulle tänne."],[17,18,"Ja Jesus rankaisi sitä, ja perkele meni hänestä ulos; ja poika parani sillä hetkellä.","Ja Jesus rankaisi sitä, ja perkele meni hänestä ulos; ja poika parani sillä hetkellä."],[17,19,"Silloin menivät opetuslapset Jesuksen tykö erinänsä, ja sanoivat: miksi emme voineet sitä ajaa ulos?","Silloin menivät opetuslapset Jesuksen tykö erinänsä, ja sanoivat: miksi emme voineet sitä ajaa ulos?"],[17,20,"Niin Jesus sanoi heille: epäuskonne tähden. Sillä totisesti minä sanon teille: jos teillä olis usko niinkuin sinapin siemen, niin te taitaisitte sanoa tälle vuorelle: siirry tästä sinne, niin se siirtyis, ja ei teille mitään olisi mahdotointa.","Niin Jesus sanoi heille: epäuskonne tähden. Sillä totisesti minä sanon teille: jos teillä olis usko niinkuin sinapin siemen, niin te taitaisitte sanoa tälle vuorelle: siirry tästä sinne, niin se siirtyis, ja ei teille mitään olisi mahdotointa."],[17,21,"Vaan tämä suku ei mene muutoin ulos kuin rukouksella ja paastolla.","Vaan tämä suku ei mene muutoin ulos kuin rukouksella ja paastolla."],[17,22,"Kuin he asuivat Galileassa, sanoi Jesus heille: tapahtuva on, että Ihmisen Poika annetaan ylön ihmisten käsiin;","Kuin he asuivat Galileassa, sanoi Jesus heille: tapahtuva on, että Ihmisen Poika annetaan ylön ihmisten käsiin;"],[17,23,"Ja he tappavat hänen, ja kolmantena päivänä hän nousee ylös. Ja he tulivat sangen murheellisiksi.","Ja he tappavat hänen, ja kolmantena päivänä hän nousee ylös. Ja he tulivat sangen murheellisiksi."],[17,24,"Mutta kuin he menivät Kapernaumiin, tulivat verorahan ottajat Pietarin tykö, ja sanoivat: eikö Mestarinne ole tottunut verorahaa maksamaan?","Mutta kuin he menivät Kapernaumiin, tulivat verorahan ottajat Pietarin tykö, ja sanoivat: eikö Mestarinne ole tottunut verorahaa maksamaan?"],[17,25,"Sanoi hän: on. Ja kuin hän tuli huoneeseen, ennätti hänen Jesus, ja sanoi: mitäs luulet, Simon? keiltä maan kuninkaat ottavat tullin eli veron? omilta lapsiltansa, taikka vierailta?","Sanoi hän: on. Ja kuin hän tuli huoneeseen, ennätti hänen Jesus, ja sanoi: mitäs luulet, Simon? keiltä maan kuninkaat ottavat tullin eli veron? omilta lapsiltansa, taikka vierailta?"],[17,26,"Pietari sanoi hänelle: vierailta. Sanoi Jesus hänelle: niin lapset ovat vapaat.","Pietari sanoi hänelle: vierailta. Sanoi Jesus hänelle: niin lapset ovat vapaat."],[17,27,"Mutta ettemme heitä pahentaisi, niin mene merelle, heitä onkes, ja ota se kala, joka ensin tulee ylös, ja avaa hänen suunsa, niin sinä löydät rahan: ota se, ja anna heille minun ja sinun edestäs.","Mutta ettemme heitä pahentaisi, niin mene merelle, heitä onkes, ja ota se kala, joka ensin tulee ylös, ja avaa hänen suunsa, niin sinä löydät rahan: ota se, ja anna heille minun ja sinun edestäs."],[18,1,"Sillä hetkellä tulivat opetuslapset Jesuksen tykö, sanoen: kuka siis on suurin taivaan valtakunnassa?","Sillä hetkellä tulivat opetuslapset Jesuksen tykö, sanoen: kuka siis on suurin taivaan valtakunnassa?"],[18,2,"Ja Jesus kutsui tykönsä lapsen, ja asetti sen heidän keskellensä,","Ja Jesus kutsui tykönsä lapsen, ja asetti sen heidän keskellensä,"],[18,3,"Ja sanoi: totisesti minä sanon teille: ellette käänny ja tule niinkuin lapset, niin ette suinkaan tule sisälle taivaan valtakuntaan.","Ja sanoi: totisesti minä sanon teille: ellette käänny ja tule niinkuin lapset, niin ette suinkaan tule sisälle taivaan valtakuntaan."],[18,4,"Sentähden joka itsensä alentaa niinkuin tämä lapsi, se on suurin taivaan valtakunnassa.","Sentähden joka itsensä alentaa niinkuin tämä lapsi, se on suurin taivaan valtakunnassa."],[18,5,"Ja joka holhoo senkaltaisen lapsen minun nimeeni, hän holhoo minun.","Ja joka holhoo senkaltaisen lapsen minun nimeeni, hän holhoo minun."],[18,6,"Mutta joka pahentaa yhden näistä pienimmistä, jotka uskovat minun päälleni, parempi hänen olis, että myllyn kivi ripustettaisiin hänen kaulaansa, ja hän upotettaisiin meren syvyyteen.","Mutta joka pahentaa yhden näistä pienimmistä, jotka uskovat minun päälleni, parempi hänen olis, että myllyn kivi ripustettaisiin hänen kaulaansa, ja hän upotettaisiin meren syvyyteen."],[18,7,"Voi maailmaa pahennusten tähden, sillä pahennukset kumminkin tulevat! Voi kuitenkin sitä ihmistä, jonka kautta pahennus tulee!","Voi maailmaa pahennusten tähden, sillä pahennukset kumminkin tulevat! Voi kuitenkin sitä ihmistä, jonka kautta pahennus tulee!"],[18,8,"Mutta jos kätes taikka jalkas pahentaa sinun, niin leikkaa ne pois, ja heitä pois tyköäs. Parempi on sinun elämään sisälle mennä ontuvana taikka raajarikkona, kuin että sinulla olis kaksi kättä eli kaksi jalkaa, ja sinä heitettäisiin ijankaikkiseen tuleen.","Mutta jos kätes taikka jalkas pahentaa sinun, niin leikkaa ne pois, ja heitä pois tyköäs. Parempi on sinun elämään sisälle mennä ontuvana taikka raajarikkona, kuin että sinulla olis kaksi kättä eli kaksi jalkaa, ja sinä heitettäisiin ijankaikkiseen tuleen."],[18,9,"Ja jos silmäs pahentaa sinun, niin puhkaise se ulos, ja heitä pois tyköäs. Parempi on sinun silmäpuolena elämään sisälle mennä, kuin että sinulla olis kaksi silmää, ja sinä heitettäisiin helvetin tuleen.","Ja jos silmäs pahentaa sinun, niin puhkaise se ulos, ja heitä pois tyköäs. Parempi on sinun silmäpuolena elämään sisälle mennä, kuin että sinulla olis kaksi silmää, ja sinä heitettäisiin helvetin tuleen."],[18,10,"Katsokaat, ettette katso ylön yhtäkään näistä pienimmistä; sillä minä sanon teille: heidän enkelinsä taivaissa näkevät aina minun isäni kasvot, joka on taivaissa.","Katsokaat, ettette katso ylön yhtäkään näistä pienimmistä; sillä minä sanon teille: heidän enkelinsä taivaissa näkevät aina minun isäni kasvot, joka on taivaissa."],[18,11,"Sillä Ihmisen Poika tuli autuaaksi tekemään sitä, mikä kadonnut oli.","Sillä Ihmisen Poika tuli autuaaksi tekemään sitä, mikä kadonnut oli."],[18,12,"Mitä te luulette? jos jollakin ihmisellä olis sata lammasta, ja yksi heistä eksyis: eikö hän jättäisi yhdeksänkymmentä ja yhdeksän, ja menis vuorelle, ja etsis eksynyttä?","Mitä te luulette? jos jollakin ihmisellä olis sata lammasta, ja yksi heistä eksyis: eikö hän jättäisi yhdeksänkymmentä ja yhdeksän, ja menis vuorelle, ja etsis eksynyttä?"],[18,13,"Ja jos niin tapahtuu, että hän löytää sen, totisesti sanon minä teille: hän iloitsee enemmin siitä kuin yhdeksästäkymmenestä ja yhdeksästä, jotka ei eksyneet.","Ja jos niin tapahtuu, että hän löytää sen, totisesti sanon minä teille: hän iloitsee enemmin siitä kuin yhdeksästäkymmenestä ja yhdeksästä, jotka ei eksyneet."],[18,14,"Niin ei ole myös teidän Isänne tahto, joka on taivaissa, että joku näistä pienimmistä hukkuis.","Niin ei ole myös teidän Isänne tahto, joka on taivaissa, että joku näistä pienimmistä hukkuis."],[18,15,"Mutta jos sinun veljes rikkoo sinua vstaan, niin mene ja nuhtele häntä kahden kesken yksinänsä. Jos hän sinua kuulee, niin sinä olet veljes voittanut.","Mutta jos sinun veljes rikkoo sinua vstaan, niin mene ja nuhtele häntä kahden kesken yksinänsä. Jos hän sinua kuulee, niin sinä olet veljes voittanut."],[18,16,"Mutta jos ei hän sinua kuule, niin ota vielä yksi eli kaksi kanssas, että kaikki asia kahden eli kolmen todistajan suussa olis.","Mutta jos ei hän sinua kuule, niin ota vielä yksi eli kaksi kanssas, että kaikki asia kahden eli kolmen todistajan suussa olis."],[18,17,"Mutta ellei hän niitä tahdo kuulla, niin sano seurakunnalle; ellei hän seurakuntaa tottele, niin pidä häntä pakanana ja Publikanina.","Mutta ellei hän niitä tahdo kuulla, niin sano seurakunnalle; ellei hän seurakuntaa tottele, niin pidä häntä pakanana ja Publikanina."],[18,18,"Totisesti sanon minä teille: kaikki, mitä te maan päällä sidotte, pitää myös oleman sidotut taivaissa: ja kaikki, mitä te päästätte maan päällä, pitää myös oleman päästetyt taivaassa.","Totisesti sanon minä teille: kaikki, mitä te maan päällä sidotte, pitää myös oleman sidotut taivaissa: ja kaikki, mitä te päästätte maan päällä, pitää myös oleman päästetyt taivaassa."],[18,19,"Taas sanon minä teille: missä ikänä asiassa kaksi teistä sopivat maan päällä; jota he rukoilevat, sen heidän pitää saaman minun Isältäni, joka on taivaissa.","Taas sanon minä teille: missä ikänä asiassa kaksi teistä sopivat maan päällä; jota he rukoilevat, sen heidän pitää saaman minun Isältäni, joka on taivaissa."],[18,20,"Sillä kussa kaksi taikka kolme tulevat kokoon minun nimeeni, siinä minä olen heidän keskellänsä.","Sillä kussa kaksi taikka kolme tulevat kokoon minun nimeeni, siinä minä olen heidän keskellänsä."],[18,21,"Silloin Pietari tuli hänen tykönsä, ja sanoi: Herra, kuinka usein minun pitää veljelleni, joka rikkoo minua vastaan, antaman anteeksi? onko seitsemässä kerrassa kyllä?","Silloin Pietari tuli hänen tykönsä, ja sanoi: Herra, kuinka usein minun pitää veljelleni, joka rikkoo minua vastaan, antaman anteeksi? onko seitsemässä kerrassa kyllä?"],[18,22,"Sanoi Jesus hänelle: en minä sano sinulle ainoastaan seitsemän kertaa, mutta seitsemänkymmentä kertaa seitsemän.","Sanoi Jesus hänelle: en minä sano sinulle ainoastaan seitsemän kertaa, mutta seitsemänkymmentä kertaa seitsemän."],[18,23,"Sentähden on taivaan valtakunta kuninkaaseen verrattu, joka tahtoi lukua laskea palveliainsa kanssa.","Sentähden on taivaan valtakunta kuninkaaseen verrattu, joka tahtoi lukua laskea palveliainsa kanssa."],[18,24,"Ja kuin hän rupesi laskemaan, tuli yksi hänen eteensä, joka oli hänelle velkaa kymmenentuhatta leiviskää.","Ja kuin hän rupesi laskemaan, tuli yksi hänen eteensä, joka oli hänelle velkaa kymmenentuhatta leiviskää."],[18,25,"Mutta ettei hänellä ollut varaa maksaa, käski hänen herransa hänen myytää, ja hänen emäntänsä ja lapsensa, ja kaikki mitä hänellä oli, ja maksettaa.","Mutta ettei hänellä ollut varaa maksaa, käski hänen herransa hänen myytää, ja hänen emäntänsä ja lapsensa, ja kaikki mitä hänellä oli, ja maksettaa."],[18,26,"Niin palvelia lankesi maahan ja rukoili häntä, sanoen: herra, ole kärsivällinen minun kanssani, ja minä maksan kaikki sinulle.","Niin palvelia lankesi maahan ja rukoili häntä, sanoen: herra, ole kärsivällinen minun kanssani, ja minä maksan kaikki sinulle."],[18,27,"Niin armahti herra palveliaa, päästi hänen, ja antoi hänelle velan anteeksi.","Niin armahti herra palveliaa, päästi hänen, ja antoi hänelle velan anteeksi."],[18,28,"Niin palvelia meni ulos, ja löysi yhden kanssapalvelioistansa, joka hänelle oli velkaa sata penninkiä; ja hän tarttui häneen, ja kiristi häntä kurkusta, sanoen: maksa minulle velkas.","Niin palvelia meni ulos, ja löysi yhden kanssapalvelioistansa, joka hänelle oli velkaa sata penninkiä; ja hän tarttui häneen, ja kiristi häntä kurkusta, sanoen: maksa minulle velkas."],[18,29,"Niin hänen kanssapalveliansa lankesi maahan hänen jalkainsa juureen, ja rukoili häntä, sanoen: ole kärsivällinen minun kanssani, ja minä maksan kaikki sinulle.","Niin hänen kanssapalveliansa lankesi maahan hänen jalkainsa juureen, ja rukoili häntä, sanoen: ole kärsivällinen minun kanssani, ja minä maksan kaikki sinulle."],[18,30,"Mutta ei hän tahtonut, vaan meni ja heitti hänen torniin, siihenasti kuin hän velan maksais.","Mutta ei hän tahtonut, vaan meni ja heitti hänen torniin, siihenasti kuin hän velan maksais."],[18,31,"Mutta kuin muut hänen kanssapalveliainsa näkivät mitä tehtiin, murehtivat he sangen kovin, tulivat ja ilmoittivat herrallensa kaiken, mitä tehty oli.","Mutta kuin muut hänen kanssapalveliainsa näkivät mitä tehtiin, murehtivat he sangen kovin, tulivat ja ilmoittivat herrallensa kaiken, mitä tehty oli."],[18,32,"Silloin kutsui herra hänen eteensä, ja sanoi hänelle: sinä paha palvelia, minä annoin sinulle anteeksi kaiken velan, ettäs minua rukoilit:","Silloin kutsui herra hänen eteensä, ja sanoi hänelle: sinä paha palvelia, minä annoin sinulle anteeksi kaiken velan, ettäs minua rukoilit:"],[18,33,"Eikö myös sinun pitänyt armahtaman kanssapalveliaas, niinkuin minäkin armahdin sinua?","Eikö myös sinun pitänyt armahtaman kanssapalveliaas, niinkuin minäkin armahdin sinua?"],[18,34,"Ja hänen herransa vihastui, ja antoi hänen pyöveleille, siihenasti kuin hän maksais kaikki, mitä hän oli hänelle velkaa.","Ja hänen herransa vihastui, ja antoi hänen pyöveleille, siihenasti kuin hän maksais kaikki, mitä hän oli hänelle velkaa."],[18,35,"Niin myös minun taivaallinen Isäni tekee teille, jollette kukin veljellensä teidän sydämistänne anna anteeksi heidän rikoksiansa.","Niin myös minun taivaallinen Isäni tekee teille, jollette kukin veljellensä teidän sydämistänne anna anteeksi heidän rikoksiansa."],[19,1,"Ja tapahtui, kuin Jesus oli lopettanut nämät puheet, läksi hän Galileasta ja tuli Juudean maan rajoille, sille puolelle Jordania.","Ja tapahtui, kuin Jesus oli lopettanut nämät puheet, läksi hän Galileasta ja tuli Juudean maan rajoille, sille puolelle Jordania."],[19,2,"Ja paljo kansaa seurasi häntä, ja hän paransi heitä siellä.","Ja paljo kansaa seurasi häntä, ja hän paransi heitä siellä."],[19,3,"Ja Pharisealaiset tulivat hänen tykönsä, kiusasivat häntä, ja sanoivat hänelle: saako mies eritä vaimostaan kaikkinaisen syyn tähden?","Ja Pharisealaiset tulivat hänen tykönsä, kiusasivat häntä, ja sanoivat hänelle: saako mies eritä vaimostaan kaikkinaisen syyn tähden?"],[19,4,"Niin hän vastasi ja sanoi heille: ettekö te ole lukeneet: joka alusta ihmisen teki, mieheksi ja vaimoksi hän heidät teki?","Niin hän vastasi ja sanoi heille: ettekö te ole lukeneet: joka alusta ihmisen teki, mieheksi ja vaimoksi hän heidät teki?"],[19,5,"Ja sanoi: sentähden pitää ihmisen luopuman isästänsä ja äidistänsä, ja vaimoonsa sidottu oleman, ja ne kaksi tulevat yhdeksi lihaksi:","Ja sanoi: sentähden pitää ihmisen luopuman isästänsä ja äidistänsä, ja vaimoonsa sidottu oleman, ja ne kaksi tulevat yhdeksi lihaksi:"],[19,6,"Niin ei he ole enään kaksi, mutta yksi liha. Jonka siis Jumala yhteen sovitti, ei pidä ihmisen sitä eroittaman.","Niin ei he ole enään kaksi, mutta yksi liha. Jonka siis Jumala yhteen sovitti, ei pidä ihmisen sitä eroittaman."],[19,7,"He sanoivat hänelle: miksi Moses käski antaa erokirjan ja hyljätä hänen?","He sanoivat hänelle: miksi Moses käski antaa erokirjan ja hyljätä hänen?"],[19,8,"Sanoi hän heille: teidän sydämenne kovuuden tähden salli Moses teidän eritä vaimoistanne; vaan ei alusta niin ollut.","Sanoi hän heille: teidän sydämenne kovuuden tähden salli Moses teidän eritä vaimoistanne; vaan ei alusta niin ollut."],[19,9,"Mutta minä sanon teille: kuka ikänä hylkää vaimonsa muutoin kuin huoruuden tähden, ja nai toisen, hän tekee huorin; ja joka hyljätyn ottaa, hän tekee huorin.","Mutta minä sanon teille: kuka ikänä hylkää vaimonsa muutoin kuin huoruuden tähden, ja nai toisen, hän tekee huorin; ja joka hyljätyn ottaa, hän tekee huorin."],[19,10,"Hänen opetuslapsensa sanoivat hänelle: jos miehen asia niin on vaimon kanssa, ei sitte ole hyvä naida.","Hänen opetuslapsensa sanoivat hänelle: jos miehen asia niin on vaimon kanssa, ei sitte ole hyvä naida."],[19,11,"Niin hän sanoi heille: ei tätä sanaa kaikki käsitä, vaan ne, joille se annettu on.","Niin hän sanoi heille: ei tätä sanaa kaikki käsitä, vaan ne, joille se annettu on."],[19,12,"Sillä muutamat ovat kuohitut, jotka äitinsä kohdusta niin syntyneet ovat: ja ovat kuohitut, jotka ihmisiltä kuohitut ovat: ja ovat kuohitut, jotka taivaan valtakunnan tähden itse kuohinneet ovat. Joka sen taitaa käsittää, se käsittäkään.","Sillä muutamat ovat kuohitut, jotka äitinsä kohdusta niin syntyneet ovat: ja ovat kuohitut, jotka ihmisiltä kuohitut ovat: ja ovat kuohitut, jotka taivaan valtakunnan tähden itse kuohinneet ovat. Joka sen taitaa käsittää, se käsittäkään."],[19,13,"Silloin vietiin hänen tykönsä lapsia, että hän laskis kätensä heidän päällensä ja rukoilis; mutta opetuslapset nuhtelivat heitä.","Silloin vietiin hänen tykönsä lapsia, että hän laskis kätensä heidän päällensä ja rukoilis; mutta opetuslapset nuhtelivat heitä."],[19,14,"Mutta Jesus sanoi: sallikaat lasten olla, ja älkäät kieltäkö heitä tulemasta minun tyköni: sillä senkaltaisten on taivaan valtakunta.","Mutta Jesus sanoi: sallikaat lasten olla, ja älkäät kieltäkö heitä tulemasta minun tyköni: sillä senkaltaisten on taivaan valtakunta."],[19,15,"Ja kuin hän oli pannut kätensä heidän päällensä, meni hän sieltä pois.","Ja kuin hän oli pannut kätensä heidän päällensä, meni hän sieltä pois."],[19,16,"Ja katso, yksi tuli ja sanoi hänelle: hyvä Mestari! mitä hyvää minun pitää tekemän, että minä saisin ijankaikkisen elämän?","Ja katso, yksi tuli ja sanoi hänelle: hyvä Mestari! mitä hyvää minun pitää tekemän, että minä saisin ijankaikkisen elämän?"],[19,17,"Niin hän sanoi hänelle: miksi sinä kutsut minun hyväksi? Ei ole kenkään hyvä, vaan yksi, Jumala. Mutta jos sinä tahdot elämään sisälle tulla, niin pidä käskyt.","Niin hän sanoi hänelle: miksi sinä kutsut minun hyväksi? Ei ole kenkään hyvä, vaan yksi, Jumala. Mutta jos sinä tahdot elämään sisälle tulla, niin pidä käskyt."],[19,18,"Hän sanoi hänelle: kutka? Jesus sanoi: ei sinun pidä tappaman: ei sinun pidä huorin tekemän: ei sinun pidä varastaman: ei sinun pidä väärin todistaman:","Hän sanoi hänelle: kutka? Jesus sanoi: ei sinun pidä tappaman: ei sinun pidä huorin tekemän: ei sinun pidä varastaman: ei sinun pidä väärin todistaman:"],[19,19,"Kunnioita isääs ja äitiäs: ja sinun pitää rakastaman lähimmäistäs niinkuin itse sinuas.","Kunnioita isääs ja äitiäs: ja sinun pitää rakastaman lähimmäistäs niinkuin itse sinuas."],[19,20,"Sanoi nuorukainen hänelle: kaikki nämät olen minä pitänyt nuoruudestani; mitä vielä minulta puuttuu?","Sanoi nuorukainen hänelle: kaikki nämät olen minä pitänyt nuoruudestani; mitä vielä minulta puuttuu?"],[19,21,"Sanoi Jesus hänelle: jos sinä tahdot olla täydellinen, niin mene ja myy mitä sinulla on, ja anna vaivaisille: ja sinun pitää saaman tavaran taivaassa; ja tule ja seuraa minua.","Sanoi Jesus hänelle: jos sinä tahdot olla täydellinen, niin mene ja myy mitä sinulla on, ja anna vaivaisille: ja sinun pitää saaman tavaran taivaassa; ja tule ja seuraa minua."],[19,22,"Mutta kuin nuorukainen kuuli sen puheen, meni hän pois murheissansa; sillä hänellä oli paljo tavaraa.","Mutta kuin nuorukainen kuuli sen puheen, meni hän pois murheissansa; sillä hänellä oli paljo tavaraa."],[19,23,"Mutta Jesus sanoi opetuslapsillensa: totisesti sanon minä teille: rikas tulee työläästi taivaan valtakuntaan.","Mutta Jesus sanoi opetuslapsillensa: totisesti sanon minä teille: rikas tulee työläästi taivaan valtakuntaan."],[19,24,"Ja taas sanon minä teille: huokiampi on kamelin käydä neulan silmän lävitse, kuin rikkaan tulla Jumalan valtakuntaan.","Ja taas sanon minä teille: huokiampi on kamelin käydä neulan silmän lävitse, kuin rikkaan tulla Jumalan valtakuntaan."],[19,25,"Mutta koska hänen opetuslapsensa sen kuulivat, peljästyivät he sangen kovin, sanoen: kuka siis taitaa autuaaksi tulla?","Mutta koska hänen opetuslapsensa sen kuulivat, peljästyivät he sangen kovin, sanoen: kuka siis taitaa autuaaksi tulla?"],[19,26,"Niin Jesus katsahti heidän päällensä ja sanoi heille: ihmisten tykönä on se mahdotoin, mutta Jumalan tykönä ovat kaikki mahdolliset.","Niin Jesus katsahti heidän päällensä ja sanoi heille: ihmisten tykönä on se mahdotoin, mutta Jumalan tykönä ovat kaikki mahdolliset."],[19,27,"Silloin vastasi Pietari ja sanoi hänelle: katso, me luovuimme kaikista ja seuraamme sinua: mitä siis meidän siitä on?","Silloin vastasi Pietari ja sanoi hänelle: katso, me luovuimme kaikista ja seuraamme sinua: mitä siis meidän siitä on?"],[19,28,"Niin sanoi Jesus heille: totisesti sanon minä teille, te, jotka minua olette seuranneet, uudessa syntymisessä, kuin Ihmisen Poika istuu kunniansa istuimella, pitää myös teidän istuman kahdellatoistakymmenellä istuimella, tuomiten kahtatoistakymmentä Israelin sukukuntaa.","Niin sanoi Jesus heille: totisesti sanon minä teille, te, jotka minua olette seuranneet, uudessa syntymisessä, kuin Ihmisen Poika istuu kunniansa istuimella, pitää myös teidän istuman kahdellatoistakymmenellä istuimella, tuomiten kahtatoistakymmentä Israelin sukukuntaa."],[19,29,"Ja jokainen, joka luopui huoneista, taikka veljistä, taikka sisarista, taikka isästä, taikka äidistä, taikka emännästä, taikka lapsista, taikka pellosta, minun nimeni tähden, hänen pitää satakertaisesti saaman, ja ijankaikkisen elämän perimän.","Ja jokainen, joka luopui huoneista, taikka veljistä, taikka sisarista, taikka isästä, taikka äidistä, taikka emännästä, taikka lapsista, taikka pellosta, minun nimeni tähden, hänen pitää satakertaisesti saaman, ja ijankaikkisen elämän perimän."],[19,30,"Mutta monta ensimäistä tulee viimeiseksi ja viimeistä ensimäiseksi.","Mutta monta ensimäistä tulee viimeiseksi ja viimeistä ensimäiseksi."],[20,1,"Sillä taivaan valtakunta on perheenisännän vertainen, joka varhain huomeneltain läksi ulos palkkaamaan työväkeä viinamäkeensä.","Sillä taivaan valtakunta on perheenisännän vertainen, joka varhain huomeneltain läksi ulos palkkaamaan työväkeä viinamäkeensä."],[20,2,"Ja kuin hän oli sopinut työmiesten kanssa päiväpenningistä, lähetti hän heidät viinamäkeensä.","Ja kuin hän oli sopinut työmiesten kanssa päiväpenningistä, lähetti hän heidät viinamäkeensä."],[20,3,"Ja hän meni ulos liki kolmannella hetkellä, ja näki muita seisovan turulla joutilaina,","Ja hän meni ulos liki kolmannella hetkellä, ja näki muita seisovan turulla joutilaina,"],[20,4,"Ja sanoi heille: menkäät tekin viinamäkeen, ja mitä kohtuullinen on, minä annan teille. Niin he menivät.","Ja sanoi heille: menkäät tekin viinamäkeen, ja mitä kohtuullinen on, minä annan teille. Niin he menivät."],[20,5,"Taas hän meni ulos liki kuudennella ja yhdeksännellä hetkellä, ja teki myös niin.","Taas hän meni ulos liki kuudennella ja yhdeksännellä hetkellä, ja teki myös niin."],[20,6,"Mutta yhdellätoistakymmenennellä hetkellä läksi hän ulos, ja löysi muita joutilaina seisomasta, ja sanoi heille: miksi te tässä kaiken päivän joutilaina seisotte?","Mutta yhdellätoistakymmenennellä hetkellä läksi hän ulos, ja löysi muita joutilaina seisomasta, ja sanoi heille: miksi te tässä kaiken päivän joutilaina seisotte?"],[20,7,"He sanoivat hänelle: sillä ei ole kenkään meitä palkannut. Hän sanoi heille: menkäät tekin minun viinamäkeeni, ja mitä kohtuus on, pitää teidän saaman.","He sanoivat hänelle: sillä ei ole kenkään meitä palkannut. Hän sanoi heille: menkäät tekin minun viinamäkeeni, ja mitä kohtuus on, pitää teidän saaman."],[20,8,"Mutta kuin ehtoo tuli, sanoi viinamäen isäntä perheensä haltialle: kutsu työväki, ja maksa heidän palkkansa, ruveten viimeisistä ensimäisiin asti.","Mutta kuin ehtoo tuli, sanoi viinamäen isäntä perheensä haltialle: kutsu työväki, ja maksa heidän palkkansa, ruveten viimeisistä ensimäisiin asti."],[20,9,"Ja kuin ne tulivat, jotka liki yhdellätoistakymmenennellä hetkellä tulleet olivat, saivat he kukin penninkinsä.","Ja kuin ne tulivat, jotka liki yhdellätoistakymmenennellä hetkellä tulleet olivat, saivat he kukin penninkinsä."],[20,10,"Mutta kuin ensimäiset tulivat, luulivat he enemmän saavansa; ja he myös saivat kukin penninkinsä.","Mutta kuin ensimäiset tulivat, luulivat he enemmän saavansa; ja he myös saivat kukin penninkinsä."],[20,11,"Ja kuin he saivat, napisivat he perheenisäntää vastaan,","Ja kuin he saivat, napisivat he perheenisäntää vastaan,"],[20,12,"Sanoen: nämät viimeiset ovat yhden hetken työtä tehneet, ja sinä teit heidät meidän verraksemme, jotka olemme kantaneet päivän kuorman ja helteen.","Sanoen: nämät viimeiset ovat yhden hetken työtä tehneet, ja sinä teit heidät meidän verraksemme, jotka olemme kantaneet päivän kuorman ja helteen."],[20,13,"Niin hän vastasi ja sanoi yhdelle heistä: ystäväni, en tee minä sinulle vääryyttä; etkös sopinut minun kanssani määrätystä penningistä?","Niin hän vastasi ja sanoi yhdelle heistä: ystäväni, en tee minä sinulle vääryyttä; etkös sopinut minun kanssani määrätystä penningistä?"],[20,14,"Ota se, mikä sinun tulee, ja mene matkaas; mutta minä tahdon tälle viimeiselle antaa niinkuin sinullekin.","Ota se, mikä sinun tulee, ja mene matkaas; mutta minä tahdon tälle viimeiselle antaa niinkuin sinullekin."],[20,15,"Vai enkö minä saa tehdä minun kalustani mitä minä tahdon? taikka katsotkos sentähden karsaasti, että minä hyvä olen?","Vai enkö minä saa tehdä minun kalustani mitä minä tahdon? taikka katsotkos sentähden karsaasti, että minä hyvä olen?"],[20,16,"Niin viimeiset tulevat ensimäisiksi ja ensimäiset viimeisiksi. Sillä monta ovat kutsutut, mutta harvat valitut.","Niin viimeiset tulevat ensimäisiksi ja ensimäiset viimeisiksi. Sillä monta ovat kutsutut, mutta harvat valitut."],[20,17,"Ja Jesus meni ylös Jerusalemiin, ja otti kaksitoistakymmentä opetuslastansa erinänsä tiellä tykönsä, ja sanoi heille:","Ja Jesus meni ylös Jerusalemiin, ja otti kaksitoistakymmentä opetuslastansa erinänsä tiellä tykönsä, ja sanoi heille:"],[20,18,"Katso, me menemme ylös Jerusalemiin, ja Ihmisen Poika ylönannetaan pappein päämiehille ja kirjanoppineille; ja he tuomitsevat hänen kuolemaan,","Katso, me menemme ylös Jerusalemiin, ja Ihmisen Poika ylönannetaan pappein päämiehille ja kirjanoppineille; ja he tuomitsevat hänen kuolemaan,"],[20,19,"Ja antavat ylön hänen pakanoille pilkattaa, ja ruoskittaa, ja ristiinnaulittaa: ja kolmantena päivänä on hän nouseva ylös.","Ja antavat ylön hänen pakanoille pilkattaa, ja ruoskittaa, ja ristiinnaulittaa: ja kolmantena päivänä on hän nouseva ylös."],[20,20,"Silloin tuli hänen tykönsä Zebedeuksen poikain äiti poikinensa, kumarsi ja anoi jotakin häneltä.","Silloin tuli hänen tykönsä Zebedeuksen poikain äiti poikinensa, kumarsi ja anoi jotakin häneltä."],[20,21,"Vaan hän sanoi hänelle: mitäs tahdot? Sanoi hän hänelle: sano, että nämät kaksi minun poikaani istuisivat, yksi sinun oikialla kädelläs ja toinen vasemmallas, sinun valtakunnassas.","Vaan hän sanoi hänelle: mitäs tahdot? Sanoi hän hänelle: sano, että nämät kaksi minun poikaani istuisivat, yksi sinun oikialla kädelläs ja toinen vasemmallas, sinun valtakunnassas."],[20,22,"Niin Jesus vastaten sanoi: ette tiedä, mitä te anotte. Voitteko juoda sen kalkin, jonka minun pitää juoman, ja kastettaa sillä kasteella, jolla minä kastetaan? He sanoivat hänelle: me voimme.","Niin Jesus vastaten sanoi: ette tiedä, mitä te anotte. Voitteko juoda sen kalkin, jonka minun pitää juoman, ja kastettaa sillä kasteella, jolla minä kastetaan? He sanoivat hänelle: me voimme."],[20,23,"Ja hän sanoi heille: minun kalkkini tosin te juotte ja sillä kasteella, jolla minä kastetaan, te kastetaan; mutta istua minun oikialla kädelläni, taikka vasemmalla, ei ole minun antamisellani, vaan joille se on valmistettu minun Isältäni.","Ja hän sanoi heille: minun kalkkini tosin te juotte ja sillä kasteella, jolla minä kastetaan, te kastetaan; mutta istua minun oikialla kädelläni, taikka vasemmalla, ei ole minun antamisellani, vaan joille se on valmistettu minun Isältäni."],[20,24,"Ja kuin ne kymmenen sen kuulivat, närkästyivät he niistä kahdesta veljeksestä.","Ja kuin ne kymmenen sen kuulivat, närkästyivät he niistä kahdesta veljeksestä."],[20,25,"Mutta Jesus kutsui heidät tykönsä ja sanoi: te tiedätte, että kansain päämiehet vallitsevat heitä, ja ylimmäisillä on valta heidän ylitsensä.","Mutta Jesus kutsui heidät tykönsä ja sanoi: te tiedätte, että kansain päämiehet vallitsevat heitä, ja ylimmäisillä on valta heidän ylitsensä."],[20,26,"Vaan ei niin pidä oleman teidän keskenänne; mutta joka tahtoo teidän seassanne suurin olla, se olkoon teidän palvelianne;","Vaan ei niin pidä oleman teidän keskenänne; mutta joka tahtoo teidän seassanne suurin olla, se olkoon teidän palvelianne;"],[20,27,"Ja joka tahtoo teidän seassanne ensimäinen olla, se olkoon teidän palvelianne.","Ja joka tahtoo teidän seassanne ensimäinen olla, se olkoon teidän palvelianne."],[20,28,"Niinkuin ei Ihmisen Poika tullut, että häntä piti palveltaman, mutta että hän palvelis, ja antais henkensä lunastukseksi monen edestä.","Niinkuin ei Ihmisen Poika tullut, että häntä piti palveltaman, mutta että hän palvelis, ja antais henkensä lunastukseksi monen edestä."],[20,29,"Ja heidän lähteissänsä Jerikosta, seurasi häntä paljo kansaa.","Ja heidän lähteissänsä Jerikosta, seurasi häntä paljo kansaa."],[20,30,"Ja katso, kaksi sokiaa istuivat tien ohessa. Kuin he kuulivat, että Jesus kävi ohitse, huusivat he, sanoen: Herra, Davidin Poika, armahda meitä!","Ja katso, kaksi sokiaa istuivat tien ohessa. Kuin he kuulivat, että Jesus kävi ohitse, huusivat he, sanoen: Herra, Davidin Poika, armahda meitä!"],[20,31,"Niin kansa torui heitä vaikenemaan. Mutta he huusivat enemmin, sanoen: Herra, Davidin Poika, armahda meitä!","Niin kansa torui heitä vaikenemaan. Mutta he huusivat enemmin, sanoen: Herra, Davidin Poika, armahda meitä!"],[20,32,"Ja Jesus seisahti, ja kutsui heidät tykönsä, ja sanoi: mitä te tahdotte, että minun pitää teille tekemän?","Ja Jesus seisahti, ja kutsui heidät tykönsä, ja sanoi: mitä te tahdotte, että minun pitää teille tekemän?"],[20,33,"Sanoivat he hänelle: Herra, että meidän silmämme aukenisivat.","Sanoivat he hänelle: Herra, että meidän silmämme aukenisivat."],[20,34,"Niin Jesus armahti heitä ja tarttui heidän silmiinsä, ja he saivat kohta näkönsä ja seurasivat häntä.","Niin Jesus armahti heitä ja tarttui heidän silmiinsä, ja he saivat kohta näkönsä ja seurasivat häntä."],[21,1,"Ja kuin he lähestyivät Jerusalemia ja tulivat Betphageen öljymäen tykö, lähetti Jesus kaksi opetuslasta,","Ja kuin he lähestyivät Jerusalemia ja tulivat Betphageen öljymäen tykö, lähetti Jesus kaksi opetuslasta,"],[21,2,"Sanoen heille: menkäät kylään, joka on edessänne, ja te löydätte kohta aasintamman sidottuna, ja varsan hänen kanssansa: päästäkäät ne ja tuokaat minulle.","Sanoen heille: menkäät kylään, joka on edessänne, ja te löydätte kohta aasintamman sidottuna, ja varsan hänen kanssansa: päästäkäät ne ja tuokaat minulle."],[21,3,"Ja jos joku teille jotakin sanoo, niin sanokaat: Herra niitä tarvitsee, ja kohta hän laskee heidät.","Ja jos joku teille jotakin sanoo, niin sanokaat: Herra niitä tarvitsee, ja kohta hän laskee heidät."],[21,4,"Mutta tämä kaikki tapahtui, että täytettäisiin, mikä sanottu oli prophetan kautta, joka sanoo:","Mutta tämä kaikki tapahtui, että täytettäisiin, mikä sanottu oli prophetan kautta, joka sanoo:"],[21,5,"Sanokaat Zionin tyttärelle: katso, sinun Kuninkaas tulee sinulle siviä, istuen aasintamman päällä ja ikeen alaisen aasin varsan päällä.","Sanokaat Zionin tyttärelle: katso, sinun Kuninkaas tulee sinulle siviä, istuen aasintamman päällä ja ikeen alaisen aasin varsan päällä."],[21,6,"Niin opetuslapset menivät ja tekivät niinkuin Jesus heille käskenyt oli,","Niin opetuslapset menivät ja tekivät niinkuin Jesus heille käskenyt oli,"],[21,7,"Ja taluttivat aasintamman ja varsan, ja panivat niiden päälle vaatteensa, ja istuttivat hänen niiden päälle.","Ja taluttivat aasintamman ja varsan, ja panivat niiden päälle vaatteensa, ja istuttivat hänen niiden päälle."],[21,8,"Niin enin osa kansasta hajoitti vaatteensa tielle, ja muut karsivat oksia puista ja hajoittivat tielle.","Niin enin osa kansasta hajoitti vaatteensa tielle, ja muut karsivat oksia puista ja hajoittivat tielle."],[21,9,"Mutta kansa, joka edellä kävi, ja jotka seurasivat, huusivat, sanoen: hosianna Davidin Pojalle! kiitetty olkoon se, joka tulee Herran nimeen! hosianna korkeudessa!","Mutta kansa, joka edellä kävi, ja jotka seurasivat, huusivat, sanoen: hosianna Davidin Pojalle! kiitetty olkoon se, joka tulee Herran nimeen! hosianna korkeudessa!"],[21,10,"Ja kuin hän tuli Jerusalemiin, nousi koko kaupunki, sanoen: kuka on tämä?","Ja kuin hän tuli Jerusalemiin, nousi koko kaupunki, sanoen: kuka on tämä?"],[21,11,"Niin kansa sanoi: tämä on Jesus, propheta Galilean Natsaretista.","Niin kansa sanoi: tämä on Jesus, propheta Galilean Natsaretista."],[21,12,"Ja Jesus meni sisälle Jumalan templiin, ja ajoi ulos kaikki, jotka myivät ja ostivat templissä, ja vaihettajain pöydät ja kyyhkyisten kaupitsiain istuimet hän kukisti,","Ja Jesus meni sisälle Jumalan templiin, ja ajoi ulos kaikki, jotka myivät ja ostivat templissä, ja vaihettajain pöydät ja kyyhkyisten kaupitsiain istuimet hän kukisti,"],[21,13,"Ja sanoi heille: kirjoitettu on: minun huoneeni pitää rukoushuoneeksi kutsuttaman; mutta te olette sen tehneet ryöväritten luolaksi.","Ja sanoi heille: kirjoitettu on: minun huoneeni pitää rukoushuoneeksi kutsuttaman; mutta te olette sen tehneet ryöväritten luolaksi."],[21,14,"Ja hänen tykönsä tulivat sokiat ja ontuvat templissä, ja hän paransi heidät.","Ja hänen tykönsä tulivat sokiat ja ontuvat templissä, ja hän paransi heidät."],[21,15,"Mutta kuin pappein päämiehet ja kirjanoppineet näkivät ne ihmeet, jotka hän teki, ja lapset templissä huutavan ja sanovan: hosianna Davidin Pojalle! närkästyivät he,","Mutta kuin pappein päämiehet ja kirjanoppineet näkivät ne ihmeet, jotka hän teki, ja lapset templissä huutavan ja sanovan: hosianna Davidin Pojalle! närkästyivät he,"],[21,16,"Ja sanoivat hänelle: kuuletkos, mitä nämät sanovat? Niin Jesus sanoi heille: kuulen kyllä. Ettekö te koskaan ole lukeneet: lasten ja imeväisten suusta olet sinä kiitoksen valmistanut?","Ja sanoivat hänelle: kuuletkos, mitä nämät sanovat? Niin Jesus sanoi heille: kuulen kyllä. Ettekö te koskaan ole lukeneet: lasten ja imeväisten suusta olet sinä kiitoksen valmistanut?"],[21,17,"Ja hän luopui heistä, ja meni ulos kaupungista Betaniaan, ja oli siellä yötä.","Ja hän luopui heistä, ja meni ulos kaupungista Betaniaan, ja oli siellä yötä."],[21,18,"Mutta huomeneltain kaupunkiin palatessansa isosi hän.","Mutta huomeneltain kaupunkiin palatessansa isosi hän."],[21,19,"Ja kuin hän näki fikunapuun tien ohessa, meni hän sen tykö, ja ei löytänyt siinä mitään muuta kuin lehdet ainoastaan; ja hän sanoi sille: älköön ikänä tästäkään edes sinusta hedelmää kasvako. Ja fikunapuu kohta kuivettui.","Ja kuin hän näki fikunapuun tien ohessa, meni hän sen tykö, ja ei löytänyt siinä mitään muuta kuin lehdet ainoastaan; ja hän sanoi sille: älköön ikänä tästäkään edes sinusta hedelmää kasvako. Ja fikunapuu kohta kuivettui."],[21,20,"Ja kuin opetuslapset sen näkivät, ihmettelivät he, sanoen: kuinka fikunapuu niin kohta kuivettui?","Ja kuin opetuslapset sen näkivät, ihmettelivät he, sanoen: kuinka fikunapuu niin kohta kuivettui?"],[21,21,"Jesus vastaten sanoi heille: totisesti sanon minä teille: jos teillä olis usko, ja ette epäilisi, niin ette ainoastaan tätä tekisi, mikä fikunapuulle tapahtui, vaan myös jos te sanoisitte tälle vuorelle: siirry ja kukistu mereen, niin se tapahtuis.","Jesus vastaten sanoi heille: totisesti sanon minä teille: jos teillä olis usko, ja ette epäilisi, niin ette ainoastaan tätä tekisi, mikä fikunapuulle tapahtui, vaan myös jos te sanoisitte tälle vuorelle: siirry ja kukistu mereen, niin se tapahtuis."],[21,22,"Ja kaikki, mitä te anotte rukouksessa, uskoen, sen te saatte.","Ja kaikki, mitä te anotte rukouksessa, uskoen, sen te saatte."],[21,23,"Ja kuin hän meni templiin, tulivat hänen opettaissansa hänen tykönsä pappein päämiehet ja kansan vanhimmat, sanoen: millä voimalla sinä näitä teet? taikka kuka sinulle antoi sen voiman?","Ja kuin hän meni templiin, tulivat hänen opettaissansa hänen tykönsä pappein päämiehet ja kansan vanhimmat, sanoen: millä voimalla sinä näitä teet? taikka kuka sinulle antoi sen voiman?"],[21,24,"Niin Jesus vastaten sanoi heille: minä tahdon myös teiltä kysyä yhden sanan: jos te sen minulle sanotte, niin minä myös teille sanon, millä voimalla minä näitä teen:","Niin Jesus vastaten sanoi heille: minä tahdon myös teiltä kysyä yhden sanan: jos te sen minulle sanotte, niin minä myös teille sanon, millä voimalla minä näitä teen:"],[21,25,"Kusta Johanneksen kaste oli, taivaastako taikka ihmisistä? Niin he ajattelivat isellensä, sanoen: jos me sanomme: taivaasta, niin hän sanoo meille: miksi ette siis häntä uskoneet?","Kusta Johanneksen kaste oli, taivaastako taikka ihmisistä? Niin he ajattelivat isellensä, sanoen: jos me sanomme: taivaasta, niin hän sanoo meille: miksi ette siis häntä uskoneet?"],[21,26,"Mutta jos me sanomme: se oli ihmisistä, niin me pelkäämme kansaa; sillä kaikki pitivät Johanneksen prophetana.","Mutta jos me sanomme: se oli ihmisistä, niin me pelkäämme kansaa; sillä kaikki pitivät Johanneksen prophetana."],[21,27,"Ja he vastaten sanoivat Jesukselle: emme tiedä. Sanoi hän heille: en minä myös sano teille, millä voimalla minä näitä teen.","Ja he vastaten sanoivat Jesukselle: emme tiedä. Sanoi hän heille: en minä myös sano teille, millä voimalla minä näitä teen."],[21,28,"Mutta kuinka te luulette? Yhdellä miehellä oli kaksi poikaa, ja hän meni ensimmäisen tykö, ja sanoi: poikani, mene tänäpänä tekemään työtä minun viinamäkeeni.","Mutta kuinka te luulette? Yhdellä miehellä oli kaksi poikaa, ja hän meni ensimmäisen tykö, ja sanoi: poikani, mene tänäpänä tekemään työtä minun viinamäkeeni."],[21,29,"Niin hän vastaten sanoi: en tahdo. Mutta sitte katui hän, ja meni.","Niin hän vastaten sanoi: en tahdo. Mutta sitte katui hän, ja meni."],[21,30,"Niin hän meni toisen tykö, ja sanoi myös niin. Mutta hän vastaten sanoi: kyllä minä menen, herra, ja ei mennytkään.","Niin hän meni toisen tykö, ja sanoi myös niin. Mutta hän vastaten sanoi: kyllä minä menen, herra, ja ei mennytkään."],[21,31,"Kumpi näistä kahdesta teki isänsä tahdon? He sanoivat hänelle: ensimäinen. Sanoi Jesus heille: totisesti sanon minä teille: Publikanit ja portot käyvät teidän edellänne Jumalan valtakuntaan.","Kumpi näistä kahdesta teki isänsä tahdon? He sanoivat hänelle: ensimäinen. Sanoi Jesus heille: totisesti sanon minä teille: Publikanit ja portot käyvät teidän edellänne Jumalan valtakuntaan."],[21,32,"Sillä Johannes tuli teidän tykönne vanhurskauden tiessä, ja ette häntä uskoneet: mutta Publikanit ja portot uskoivat hänen. Mutta te, jotka sen näitte, ette sittenkään parannusta tehneet, että te häntä olisitte uskoneet.","Sillä Johannes tuli teidän tykönne vanhurskauden tiessä, ja ette häntä uskoneet: mutta Publikanit ja portot uskoivat hänen. Mutta te, jotka sen näitte, ette sittenkään parannusta tehneet, että te häntä olisitte uskoneet."],[21,33,"Kuulkaat toinen vertaus: oli perheenisäntä, joka istutti viinamäen, ja pani aidan sen ympärille, ja kaivoi siihen viinakuurnan, ja rakensi tornin, ja pani sen vuorolle peltomiehille, ja vaelsi muille maille.","Kuulkaat toinen vertaus: oli perheenisäntä, joka istutti viinamäen, ja pani aidan sen ympärille, ja kaivoi siihen viinakuurnan, ja rakensi tornin, ja pani sen vuorolle peltomiehille, ja vaelsi muille maille."],[21,34,"Mutta kuin hedelmäin aika lähestyi, lähetti hän palveliansa peltomiesten tykö, ottamaan sen hedelmiä.","Mutta kuin hedelmäin aika lähestyi, lähetti hän palveliansa peltomiesten tykö, ottamaan sen hedelmiä."],[21,35,"Ja peltomiehet ottivat kiinni hänen palveliansa, ja yhden he pieksivät, toisen he tappoivat, kolmannen he kivittivät.","Ja peltomiehet ottivat kiinni hänen palveliansa, ja yhden he pieksivät, toisen he tappoivat, kolmannen he kivittivät."],[21,36,"Taas hän lähetti toiset palveliat, usiammat kuin ensimäiset, ja he tekivät heille myös niin.","Taas hän lähetti toiset palveliat, usiammat kuin ensimäiset, ja he tekivät heille myös niin."],[21,37,"Mutta viimein lähetti hän heidän tykönsä poikansa, sanoen: he karttavat poikaani.","Mutta viimein lähetti hän heidän tykönsä poikansa, sanoen: he karttavat poikaani."],[21,38,"Mutta kuin peltomiehet näkivät pojan, sanoivat he keskenänsä: tämä on perillinen; tulkaat, tappakaamme häntä, ja niin me saamme hänen perintönsä.","Mutta kuin peltomiehet näkivät pojan, sanoivat he keskenänsä: tämä on perillinen; tulkaat, tappakaamme häntä, ja niin me saamme hänen perintönsä."],[21,39,"Ja he ottivat hänen kiinni, sysäsivät ulos viinamäestä ja tappoivat.","Ja he ottivat hänen kiinni, sysäsivät ulos viinamäestä ja tappoivat."],[21,40,"Kun siis viinamäen isäntä tulee, mitä hän niiden peltomiesten tekee?","Kun siis viinamäen isäntä tulee, mitä hän niiden peltomiesten tekee?"],[21,41,"He sanoivat hänelle: ne pahat hän pahasti hukuttaa, ja antaa viinamäkensä toisille viinamäen miehille, jotka hänelle antavat hedelmät ajallansa.","He sanoivat hänelle: ne pahat hän pahasti hukuttaa, ja antaa viinamäkensä toisille viinamäen miehille, jotka hänelle antavat hedelmät ajallansa."],[21,42,"Sanoi Jesus heille: ettekö te ikänä Raamatuissa ole lukeneet: jonka kiven rakentajat hylkäsivät, se on tullut kulmakiveksi. Herralta on se tapahtunut, ja on ihmeellinen meidän silmäimme edessä.","Sanoi Jesus heille: ettekö te ikänä Raamatuissa ole lukeneet: jonka kiven rakentajat hylkäsivät, se on tullut kulmakiveksi. Herralta on se tapahtunut, ja on ihmeellinen meidän silmäimme edessä."],[21,43,"Sentähden sanon minä teille: Jumalan valtakunta pitää teiltä otettaman pois ja annettaman pakanoille, jotka sen hedelmän tekevät.","Sentähden sanon minä teille: Jumalan valtakunta pitää teiltä otettaman pois ja annettaman pakanoille, jotka sen hedelmän tekevät."],[21,44,"Ja joka lankee tähän kiveen, hän runnellaan. Mutta jonka päälle hän lankee, sen hän murentaa.","Ja joka lankee tähän kiveen, hän runnellaan. Mutta jonka päälle hän lankee, sen hän murentaa."],[21,45,"Ja kuin pappein päämiehet ja Pharisealaiset kuulivat hänen vertauksensa, ymmärsivät he, että hän heistä sanoi.","Ja kuin pappein päämiehet ja Pharisealaiset kuulivat hänen vertauksensa, ymmärsivät he, että hän heistä sanoi."],[21,46,"Ja kuin he pyysivät häntä ottaa kiinni, pelkäsivät he kansaa, sillä he pitivät hänen prophetana.","Ja kuin he pyysivät häntä ottaa kiinni, pelkäsivät he kansaa, sillä he pitivät hänen prophetana."],[22,1,"Ja Jesus vastaten puhui taas heille vertauksilla, sanoen:","Ja Jesus vastaten puhui taas heille vertauksilla, sanoen:"],[22,2,"Taivaan valtakunta on kuninkaan vertainen, joka teki häitä pojallensa,","Taivaan valtakunta on kuninkaan vertainen, joka teki häitä pojallensa,"],[22,3,"Ja lähetti palveliansa kutsumaan kutsutuita häihin, ja ei he tahtoneet tulla.","Ja lähetti palveliansa kutsumaan kutsutuita häihin, ja ei he tahtoneet tulla."],[22,4,"Taas hän lähetti toiset palveliat, sanoen: sanokaat kutsutuille: katso, minä valmistin atriani, härkäni ja syöttilääni ovat tapetut, ja kaikki ovat valmistetut: tulkaat häihin!","Taas hän lähetti toiset palveliat, sanoen: sanokaat kutsutuille: katso, minä valmistin atriani, härkäni ja syöttilääni ovat tapetut, ja kaikki ovat valmistetut: tulkaat häihin!"],[22,5,"Mutta he katsoivat ylön, ja menivät pois, yksi pellollensa, toinen kaupallensa.","Mutta he katsoivat ylön, ja menivät pois, yksi pellollensa, toinen kaupallensa."],[22,6,"Mutta muut ottivat kiinni hänen palveliansa, ja pilkkasivat heitä, ja tappoivat.","Mutta muut ottivat kiinni hänen palveliansa, ja pilkkasivat heitä, ja tappoivat."],[22,7,"Mutta kuin kuningas sen kuuli, vihastui hän, ja lähetti sotaväkensä, ja hukutti ne murhamiehet, ja heidän kaupunkinsa poltti.","Mutta kuin kuningas sen kuuli, vihastui hän, ja lähetti sotaväkensä, ja hukutti ne murhamiehet, ja heidän kaupunkinsa poltti."],[22,8,"Silloin hän sanoi palvelioillensa: häät tosin ovat valmistetut, mutta kutsutut ei olleet mahdolliset.","Silloin hän sanoi palvelioillensa: häät tosin ovat valmistetut, mutta kutsutut ei olleet mahdolliset."],[22,9,"Menkäät siis teiden haaroihin, ja kaikki, jotka te löydätte, kutsukaat häihin.","Menkäät siis teiden haaroihin, ja kaikki, jotka te löydätte, kutsukaat häihin."],[22,10,"Ja palveliat menivät ulos teille, ja kokosivat kaikki, jotka he löysivät, pahat ja hyvät; ja häähuone täytettiin vieraista.","Ja palveliat menivät ulos teille, ja kokosivat kaikki, jotka he löysivät, pahat ja hyvät; ja häähuone täytettiin vieraista."],[22,11,"Niin kuningas meni katsomaan vieraita, ja näki siellä yhden ihmisen, joka ei ollut vaatetettu häävaatteilla.","Niin kuningas meni katsomaan vieraita, ja näki siellä yhden ihmisen, joka ei ollut vaatetettu häävaatteilla."],[22,12,"Niin hän sanoi hänelle: ystäväni, kuinkas tänne tulit, ja ei sinulla ole häävaatteita? Mutta hän vaikeni.","Niin hän sanoi hänelle: ystäväni, kuinkas tänne tulit, ja ei sinulla ole häävaatteita? Mutta hän vaikeni."],[22,13,"Silloin sanoi kuningas palvelioille: sitokaat hänen kätensä ja jalkansa, ottakaat ja heittäkäät häntä ulkoiseen pimeyteen; siellä pitää oleman itku ja hammasten kiristys.","Silloin sanoi kuningas palvelioille: sitokaat hänen kätensä ja jalkansa, ottakaat ja heittäkäät häntä ulkoiseen pimeyteen; siellä pitää oleman itku ja hammasten kiristys."],[22,14,"Sillä monta on kutsuttu, mutta harvat ovat valitut.","Sillä monta on kutsuttu, mutta harvat ovat valitut."],[22,15,"Silloin Pharisealaiset menivät pitämään neuvoa, kuinka he hänen sanoissa solmeaisivat.","Silloin Pharisealaiset menivät pitämään neuvoa, kuinka he hänen sanoissa solmeaisivat."],[22,16,"Ja he lähettivät hänen tykönsä opetuslapsensa Herodilaisten kanssa, sanoen: Mestari, me tiedämme sinun totiseksi, ja sinä opetat Jumalan tien totuudessa, et myös tottele ketään; sillä et sinä katso ihmisten muotoa.","Ja he lähettivät hänen tykönsä opetuslapsensa Herodilaisten kanssa, sanoen: Mestari, me tiedämme sinun totiseksi, ja sinä opetat Jumalan tien totuudessa, et myös tottele ketään; sillä et sinä katso ihmisten muotoa."],[22,17,"Sano siis meille, kuinkas luulet: sopiiko keisarille antaa veroa taikka ei?","Sano siis meille, kuinkas luulet: sopiiko keisarille antaa veroa taikka ei?"],[22,18,"Mutta kuin Jeesus ymmärsi heidän pahuutensa, sanoi hän: mitä te ulkokullatut kiusaatte minua?","Mutta kuin Jeesus ymmärsi heidän pahuutensa, sanoi hän: mitä te ulkokullatut kiusaatte minua?"],[22,19,"Osoittakaat minulle veroraha. Niin he antoivat hänelle verorahan.","Osoittakaat minulle veroraha. Niin he antoivat hänelle verorahan."],[22,20,"Ja hän sanoi heille: kenenkä on tämä kuva ja päällekirjoitus?","Ja hän sanoi heille: kenenkä on tämä kuva ja päällekirjoitus?"],[22,21,"He sanoivat hänelle: keisarin. Niin hän sanoi heille: antakaat keisarille, mitkä keisarin ovat, ja Jumalalle, mitkä Jumalan ovat.","He sanoivat hänelle: keisarin. Niin hän sanoi heille: antakaat keisarille, mitkä keisarin ovat, ja Jumalalle, mitkä Jumalan ovat."],[22,22,"Ja kuin he nämät kuulivat, ihmettelivät he, ja luopuivat hänestä, ja menivät pois.","Ja kuin he nämät kuulivat, ihmettelivät he, ja luopuivat hänestä, ja menivät pois."],[22,23,"Sinä päivänä tulivat Saddukealaiset hänen tykönsä, jotka sanovat, ettei ylösnousemusta ole, ja kysyivät häneltä,","Sinä päivänä tulivat Saddukealaiset hänen tykönsä, jotka sanovat, ettei ylösnousemusta ole, ja kysyivät häneltä,"],[22,24,"Sanoen: Mestari! Moses sanoi: jos joku kuolee lapsetoinna, niin hänen veljensä pitää naiman hänen emäntänsä ja herättämän veljellensä siemenen.","Sanoen: Mestari! Moses sanoi: jos joku kuolee lapsetoinna, niin hänen veljensä pitää naiman hänen emäntänsä ja herättämän veljellensä siemenen."],[22,25,"Niin oli meidän seassamme seitsemän veljestä, ja kuin ensimäinen nai, niin se kuoli. Ja ettei hänellä ollut siementä, jätti hän emäntänsä veljellensä.","Niin oli meidän seassamme seitsemän veljestä, ja kuin ensimäinen nai, niin se kuoli. Ja ettei hänellä ollut siementä, jätti hän emäntänsä veljellensä."],[22,26,"Niin myös toinen ja kolmas, hamaan seitsemänteen asti.","Niin myös toinen ja kolmas, hamaan seitsemänteen asti."],[22,27,"Mutta kaikkein viimein kuoli myös se vaimo.","Mutta kaikkein viimein kuoli myös se vaimo."],[22,28,"Kenenkä emännän siis näistä seitsemästä pitää hänen ylösnousemisessa oleman? Sillä kaikki ovat häntä pitäneet.","Kenenkä emännän siis näistä seitsemästä pitää hänen ylösnousemisessa oleman? Sillä kaikki ovat häntä pitäneet."],[22,29,"Niin Jesus vastaten sanoi heille: te eksytte ja ette tiedä Raamatuita, eikä Jumalan voimaa.","Niin Jesus vastaten sanoi heille: te eksytte ja ette tiedä Raamatuita, eikä Jumalan voimaa."],[22,30,"Sillä ylösnousemisessa ei naida eikä huolla, mutta he ovat niinkuin Jumalan enkelit taivaassa.","Sillä ylösnousemisessa ei naida eikä huolla, mutta he ovat niinkuin Jumalan enkelit taivaassa."],[22,31,"Mutta ettekö te ole lukeneet kuolleitten ylösnousemisesta, mitä teille on Jumalalta sanottu, joka sanoo:","Mutta ettekö te ole lukeneet kuolleitten ylösnousemisesta, mitä teille on Jumalalta sanottu, joka sanoo:"],[22,32,"Minä olen Abrahamin Jumala, ja Isaakin Jumala, ja Jakobin Jumala? Ei ole Jumala kuolleiden Jumala, mutta elävien.","Minä olen Abrahamin Jumala, ja Isaakin Jumala, ja Jakobin Jumala? Ei ole Jumala kuolleiden Jumala, mutta elävien."],[22,33,"Ja kuin kansa sen kuuli, hämmästyivät he hänen oppiansa.","Ja kuin kansa sen kuuli, hämmästyivät he hänen oppiansa."],[22,34,"Mutta kuin Pharisealaiset sen kuulivat, että hän oli Saddukealaisten suun tukinnut, kokoontuivat he yhteen.","Mutta kuin Pharisealaiset sen kuulivat, että hän oli Saddukealaisten suun tukinnut, kokoontuivat he yhteen."],[22,35,"Ja yksi lain-opettaja heistä kysyi häneltä, kiusaten häntä, ja sanoi:","Ja yksi lain-opettaja heistä kysyi häneltä, kiusaten häntä, ja sanoi:"],[22,36,"Mestari, mikä on suurin käsky laissa?","Mestari, mikä on suurin käsky laissa?"],[22,37,"Niin Jesus sanoi hänelle: sinun pitää rakastaman Herraa sinun Jumalaas, kaikesta sydämestäs, ja kaikesta sielustas, ja kaikesta mielestäs:","Niin Jesus sanoi hänelle: sinun pitää rakastaman Herraa sinun Jumalaas, kaikesta sydämestäs, ja kaikesta sielustas, ja kaikesta mielestäs:"],[22,38,"Tämä on ensimäinen ja suurin käsky.","Tämä on ensimäinen ja suurin käsky."],[22,39,"Toinen on tämän kaltainen: sinun pitää rakastaman lähimmäistäs niinkuin itse sinuas.","Toinen on tämän kaltainen: sinun pitää rakastaman lähimmäistäs niinkuin itse sinuas."],[22,40,"Näissä kahdessa käskyssä kaikki laki ja prophetat riippuvat.","Näissä kahdessa käskyssä kaikki laki ja prophetat riippuvat."],[22,41,"Koska Pharisealaiset koossa olivat, kysyi heiltä Jesus,","Koska Pharisealaiset koossa olivat, kysyi heiltä Jesus,"],[22,42,"Sanoen: mitä teille näkyy Kristuksesta, kenenkä poika hän on? he sanoivat hänelle: Davidin.","Sanoen: mitä teille näkyy Kristuksesta, kenenkä poika hän on? he sanoivat hänelle: Davidin."],[22,43,"Hän sanoi heille: kuinka siis David kutsuu hengessä hänen Herraksi? sanoen:","Hän sanoi heille: kuinka siis David kutsuu hengessä hänen Herraksi? sanoen:"],[22,44,"Herra sanoi minun Herralleni: istu minun oikealla kädelläni, siihenasti kuin minä panen vihollises sinun jalkais astinlaudaksi.","Herra sanoi minun Herralleni: istu minun oikealla kädelläni, siihenasti kuin minä panen vihollises sinun jalkais astinlaudaksi."],[22,45,"Jos siis David kutsuu hänen Herraksi, kuinka hän on hänen poikansa?","Jos siis David kutsuu hänen Herraksi, kuinka hän on hänen poikansa?"],[22,46,"Ja ei kenkään taitanut häntä mitään vastata: ei myös yksikään rohjennut sen päivän perästä häneltä enempää kysyä.","Ja ei kenkään taitanut häntä mitään vastata: ei myös yksikään rohjennut sen päivän perästä häneltä enempää kysyä."],[23,1,"Silloin Jesus puhui kansalle ja hänen opetuslapsillensa,","Silloin Jesus puhui kansalle ja hänen opetuslapsillensa,"],[23,2,"Sanoen: Moseksen istuimella istuvat kirjanoppineet ja Pharisealaiset:","Sanoen: Moseksen istuimella istuvat kirjanoppineet ja Pharisealaiset:"],[23,3,"Kaikki siis, mitä he teidän käskevät pitää, se pitäkäät ja tehkäät; mutta heidän töittensä jälkeen älkäät te tehkö, sillä he sanovat, ja ei tee.","Kaikki siis, mitä he teidän käskevät pitää, se pitäkäät ja tehkäät; mutta heidän töittensä jälkeen älkäät te tehkö, sillä he sanovat, ja ei tee."],[23,4,"Sillä he sitovat raskaat kuormat, joita ei voida kantaa, ja panevat ne ihmisten olille, mutta ei he sormellansakaan itse tahdo niitä liikuttaa.","Sillä he sitovat raskaat kuormat, joita ei voida kantaa, ja panevat ne ihmisten olille, mutta ei he sormellansakaan itse tahdo niitä liikuttaa."],[23,5,"Mutta kaikki työnsä tekevät he, että ne ihmisiltä nähtäisiin. He levittelevät muistokirjansa, ja tekevät suureksi vaatteensa liepeet,","Mutta kaikki työnsä tekevät he, että ne ihmisiltä nähtäisiin. He levittelevät muistokirjansa, ja tekevät suureksi vaatteensa liepeet,"],[23,6,"Ja rakastavat ylimmäisiä sijoja pidoissa ja ylimmäisiä istuimia synagogissa,","Ja rakastavat ylimmäisiä sijoja pidoissa ja ylimmäisiä istuimia synagogissa,"],[23,7,"Ja tervehdyksiä turulla, ja tahtovat kutsuttaa ihmisiltä: rabbi, rabbi.","Ja tervehdyksiä turulla, ja tahtovat kutsuttaa ihmisiltä: rabbi, rabbi."],[23,8,"Mutta älkäät te antako teitä kutsuttaa rabbiksi; sillä yksi on teidän Mestarinne, joka on Kristus, mutta te olette kaikki veljekset.","Mutta älkäät te antako teitä kutsuttaa rabbiksi; sillä yksi on teidän Mestarinne, joka on Kristus, mutta te olette kaikki veljekset."],[23,9,"Ja älkäät ketäkään kutsuko isäksenne maan päällä; sillä yksi on Isänne, joka on taivaissa.","Ja älkäät ketäkään kutsuko isäksenne maan päällä; sillä yksi on Isänne, joka on taivaissa."],[23,10,"Ja älkäät antako teitä kutsuttaa mestariksi; sillä yksi on teidän Mestarinne, joka on Kristus.","Ja älkäät antako teitä kutsuttaa mestariksi; sillä yksi on teidän Mestarinne, joka on Kristus."],[23,11,"Joka teistä suurin on, se olkoon teidän palvelianne.","Joka teistä suurin on, se olkoon teidän palvelianne."],[23,12,"Mutta joka itsensä ylentää, se alennetaan, ja joka itsensä alentaa, se ylennetään.","Mutta joka itsensä ylentää, se alennetaan, ja joka itsensä alentaa, se ylennetään."],[23,13,"Mutta voi teitä, kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka suljette taivaan valtakunnan ihmisten edestä; sillä ette itse sinne mene, ettekä salli meneväisiä sinne mennä.","Mutta voi teitä, kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka suljette taivaan valtakunnan ihmisten edestä; sillä ette itse sinne mene, ettekä salli meneväisiä sinne mennä."],[23,14,"Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka syötte leskein huoneet, ja muodoksi pidätte pitkät rukoukset: sentähden te saatte sitä kovemman kadotuksen.","Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka syötte leskein huoneet, ja muodoksi pidätte pitkät rukoukset: sentähden te saatte sitä kovemman kadotuksen."],[23,15,"Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka merta ja mannerta ympäri vaellatte, tehdäksenne yhtä uutta Juudalaista; ja kuin se tehty on, niin te hänestä teette kaksikertaa enemmän helvetin lapsen kuin te itse olette.","Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka merta ja mannerta ympäri vaellatte, tehdäksenne yhtä uutta Juudalaista; ja kuin se tehty on, niin te hänestä teette kaksikertaa enemmän helvetin lapsen kuin te itse olette."],[23,16,"Voi teitä, te sokiat taluttajat! jotka sanotte: joka vannoo templin kautta, ei se mitään ole, mutta joka vannoo templin kullan kautta, se on velvollinen.","Voi teitä, te sokiat taluttajat! jotka sanotte: joka vannoo templin kautta, ei se mitään ole, mutta joka vannoo templin kullan kautta, se on velvollinen."],[23,17,"Te hullut ja sokiat! sillä kumpi on suurempi: kulta, eli templi, joka kullan pyhittää?","Te hullut ja sokiat! sillä kumpi on suurempi: kulta, eli templi, joka kullan pyhittää?"],[23,18,"Ja joka vannoo alttarin kautta, ei se mitään ole; mutta joka vannoo lahjan kautta, joka sen päällä on, se on velvollinen.","Ja joka vannoo alttarin kautta, ei se mitään ole; mutta joka vannoo lahjan kautta, joka sen päällä on, se on velvollinen."],[23,19,"Te hullut ja sokiat! sillä kumpi on suurempi: lahja, eli alttari, joka lahjan pyhittää?","Te hullut ja sokiat! sillä kumpi on suurempi: lahja, eli alttari, joka lahjan pyhittää?"],[23,20,"Joka siis vannoo alttarin kautta, hän vannoo sen kautta ja kaikkein, mikä sen päällä on.","Joka siis vannoo alttarin kautta, hän vannoo sen kautta ja kaikkein, mikä sen päällä on."],[23,21,"Ja joka vannoo templin kautta, se vannoo hänen kauttansa ja sen kautta, joka siinä asuu.","Ja joka vannoo templin kautta, se vannoo hänen kauttansa ja sen kautta, joka siinä asuu."],[23,22,"Ja joka vannoo taivaan kautta, se vannoo Jumalan istuimen kautta ja hänen kauttansa, joka sen päällä istuu.","Ja joka vannoo taivaan kautta, se vannoo Jumalan istuimen kautta ja hänen kauttansa, joka sen päällä istuu."],[23,23,"Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka kymmenykset teette mintuista, tilleistä ja kuminoista, ja jätätte pois ne raskaammat laista, tuomion, laupiuden ja uskon: näitä piti tehtämän, ja toisia ei jätettämän.","Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka kymmenykset teette mintuista, tilleistä ja kuminoista, ja jätätte pois ne raskaammat laista, tuomion, laupiuden ja uskon: näitä piti tehtämän, ja toisia ei jätettämän."],[23,24,"Te sokiat taluttajat! te kuurnitsette hyttysen ja kamelin nielette.","Te sokiat taluttajat! te kuurnitsette hyttysen ja kamelin nielette."],[23,25,"Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka puhdistatte juoma-astian ja ruoka-astian ulkoiselta puolelta, mutta sisältä ovat ne täynnä raatelemista ja tyytymättömyyttä.","Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka puhdistatte juoma-astian ja ruoka-astian ulkoiselta puolelta, mutta sisältä ovat ne täynnä raatelemista ja tyytymättömyyttä."],[23,26,"Sinä sokia Pharisealainen! puhdista ensin juoma-astia ja ruoka-astia sisältä, että myös ulkonainenkin puoli puhtaaksi tulis.","Sinä sokia Pharisealainen! puhdista ensin juoma-astia ja ruoka-astia sisältä, että myös ulkonainenkin puoli puhtaaksi tulis."],[23,27,"Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut; sillä te olette valkiaksi sivuttuin hautain kaltaiset, jotka ulkoa kauniit ovat, mutta sisältä ovat he täynnä kuolleiden luita ja kaikkea riettautta.","Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut; sillä te olette valkiaksi sivuttuin hautain kaltaiset, jotka ulkoa kauniit ovat, mutta sisältä ovat he täynnä kuolleiden luita ja kaikkea riettautta."],[23,28,"Niin myös te olette ulkoa tosin nähdä ihmisten edessä hurskaat, mutta sisältä te olette täynnä ulkokullaisuutta ja vääryyttä.","Niin myös te olette ulkoa tosin nähdä ihmisten edessä hurskaat, mutta sisältä te olette täynnä ulkokullaisuutta ja vääryyttä."],[23,29,"Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka rakennatte prophetain hautoja ja kaunistatte vanhurskasten hautoja,","Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka rakennatte prophetain hautoja ja kaunistatte vanhurskasten hautoja,"],[23,30,"Ja sanotte: jos me olisimme olleet meidän isäimme aikoina, emme olisi olleet osalliset heidän kanssansa prophetain veressä.","Ja sanotte: jos me olisimme olleet meidän isäimme aikoina, emme olisi olleet osalliset heidän kanssansa prophetain veressä."],[23,31,"Niin te siis itseänne tunnustatte, että olette niiden lapset, jotka tappoivat prophetat.","Niin te siis itseänne tunnustatte, että olette niiden lapset, jotka tappoivat prophetat."],[23,32,"Niin tekin täyttäkäät teidän isäinne määrä.","Niin tekin täyttäkäät teidän isäinne määrä."],[23,33,"Te kärmeet, te kyykärmetten sikiät! kuinka te vältätte helvetin kadotuksen?","Te kärmeet, te kyykärmetten sikiät! kuinka te vältätte helvetin kadotuksen?"],[23,34,"Sentähden, katso, minä lähetän teille prophetat, ja viisaat, ja kirjanoppineet; ja niistä te muutamat tapatte ja ristiinnaulitsette, ja muutamat te pieksätte teidän synagogissanne, ja vainootte kaupungista kaupunkiin.","Sentähden, katso, minä lähetän teille prophetat, ja viisaat, ja kirjanoppineet; ja niistä te muutamat tapatte ja ristiinnaulitsette, ja muutamat te pieksätte teidän synagogissanne, ja vainootte kaupungista kaupunkiin."],[23,35,"Että teidän päällenne pitää tuleman kaikki vanhurskas veri, joka vuodatettu on maan päälle hamasta vanhurskaan Abelin verestä niin Sakariaan, Barakiaan pojan vereen asti, jonka te tapoitte templin ja alttarin vaiheella.","Että teidän päällenne pitää tuleman kaikki vanhurskas veri, joka vuodatettu on maan päälle hamasta vanhurskaan Abelin verestä niin Sakariaan, Barakiaan pojan vereen asti, jonka te tapoitte templin ja alttarin vaiheella."],[23,36,"Totisesti sanon minä teille: kaikki nämät pitää tuleman tämän suvun päälle.","Totisesti sanon minä teille: kaikki nämät pitää tuleman tämän suvun päälle."],[23,37,"Jerusalem, Jerusalem, sinä joka tapat prophetat ja kivillä surmaat ne, jotka sinun tykös lähetetyt ovat! kuinka usein minä tahdoin koota sinun lapses, niinkuin kana kokoo poikansa siipeinsä alle? ja ette tahtoneet.","Jerusalem, Jerusalem, sinä joka tapat prophetat ja kivillä surmaat ne, jotka sinun tykös lähetetyt ovat! kuinka usein minä tahdoin koota sinun lapses, niinkuin kana kokoo poikansa siipeinsä alle? ja ette tahtoneet."],[23,38,"Katso, teidän huoneenne pitää teille jäämän kylmille.","Katso, teidän huoneenne pitää teille jäämän kylmille."],[23,39,"Sillä minä sanon teille: ette suinkaan minua tästedes näe, siihenasti kuin te sanotte: kiitetty olkoon se, joka tulee Herran nimeen!","Sillä minä sanon teille: ette suinkaan minua tästedes näe, siihenasti kuin te sanotte: kiitetty olkoon se, joka tulee Herran nimeen!"],[24,1,"Ja Jesus meni ulos ja läksi pois templistä, ja hänen opetuslapsensa tulivat osoittamaan hänelle templin rakennuksia.","Ja Jesus meni ulos ja läksi pois templistä, ja hänen opetuslapsensa tulivat osoittamaan hänelle templin rakennuksia."],[24,2,"Niin sanoi Jesus heille: ettekö te kaikkia näitä näe? Totisesti sanon minä teille: ei pidä tässä jätettämän kiveä kiven päälle, joka ei maahan jaoteta.","Niin sanoi Jesus heille: ettekö te kaikkia näitä näe? Totisesti sanon minä teille: ei pidä tässä jätettämän kiveä kiven päälle, joka ei maahan jaoteta."],[24,3,"Mutta kuin hän istui Öljymäellä, menivät opetuslapset hänen tykönsä erinänsä ja sanoivat: sano meille: koska tämä tapahtuu, ja mikä sinun tulemises ja maailman lopun merkki ollee?","Mutta kuin hän istui Öljymäellä, menivät opetuslapset hänen tykönsä erinänsä ja sanoivat: sano meille: koska tämä tapahtuu, ja mikä sinun tulemises ja maailman lopun merkki ollee?"],[24,4,"Ja Jesus vastasi ja sanoi heille: katsokaat, ettei kenkään teitä viettele.","Ja Jesus vastasi ja sanoi heille: katsokaat, ettei kenkään teitä viettele."],[24,5,"Sillä monta tulevat minun nimeeni, sanoen: minä olen Kristus! ja viettelevät monta.","Sillä monta tulevat minun nimeeni, sanoen: minä olen Kristus! ja viettelevät monta."],[24,6,"Niin te saatte kuulla sotia ja sanomia sodista. Katsokaat, ettette peljästy; sillä kaikki nämät pitää tapahtuman, mutta ei vielä ole loppu.","Niin te saatte kuulla sotia ja sanomia sodista. Katsokaat, ettette peljästy; sillä kaikki nämät pitää tapahtuman, mutta ei vielä ole loppu."],[24,7,"Sillä kansan pitää kansaa vastaan nouseman ja valtakunnan valtakuntaa vastaan, ja tulee ruttotauti ja nälkä ja maanjäristys moneen paikkaan.","Sillä kansan pitää kansaa vastaan nouseman ja valtakunnan valtakuntaa vastaan, ja tulee ruttotauti ja nälkä ja maanjäristys moneen paikkaan."],[24,8,"Mutta kaikki nämät ovat murhetten alku.","Mutta kaikki nämät ovat murhetten alku."],[24,9,"Silloin he ylönantavat teitä vaivaan ja tappavat teidät, ja te tulette vihattavaksi kaikilta pakanoilta minun nimeni tähden.","Silloin he ylönantavat teitä vaivaan ja tappavat teidät, ja te tulette vihattavaksi kaikilta pakanoilta minun nimeni tähden."],[24,10,"Ja silloin monta pahenevat, ja keskenänsä pettävät toinen toisensa, ja vihaavat toinen toistansa keskenänsä.","Ja silloin monta pahenevat, ja keskenänsä pettävät toinen toisensa, ja vihaavat toinen toistansa keskenänsä."],[24,11,"Ja monta väärää prophetaa nousevat ja viettelevät monta.","Ja monta väärää prophetaa nousevat ja viettelevät monta."],[24,12,"Ja että vääryys saa vallan, niin rakkaus monessa kylmenee.","Ja että vääryys saa vallan, niin rakkaus monessa kylmenee."],[24,13,"Mutta joka vahvana pysyy loppuun asti, se tulee autuaaksi.","Mutta joka vahvana pysyy loppuun asti, se tulee autuaaksi."],[24,14,"Ja tämä valtakunnan evankeliumi pitää saarnattaman kaikessa maailmassa, kaikille pakanoille todistukseksi; ja silloin tulee loppu.","Ja tämä valtakunnan evankeliumi pitää saarnattaman kaikessa maailmassa, kaikille pakanoille todistukseksi; ja silloin tulee loppu."],[24,15,"Kuin te siis näette hävityksen kauhistuksen, josta sanottu on Daniel prophetan kautta, seisovan pyhässä siassa; (joka tämän lukee, hän ymmärtäköön!)","Kuin te siis näette hävityksen kauhistuksen, josta sanottu on Daniel prophetan kautta, seisovan pyhässä siassa; (joka tämän lukee, hän ymmärtäköön!)"],[24,16,"Silloin ne, jotka Juudeassa ovat, paetkoot vuorille.","Silloin ne, jotka Juudeassa ovat, paetkoot vuorille."],[24,17,"Ja joka katon päällä on, älköön astuko alas ottamaan jotakin huoneestansa.","Ja joka katon päällä on, älköön astuko alas ottamaan jotakin huoneestansa."],[24,18,"Ja joka pellolla on, älköön palatko vaatteitansa ottamaan.","Ja joka pellolla on, älköön palatko vaatteitansa ottamaan."],[24,19,"Voi raskaita ja imettäväisiä niinä päivinä!","Voi raskaita ja imettäväisiä niinä päivinä!"],[24,20,"Mutta rukoilkaat, ettei teidän pakonne tapahtuisi talvella eikä sabbatina;","Mutta rukoilkaat, ettei teidän pakonne tapahtuisi talvella eikä sabbatina;"],[24,21,"Sillä silloin pitää suuren vaivan oleman, jonka kaltaista ei ole ollut maailman alusta niin tähän asti, ei myös tule.","Sillä silloin pitää suuren vaivan oleman, jonka kaltaista ei ole ollut maailman alusta niin tähän asti, ei myös tule."],[24,22,"Ja ellei ne päivät olisi lyhennetyt, niin ei yksikään liha tulisi autuaaksi; mutta valittuin tähden pitää ne päivät lyhennettämän.","Ja ellei ne päivät olisi lyhennetyt, niin ei yksikään liha tulisi autuaaksi; mutta valittuin tähden pitää ne päivät lyhennettämän."],[24,23,"Silloin jos joku teille sanois: katso, tässä on Kristus taikka siellä! älkäät uskoko.","Silloin jos joku teille sanois: katso, tässä on Kristus taikka siellä! älkäät uskoko."],[24,24,"Sillä väärät Kristukset ja väärät prophetat nousevat, ja tekevät suuria ihmeitä ja merkkejä: niin että myös, jos taitais tapahtua, valitutkin eksytettäisiin.","Sillä väärät Kristukset ja väärät prophetat nousevat, ja tekevät suuria ihmeitä ja merkkejä: niin että myös, jos taitais tapahtua, valitutkin eksytettäisiin."],[24,25,"Katso, minä olen teille sen ennen sanonut.","Katso, minä olen teille sen ennen sanonut."],[24,26,"Jos he siis teille sanovat: katso, hän on korvessa! niin älkäät menkö ulos; katso, hän on kammiossa! älkäät uskoko.","Jos he siis teille sanovat: katso, hän on korvessa! niin älkäät menkö ulos; katso, hän on kammiossa! älkäät uskoko."],[24,27,"Sillä niinkuin pitkäisen tuli leimahtaa idästä ja näkyy hamaan länteen, niin on myös Ihmisen Pojan tulemus.","Sillä niinkuin pitkäisen tuli leimahtaa idästä ja näkyy hamaan länteen, niin on myös Ihmisen Pojan tulemus."],[24,28,"Sillä kussa raato on, siihen kotkat kokoontuvat.","Sillä kussa raato on, siihen kotkat kokoontuvat."],[24,29,"Mutta kohta sen ajan vaivan jälkeen aurinko pimenee, ja kuu ei anna valoansa, ja tähden putoavat taivaasta, ja taivaan voimat pitää liikutettaman.","Mutta kohta sen ajan vaivan jälkeen aurinko pimenee, ja kuu ei anna valoansa, ja tähden putoavat taivaasta, ja taivaan voimat pitää liikutettaman."],[24,30,"Ja silloin näkyy Ihmisen Pojan merkki taivaassa, ja silloin kaikki sukukunnat maassa parkuvat ja saavat nähdä Ihmisen Pojan tulevan taivaan pilvissä suurella voimalla ja kunnialla.","Ja silloin näkyy Ihmisen Pojan merkki taivaassa, ja silloin kaikki sukukunnat maassa parkuvat ja saavat nähdä Ihmisen Pojan tulevan taivaan pilvissä suurella voimalla ja kunnialla."],[24,31,"Ja hän lähettää enkelinsä suurella basunan äänellä, ja he kokoovat hänen valittunsa neljästä tuulesta, yhdestä taivasten äärestä niin toiseen.","Ja hän lähettää enkelinsä suurella basunan äänellä, ja he kokoovat hänen valittunsa neljästä tuulesta, yhdestä taivasten äärestä niin toiseen."],[24,32,"Mutta oppikaat fikunapuusta vertaus: kuin sen oksa on tuores ja lehdet puhkeavat, niin te tiedätte suven läsnä olevan:","Mutta oppikaat fikunapuusta vertaus: kuin sen oksa on tuores ja lehdet puhkeavat, niin te tiedätte suven läsnä olevan:"],[24,33,"Niin myös te, kuin te näette nämät kaikki, tietäkäät, että se on läsnä, oven edessä.","Niin myös te, kuin te näette nämät kaikki, tietäkäät, että se on läsnä, oven edessä."],[24,34,"Totisesti sanon minä teille: ei suinkaan tämän sukukunnan pidä hukkuman ennen kuin kaikki nämät tapahtuvat.","Totisesti sanon minä teille: ei suinkaan tämän sukukunnan pidä hukkuman ennen kuin kaikki nämät tapahtuvat."],[24,35,"Taivas ja maa pitää hukkuman, mutta minun sanani ei pidä suinkaan hukkaantuman.","Taivas ja maa pitää hukkuman, mutta minun sanani ei pidä suinkaan hukkaantuman."],[24,36,"Vaan siitä päivästä ja hetkestä ei tiedä kenkään, ei taivaan enkelitkään, vaan minun Isäni yksinänsä.","Vaan siitä päivästä ja hetkestä ei tiedä kenkään, ei taivaan enkelitkään, vaan minun Isäni yksinänsä."],[24,37,"Mutta niinkuin Noan ajat olivat, niin pitää myös Ihmisen Pojan tulemus oleman.","Mutta niinkuin Noan ajat olivat, niin pitää myös Ihmisen Pojan tulemus oleman."],[24,38,"Sillä niinkuin he niinä päivinä vedenpaisumisen edellä olivat, söivät ja joivat, naivat ja huolivat, hamaan siihen päivään asti, jona Noa arkkiin sisälle meni,","Sillä niinkuin he niinä päivinä vedenpaisumisen edellä olivat, söivät ja joivat, naivat ja huolivat, hamaan siihen päivään asti, jona Noa arkkiin sisälle meni,"],[24,39,"Ja ei tietäneet ennen kuin vedenpaisumus tuli, ja otti pois kaikki: niin pitää myös Ihmisen Pojan tulemus oleman.","Ja ei tietäneet ennen kuin vedenpaisumus tuli, ja otti pois kaikki: niin pitää myös Ihmisen Pojan tulemus oleman."],[24,40,"Silloin on kaksi kedolla: yksi otetaan ylös, ja toinen jätetään.","Silloin on kaksi kedolla: yksi otetaan ylös, ja toinen jätetään."],[24,41,"Kaksi jauhavat myllyssä: yksi otetaan ylös, ja toinen jätetään.","Kaksi jauhavat myllyssä: yksi otetaan ylös, ja toinen jätetään."],[24,42,"Valvokaat siis; sillä ette tiedä, millä hetkellä teidän Herranne on tuleva.","Valvokaat siis; sillä ette tiedä, millä hetkellä teidän Herranne on tuleva."],[24,43,"Mutta se tietäkäät: jos perheenisäntä tietäis, millä hetkellä varas on tuleva, kaiketi hän valvois, eikä sallisi kaivaa huonettansa.","Mutta se tietäkäät: jos perheenisäntä tietäis, millä hetkellä varas on tuleva, kaiketi hän valvois, eikä sallisi kaivaa huonettansa."],[24,44,"Sentähden olkaat te myös valmiit; sillä millä hetkellä ette luulekaan, tulee Ihmisen Poika.","Sentähden olkaat te myös valmiit; sillä millä hetkellä ette luulekaan, tulee Ihmisen Poika."],[24,45,"Kuka siis on uskollinen ja toimellinen palvelia, jonka Herra pani perheensä päälle, antamaan heille ruokaa ajallansa?","Kuka siis on uskollinen ja toimellinen palvelia, jonka Herra pani perheensä päälle, antamaan heille ruokaa ajallansa?"],[24,46,"Autuas on se palvelia, jonka Herra löytää niin tehneeksi, kuin hän tulee.","Autuas on se palvelia, jonka Herra löytää niin tehneeksi, kuin hän tulee."],[24,47,"Totisesti sanon minä teille: hän panee hänen kaiken hyvyytensä päälle.","Totisesti sanon minä teille: hän panee hänen kaiken hyvyytensä päälle."],[24,48,"Mutta jos paha palvelia sanoo sydämessänsä: minun Herrani viipyy tulemasta;","Mutta jos paha palvelia sanoo sydämessänsä: minun Herrani viipyy tulemasta;"],[24,49,"Ja rupee pieksämään leipäveljiänsä, niin myös syömään ja juomaan juomarien kanssa:","Ja rupee pieksämään leipäveljiänsä, niin myös syömään ja juomaan juomarien kanssa:"],[24,50,"Niin sen palvelian Herra tulee sinä päivänä, jona ei hän luulekaan, ja sillä hetkellä, jolla ei hän tiedä.","Niin sen palvelian Herra tulee sinä päivänä, jona ei hän luulekaan, ja sillä hetkellä, jolla ei hän tiedä."],[24,51,"Ja hän eroittaa hänen, ja antaa hänelle osan ulkokullattuin kanssa: siellä pitää oleman itku ja hammasten kiristys.","Ja hän eroittaa hänen, ja antaa hänelle osan ulkokullattuin kanssa: siellä pitää oleman itku ja hammasten kiristys."],[25,1,"Silloin pitää taivaan valtakunta oleman kymmenen neitseen kaltainen, jotka ottivat lamppunsa ja menivät ulos ylkää vastaan.","Silloin pitää taivaan valtakunta oleman kymmenen neitseen kaltainen, jotka ottivat lamppunsa ja menivät ulos ylkää vastaan."],[25,2,"Mutta viisi heistä oli taitavaa, ja viisi tyhmää.","Mutta viisi heistä oli taitavaa, ja viisi tyhmää."],[25,3,"Tyhmät ottivat lamppunsa, ja ei ottaneet öljyä myötänsä;","Tyhmät ottivat lamppunsa, ja ei ottaneet öljyä myötänsä;"],[25,4,"Mutta taitavat ottiva öljyä astioihinsa, ynnä lamppunsa kanssa.","Mutta taitavat ottiva öljyä astioihinsa, ynnä lamppunsa kanssa."],[25,5,"Kuin ylkä viipyi, tulivat he kaikki uneliaiksi ja makasivat.","Kuin ylkä viipyi, tulivat he kaikki uneliaiksi ja makasivat."],[25,6,"Mutta puoli-yönä tuli huuto: katso, ylkä tulee, menkäät ulos häntä vastaan.","Mutta puoli-yönä tuli huuto: katso, ylkä tulee, menkäät ulos häntä vastaan."],[25,7,"Niin nousivat kaikki nämät neitseet ja valmistivat lamppunsa.","Niin nousivat kaikki nämät neitseet ja valmistivat lamppunsa."],[25,8,"Mutta tyhmät sanoivat taitaville: antakaat meille öljystänne; sillä meidän lamppumme sammuvat.","Mutta tyhmät sanoivat taitaville: antakaat meille öljystänne; sillä meidän lamppumme sammuvat."],[25,9,"Niin vastasivat taitavat, sanoen: ei suinkaan, ettei meiltä ja teiltä puuttuisi; mutta menkäät paremmin niiden tykö, jotka myyvät, ja ostakaat itsellenne.","Niin vastasivat taitavat, sanoen: ei suinkaan, ettei meiltä ja teiltä puuttuisi; mutta menkäät paremmin niiden tykö, jotka myyvät, ja ostakaat itsellenne."],[25,10,"Mutta kuin he menivät ostamaan, tuli ylkä. Ja jotka valmiit olivat, ne menivät hänen kanssansa häihin, ja ovi suljettiin.","Mutta kuin he menivät ostamaan, tuli ylkä. Ja jotka valmiit olivat, ne menivät hänen kanssansa häihin, ja ovi suljettiin."],[25,11,"Viimein tulivat nekin toiset neitseet, ja sanoivat: Herra, Herra, avaa meidän eteemme.","Viimein tulivat nekin toiset neitseet, ja sanoivat: Herra, Herra, avaa meidän eteemme."],[25,12,"Mutta hän vastasi ja sanoi: totisesti sanon minä teille: en tunne minä teitä.","Mutta hän vastasi ja sanoi: totisesti sanon minä teille: en tunne minä teitä."],[25,13,"Valvokaat sentähden, sillä ette tiedä päivää eikä hetkeä, jona Ihmisen Poika tulee.","Valvokaat sentähden, sillä ette tiedä päivää eikä hetkeä, jona Ihmisen Poika tulee."],[25,14,"Sillä niinkuin ihminen matkusti kauvas ja kutsui palveliansa, ja antoi heille tavaransa:","Sillä niinkuin ihminen matkusti kauvas ja kutsui palveliansa, ja antoi heille tavaransa:"],[25,15,"Ja antoi yhdelle viisi leiviskää, toiselle kaksi ja kolmannelle yhden, jokaiselle varansa jälkeen: ja meni kohta matkaansa;","Ja antoi yhdelle viisi leiviskää, toiselle kaksi ja kolmannelle yhden, jokaiselle varansa jälkeen: ja meni kohta matkaansa;"],[25,16,"Niin meni se, joka viisi leiviskää oli ottanut, teki niillä kauppaa ja voitti toiset viisi leiviskää.","Niin meni se, joka viisi leiviskää oli ottanut, teki niillä kauppaa ja voitti toiset viisi leiviskää."],[25,17,"Niin myös se, joka kaksi oli ottanut, voitti myös toiset kaksi.","Niin myös se, joka kaksi oli ottanut, voitti myös toiset kaksi."],[25,18,"Mutta joka yhden oli ottanut, hän meni pois ja kaivoi maahan, ja kätki herransa rahan.","Mutta joka yhden oli ottanut, hän meni pois ja kaivoi maahan, ja kätki herransa rahan."],[25,19,"Niin pitkän ajan perästä tuli palveliain herra ja laski lukua heidän kanssansa.","Niin pitkän ajan perästä tuli palveliain herra ja laski lukua heidän kanssansa."],[25,20,"Ja tuli se, joka oli ottanut viisi leiviskää, ja toi toiset viisi leiviskää, sanoen: herra, viisi leiviskää sinä annoit minulle, katso, minä olen toiset viisi leiviskää niillä voittanut.","Ja tuli se, joka oli ottanut viisi leiviskää, ja toi toiset viisi leiviskää, sanoen: herra, viisi leiviskää sinä annoit minulle, katso, minä olen toiset viisi leiviskää niillä voittanut."],[25,21,"Sanoi hänen herransa hänelle: hyvin, sinä hyvä ja uskollinen palvelia! vähän päällä sinä olit uskollinen, minä panen sinun paljon päälle: mene sinun herras iloon.","Sanoi hänen herransa hänelle: hyvin, sinä hyvä ja uskollinen palvelia! vähän päällä sinä olit uskollinen, minä panen sinun paljon päälle: mene sinun herras iloon."],[25,22,"Niin tuli se, joka oli kaksi leiviskää ottanut, ja sanoi: herra, kaksi leiviskää sinä annoit minulle, katso, toiset kaksi olen minä niillä voittanut.","Niin tuli se, joka oli kaksi leiviskää ottanut, ja sanoi: herra, kaksi leiviskää sinä annoit minulle, katso, toiset kaksi olen minä niillä voittanut."],[25,23,"Sanoi hänen herransa hänelle: hyvin, sinä hyvä ja uskollinen palvelia! vähän päällä sinä olit uskollinen, minä panen sinun paljon päälle: mene sinun herras iloon.","Sanoi hänen herransa hänelle: hyvin, sinä hyvä ja uskollinen palvelia! vähän päällä sinä olit uskollinen, minä panen sinun paljon päälle: mene sinun herras iloon."],[25,24,"Niin myös se tuli, joka yhden leiviskän oli ottanut, ja sanoi: herra, minä tiesin sinun kovaksi mieheksi: sinä niität siitä, kuhunkas et kylvänyt, ja siitä sinä kokoot, kuhunka sinä et hajoittanut.","Niin myös se tuli, joka yhden leiviskän oli ottanut, ja sanoi: herra, minä tiesin sinun kovaksi mieheksi: sinä niität siitä, kuhunkas et kylvänyt, ja siitä sinä kokoot, kuhunka sinä et hajoittanut."],[25,25,"Ja minä peljäten menin pois ja kätkin sinun leiviskäs maahan: katso, tässä on sinun omas.","Ja minä peljäten menin pois ja kätkin sinun leiviskäs maahan: katso, tässä on sinun omas."],[25,26,"Mutta hänen herransa vastasi ja sanoi hänelle: sinä paha ja laiska palvelia! jos tiesit minun siitä niittävän, kuhunka en minä kylvänyt, ja sieltä kokoovan, johonka en minä ole hajoittanut,","Mutta hänen herransa vastasi ja sanoi hänelle: sinä paha ja laiska palvelia! jos tiesit minun siitä niittävän, kuhunka en minä kylvänyt, ja sieltä kokoovan, johonka en minä ole hajoittanut,"],[25,27,"Niin sinun siis olis tullut antaa minun rahani vaihettajille, ja minä tultuani olisin omani jälleen saanut kasvun kanssa.","Niin sinun siis olis tullut antaa minun rahani vaihettajille, ja minä tultuani olisin omani jälleen saanut kasvun kanssa."],[25,28,"Ottakaat siis häneltä leiviskä, ja antakaat sille, jolla on kymmenen leiviskää.","Ottakaat siis häneltä leiviskä, ja antakaat sille, jolla on kymmenen leiviskää."],[25,29,"(Sillä jokaiselle, jolla on, pitää annettaman, ja hänellä pitää kyllä oleman; mutta jolla ei ole, sekin kuin hänellä on, pitää häneltä otettaman pois).","(Sillä jokaiselle, jolla on, pitää annettaman, ja hänellä pitää kyllä oleman; mutta jolla ei ole, sekin kuin hänellä on, pitää häneltä otettaman pois)."],[25,30,"Ja heittäkäät se kelvotoin palvelia ulkonaiseen pimeyteen: siellä pitää oleman itku ja hammasten kiristys.","Ja heittäkäät se kelvotoin palvelia ulkonaiseen pimeyteen: siellä pitää oleman itku ja hammasten kiristys."],[25,31,"Mutta kuin Ihmisen Poika tulee kunniassansa ja kaikki pyhät enkelit hänen kanssansa, silloin hän istuu kunniansa istuimella,","Mutta kuin Ihmisen Poika tulee kunniassansa ja kaikki pyhät enkelit hänen kanssansa, silloin hän istuu kunniansa istuimella,"],[25,32,"Ja hänen eteensä kootaan kaikki kansat. Ja hän eroittaa toiset toisistansa, niinkuin paimen eroittaa lampaat vuohista,","Ja hänen eteensä kootaan kaikki kansat. Ja hän eroittaa toiset toisistansa, niinkuin paimen eroittaa lampaat vuohista,"],[25,33,"ja asettaa lampaat tosin oikialle puolellensa, mutta vuohet vasemmallensa.","ja asettaa lampaat tosin oikialle puolellensa, mutta vuohet vasemmallensa."],[25,34,"Silloin sanoo kuningas niille, jotka hänen oikialla puolellansa ovat: tulkaat, minun Isäni siunatut, omistakaat se valtakunta, joka teille on valmistettu maailman alusta.","Silloin sanoo kuningas niille, jotka hänen oikialla puolellansa ovat: tulkaat, minun Isäni siunatut, omistakaat se valtakunta, joka teille on valmistettu maailman alusta."],[25,35,"Sillä minä isosin, ja te ruokitte minun: minä janosin, ja te juotitte minun: minä olin outo, ja te minun huoneeseen otitte:","Sillä minä isosin, ja te ruokitte minun: minä janosin, ja te juotitte minun: minä olin outo, ja te minun huoneeseen otitte:"],[25,36,"Alasti, ja te vaatetitte minun: sairaana, ja te opitte minua: minä olin vankina, ja te tulitte minun tyköni.","Alasti, ja te vaatetitte minun: sairaana, ja te opitte minua: minä olin vankina, ja te tulitte minun tyköni."],[25,37,"Silloin vanhurskaat häntä vastaavat ja sanovat: Herra, koska me näimme sinun isoovan, ja ruokimme sinun? taikka janoovan, ja annoimme sinun juoda?","Silloin vanhurskaat häntä vastaavat ja sanovat: Herra, koska me näimme sinun isoovan, ja ruokimme sinun? taikka janoovan, ja annoimme sinun juoda?"],[25,38,"Mutta koska me näimme sinun outona, ja huoneeseen otimme sinun? taikka alastoinna, ja vaatetimme sinua?","Mutta koska me näimme sinun outona, ja huoneeseen otimme sinun? taikka alastoinna, ja vaatetimme sinua?"],[25,39,"Eli koska me näimme sinun sairaana, taikka vankina, ja tulimme sinun tykös?","Eli koska me näimme sinun sairaana, taikka vankina, ja tulimme sinun tykös?"],[25,40,"Niin vastaa kuningas ja sanoo heille: totisesti sanon minä teille: sen minkä te olette tehneet yhdelle näistä vähimmistä minun veljistäni, sen te teitte minulle.","Niin vastaa kuningas ja sanoo heille: totisesti sanon minä teille: sen minkä te olette tehneet yhdelle näistä vähimmistä minun veljistäni, sen te teitte minulle."],[25,41,"Silloin hän myös sanoo niille, jotka vasemmalla ovat: menkäät pois minun tyköäni, te kirotut, ijankaikkiseen tuleen, joka valmistettu on perkeleelle ja hänen enkeleillensä.","Silloin hän myös sanoo niille, jotka vasemmalla ovat: menkäät pois minun tyköäni, te kirotut, ijankaikkiseen tuleen, joka valmistettu on perkeleelle ja hänen enkeleillensä."],[25,42,"Sillä minä isosin, ja ette minua ruokkineet: minä janosin, ja ette minua juottaneet:","Sillä minä isosin, ja ette minua ruokkineet: minä janosin, ja ette minua juottaneet:"],[25,43,"Minä olin outo, ja ette minua huoneeseen ottaneet: alastoin, ja ette minua vaatettaneet: sairas ja vankina, ja ette minua oppineet.","Minä olin outo, ja ette minua huoneeseen ottaneet: alastoin, ja ette minua vaatettaneet: sairas ja vankina, ja ette minua oppineet."],[25,44,"Silloin nekin häntä vastaavat, sanoen: Herra, koska me näimme sinun isoovan, taikka janoovan, taikka outona, eli alastoinna, eli sairaana, taikka vankina, ja emme sinua palvelleet?","Silloin nekin häntä vastaavat, sanoen: Herra, koska me näimme sinun isoovan, taikka janoovan, taikka outona, eli alastoinna, eli sairaana, taikka vankina, ja emme sinua palvelleet?"],[25,45,"Silloin hän vastaa heitä, sanoen: totisesti sanon minä teille, mitä ette tehneet yhdelle näistä vähimmistä, sitä ette tehneet minulle.","Silloin hän vastaa heitä, sanoen: totisesti sanon minä teille, mitä ette tehneet yhdelle näistä vähimmistä, sitä ette tehneet minulle."],[25,46,"Ja niiden pitää menemän ijankaikkiseen vaivaan, mutta vanhurskaat ijankaikkiseen elämään.","Ja niiden pitää menemän ijankaikkiseen vaivaan, mutta vanhurskaat ijankaikkiseen elämään."],[26,1,"Ja tapahtui, kuin Jesus oli lopettanut kaikki nämät puheet, sanoi hän opetuslapsillensa:","Ja tapahtui, kuin Jesus oli lopettanut kaikki nämät puheet, sanoi hän opetuslapsillensa:"],[26,2,"Te tiedätte, että kahden päivän perästä tulee pääsiäinen, ja Ihmisen Poika ylönannetaan ristiinnaulittaa.","Te tiedätte, että kahden päivän perästä tulee pääsiäinen, ja Ihmisen Poika ylönannetaan ristiinnaulittaa."],[26,3,"Silloin kokoontuivat pappein päämiehet ja kirjanoppineet ja kansan vanhimmat ylimmäisen papin saliin, joka kutsuttiin Kaiphas.","Silloin kokoontuivat pappein päämiehet ja kirjanoppineet ja kansan vanhimmat ylimmäisen papin saliin, joka kutsuttiin Kaiphas."],[26,4,"Ja neuvoa pitivät, kuinka he Jesuksen kavalluksella kiinniottaisivat ja tappaisivat.","Ja neuvoa pitivät, kuinka he Jesuksen kavalluksella kiinniottaisivat ja tappaisivat."],[26,5,"Mutta he sanoivat, ei juhlapäivänä, ettei kansassa tule meteli.","Mutta he sanoivat, ei juhlapäivänä, ettei kansassa tule meteli."],[26,6,"Kuin Jesus oli Betaniassa, spitaalisen Simonin huoneessa,","Kuin Jesus oli Betaniassa, spitaalisen Simonin huoneessa,"],[26,7,"Tuli vaimo hänen tykönsä, jolla oli lasi kallista voidetta, ja kaasi sen hänen päänsä päälle atrioitessansa.","Tuli vaimo hänen tykönsä, jolla oli lasi kallista voidetta, ja kaasi sen hänen päänsä päälle atrioitessansa."],[26,8,"Mutta kuin hänen opetuslapsensa sen näkivät, närkästyivät he ja sanoivat: mihinkä kelpaa tämä haaskaus?","Mutta kuin hänen opetuslapsensa sen näkivät, närkästyivät he ja sanoivat: mihinkä kelpaa tämä haaskaus?"],[26,9,"Sillä tämä voide olis kalliisti taittu myytää ja annettaa vaivaisille.","Sillä tämä voide olis kalliisti taittu myytää ja annettaa vaivaisille."],[26,10,"Mutta kuin Jesus sen ymmärsi, sanoi hän heille: mitä te vaivaatte tätä vaimoa? Sillä hän teki hyvän työn minun kohtaani.","Mutta kuin Jesus sen ymmärsi, sanoi hän heille: mitä te vaivaatte tätä vaimoa? Sillä hän teki hyvän työn minun kohtaani."],[26,11,"Sillä teidän tykönänne ovat aina vaivaiset; mutta en minä teillä aina ole.","Sillä teidän tykönänne ovat aina vaivaiset; mutta en minä teillä aina ole."],[26,12,"Sillä että hän kaasi sen voiteen minun ruumiini päälle, sen on hän tehnyt minun hautaamisekseni.","Sillä että hän kaasi sen voiteen minun ruumiini päälle, sen on hän tehnyt minun hautaamisekseni."],[26,13,"Totisesti sanon minä teille: kussa ikänä tämä evankeliumi saarnataan kaikessa maailmassa, niin tämä myös, minkä hän teki, pitää mainittaman hänen muistoksensa.","Totisesti sanon minä teille: kussa ikänä tämä evankeliumi saarnataan kaikessa maailmassa, niin tämä myös, minkä hän teki, pitää mainittaman hänen muistoksensa."],[26,14,"Silloin yksi kahdestatoistakymmenestä, joka kutsuttiin Juudas Iskariot, läksi pois pappein päämiesten tykö,","Silloin yksi kahdestatoistakymmenestä, joka kutsuttiin Juudas Iskariot, läksi pois pappein päämiesten tykö,"],[26,15,"Ja sanoi: mitä te tahdotte minulle antaa, ja minä teille hänen saatan? Ja he määräsivät hänelle kolmekymmentä hopiapenninkiä.","Ja sanoi: mitä te tahdotte minulle antaa, ja minä teille hänen saatan? Ja he määräsivät hänelle kolmekymmentä hopiapenninkiä."],[26,16,"Ja siitä ajasta etsi hän soveliasta aikaa pettääksensä häntä.","Ja siitä ajasta etsi hän soveliasta aikaa pettääksensä häntä."],[26,17,"Mutta ensimäisen makian leivän päivänä tulivat opetuslapset Jesuksen tykö, sanoen hänelle: kussas tahdot, että meidän pitää sinulle valmistaman pääsiäislampaan syötää?","Mutta ensimäisen makian leivän päivänä tulivat opetuslapset Jesuksen tykö, sanoen hänelle: kussas tahdot, että meidän pitää sinulle valmistaman pääsiäislampaan syötää?"],[26,18,"Niin hän sanoi: menkäät kaupunkiin yhden tykö, ja sanokaat hänelle: Mestari sanoo: minun aikani on läsnä, sinun tykönäs tahdon minä pääsiäistä pitää minun opetuslasteni kanssa.","Niin hän sanoi: menkäät kaupunkiin yhden tykö, ja sanokaat hänelle: Mestari sanoo: minun aikani on läsnä, sinun tykönäs tahdon minä pääsiäistä pitää minun opetuslasteni kanssa."],[26,19,"Ja opetuslapset tekivät niinkuin Jesus oli heitä käskenyt, ja valmistivat pääsiäislampaan.","Ja opetuslapset tekivät niinkuin Jesus oli heitä käskenyt, ja valmistivat pääsiäislampaan."],[26,20,"Mutta kuin ehtoo tuli, istui hän pöydän tykönä kahdentoistakymmenen kanssa.","Mutta kuin ehtoo tuli, istui hän pöydän tykönä kahdentoistakymmenen kanssa."],[26,21,"Ja heidän syödessänsä sanoi hän: totisesti sanon minä teille: yksi teistä minun pettää.","Ja heidän syödessänsä sanoi hän: totisesti sanon minä teille: yksi teistä minun pettää."],[26,22,"Ja he tulivat sangen murheellisiksi, ja rupesi jokainen heistä sanomaan hänelle: Herra, lienenkö minä se?","Ja he tulivat sangen murheellisiksi, ja rupesi jokainen heistä sanomaan hänelle: Herra, lienenkö minä se?"],[26,23,"Mutta hän vastasi ja sanoi: joka minun kanssani pistää kätensä vatiin, se pettää minun.","Mutta hän vastasi ja sanoi: joka minun kanssani pistää kätensä vatiin, se pettää minun."],[26,24,"Ihmisen Poika tosin menee, niinkuin hänestä on kirjoitettu; mutta voi sitä ihmistä, jonka kautta Ihmisen Poika petetään! parempi olis sille ihmiselle ollut, jos ei hän olisi syntynyt.","Ihmisen Poika tosin menee, niinkuin hänestä on kirjoitettu; mutta voi sitä ihmistä, jonka kautta Ihmisen Poika petetään! parempi olis sille ihmiselle ollut, jos ei hän olisi syntynyt."],[26,25,"Niin vastasi Juudas, joka hänen petti, ja sanoi: Mestari, olenko minä se? hän sanoi hänelle: sinäpä sen sanoit.","Niin vastasi Juudas, joka hänen petti, ja sanoi: Mestari, olenko minä se? hän sanoi hänelle: sinäpä sen sanoit."],[26,26,"Mutta kuin he söivät, otti Jesus leivän, ja kiitti, mursi ja antoi opetuslapsille, ja sanoi: ottakaat, syökäät: tämä on minun ruumiini.","Mutta kuin he söivät, otti Jesus leivän, ja kiitti, mursi ja antoi opetuslapsille, ja sanoi: ottakaat, syökäät: tämä on minun ruumiini."],[26,27,"Ja hän otti kalkin, ja kiitti, antoi heille ja sanoi: juokaat tästä kaikki;","Ja hän otti kalkin, ja kiitti, antoi heille ja sanoi: juokaat tästä kaikki;"],[26,28,"Sillä tämä on minun vereni, sen uuden Testamentin, joka monen tähden vuodatetaan syntein anteeksi antamiseksi.","Sillä tämä on minun vereni, sen uuden Testamentin, joka monen tähden vuodatetaan syntein anteeksi antamiseksi."],[26,29,"Mutta minä sanon teille: en suinkaan minä silleen juo tästä viinapuun hedelmästä, siihen päivään asti kuin minä juon teidän kanssanne sen uuden minun Isäni valtakunnassa.","Mutta minä sanon teille: en suinkaan minä silleen juo tästä viinapuun hedelmästä, siihen päivään asti kuin minä juon teidän kanssanne sen uuden minun Isäni valtakunnassa."],[26,30,"Ja kuin he olivat kiitosvirren veisanneet, menivät he ulos Öljymäelle.","Ja kuin he olivat kiitosvirren veisanneet, menivät he ulos Öljymäelle."],[26,31,"Silloin sanoi Jesus heille: tänä yönä te kaikki pahenette minussa; sillä kirjoitettu on: minä lyön paimenta, ja lampaat laumasta pitää hajoitettaman.","Silloin sanoi Jesus heille: tänä yönä te kaikki pahenette minussa; sillä kirjoitettu on: minä lyön paimenta, ja lampaat laumasta pitää hajoitettaman."],[26,32,"Mutta sittenkuin minä nousen ylös, käyn minä teidän edellänne Galileaan.","Mutta sittenkuin minä nousen ylös, käyn minä teidän edellänne Galileaan."],[26,33,"Niin vastasi Pietari ja sanoi hänelle: jos vielä kaikki sinussa pahenisivat, en minä ikänä pahene.","Niin vastasi Pietari ja sanoi hänelle: jos vielä kaikki sinussa pahenisivat, en minä ikänä pahene."],[26,34,"Jesus sanoi hänelle: totisesti sanon minä sinulle: tänä yönä, ennenkuin kukko laulaa, kolmasti sinä minun kiellät.","Jesus sanoi hänelle: totisesti sanon minä sinulle: tänä yönä, ennenkuin kukko laulaa, kolmasti sinä minun kiellät."],[26,35,"Pietari sanoi hänelle: ja vaikka minun pitäis sinun kanssas kuoleman, en kiellä minä sinua. Niin sanoivat myös kaikki opetuslapset.","Pietari sanoi hänelle: ja vaikka minun pitäis sinun kanssas kuoleman, en kiellä minä sinua. Niin sanoivat myös kaikki opetuslapset."],[26,36,"Silloin tuli Jesus heidän kanssansa kylään, jota kutsutaan Getsemaneksi, ja sanoi opetuslapsillensa: istukaat tässä, niinkauvan kuin minä menen ja rukoilen tuolla.","Silloin tuli Jesus heidän kanssansa kylään, jota kutsutaan Getsemaneksi, ja sanoi opetuslapsillensa: istukaat tässä, niinkauvan kuin minä menen ja rukoilen tuolla."],[26,37,"Ja hän otti tykönsä Pietarin ja kaksi Zebedeuksen poikaa, rupesi murehtimaan ja vapisemaan.","Ja hän otti tykönsä Pietarin ja kaksi Zebedeuksen poikaa, rupesi murehtimaan ja vapisemaan."],[26,38,"Niin sanoi Jesus helle: minun sieluni on suuresti murheissansa kuolemaan asti; olkaat tässä ja valvokaat minun kanssani.","Niin sanoi Jesus helle: minun sieluni on suuresti murheissansa kuolemaan asti; olkaat tässä ja valvokaat minun kanssani."],[26,39,"Ja hän meni vähän taamma, lankesi kasvoillensa, rukoillen ja sanoen: minun Isäni! jos mahdollinen on, niin menkään pois minulta tämä kalkki: ei kuitenkaan niinkuin minä tahdon, mutta niinkuin sinä.","Ja hän meni vähän taamma, lankesi kasvoillensa, rukoillen ja sanoen: minun Isäni! jos mahdollinen on, niin menkään pois minulta tämä kalkki: ei kuitenkaan niinkuin minä tahdon, mutta niinkuin sinä."],[26,40,"Ja hän tuli opetuslasten tykö, ja löysi heidät makaamasta, ja sanoi Pietarille: niin ette voineet yhtä hetkeä valvoa minun kanssani.","Ja hän tuli opetuslasten tykö, ja löysi heidät makaamasta, ja sanoi Pietarille: niin ette voineet yhtä hetkeä valvoa minun kanssani."],[26,41,"Valvokaat ja rukoilkaat, ettette kiusaukseen lankeaisi. Henki tosin on altis, mutta liha on heikko.","Valvokaat ja rukoilkaat, ettette kiusaukseen lankeaisi. Henki tosin on altis, mutta liha on heikko."],[26,42,"Taas meni hän toisen kerran ja rukoili, sanoen: minun Isäni! ellei tämä kalkki taida mennä pois minulta, muutoin jos en minä sitä juo, niin tapahtukoon sinun tahtos.","Taas meni hän toisen kerran ja rukoili, sanoen: minun Isäni! ellei tämä kalkki taida mennä pois minulta, muutoin jos en minä sitä juo, niin tapahtukoon sinun tahtos."],[26,43,"Ja hän tuli ja löysi taas heidät makaamasta; sillä heidän silmänsä olivat raskaat.","Ja hän tuli ja löysi taas heidät makaamasta; sillä heidän silmänsä olivat raskaat."],[26,44,"Ja hän jätti heidät, meni taas ja rukoili kolmannen kerran, ja sanoi entisen sanan.","Ja hän jätti heidät, meni taas ja rukoili kolmannen kerran, ja sanoi entisen sanan."],[26,45,"Silloin hän tuli opetuslastensa tykö, ja sanoi heille: maatkaat vielä ja levätkäät! katso, hetki on lähestynyt, ja Ihmisen Poika annetaan ylön syntisten käsiin.","Silloin hän tuli opetuslastensa tykö, ja sanoi heille: maatkaat vielä ja levätkäät! katso, hetki on lähestynyt, ja Ihmisen Poika annetaan ylön syntisten käsiin."],[26,46,"Nouskaat, käykäämme: katso, se lähestyi, joka minun pettää.","Nouskaat, käykäämme: katso, se lähestyi, joka minun pettää."],[26,47,"Ja vielä hänen puhuessansa, katso, Juudas, yksi kahdestatoistakymmenestä, tuli ja hänen kanssansa paljo väkeä miekoilla ja seipäillä, pappein päämiehiltä ja kansan vanhimmilta.","Ja vielä hänen puhuessansa, katso, Juudas, yksi kahdestatoistakymmenestä, tuli ja hänen kanssansa paljo väkeä miekoilla ja seipäillä, pappein päämiehiltä ja kansan vanhimmilta."],[26,48,"Mutta se, joka hänen petti, oli antanut heille merkin, sanoen: kenenkä minä suuta annan, se on, kiinniottakaat häntä.","Mutta se, joka hänen petti, oli antanut heille merkin, sanoen: kenenkä minä suuta annan, se on, kiinniottakaat häntä."],[26,49,"Ja hän astui kohta Jesuksen tykö ja sanoi: terve, Rabbi! ja suuta antoi hänen.","Ja hän astui kohta Jesuksen tykö ja sanoi: terve, Rabbi! ja suuta antoi hänen."],[26,50,"Niin sanoi Jesus hänelle: ystäväni! mitä varten sinä tulit? Silloin he astuivat edes ja laskivat kätensä Jesuksen päälle, ja ottivat hänen kiinni.","Niin sanoi Jesus hänelle: ystäväni! mitä varten sinä tulit? Silloin he astuivat edes ja laskivat kätensä Jesuksen päälle, ja ottivat hänen kiinni."],[26,51,"Ja katso, yksi niistä, jotka olivat Jesuksen kanssa, ojensi kätensä, veti miekkansa, ja löi ylimmäisen papin palveliaa, ja hakkasi pois hänen korvansa.","Ja katso, yksi niistä, jotka olivat Jesuksen kanssa, ojensi kätensä, veti miekkansa, ja löi ylimmäisen papin palveliaa, ja hakkasi pois hänen korvansa."],[26,52,"Niin Jesus sanoi hänelle: pistä miekkas siallensa; sillä kaikki, jotka miekkaan rupeevat, ne miekkaan hukkuvat.","Niin Jesus sanoi hänelle: pistä miekkas siallensa; sillä kaikki, jotka miekkaan rupeevat, ne miekkaan hukkuvat."],[26,53,"Taikka luuletkos, etten minä voisi vielä rukoilla minun Isääni, lähettämään minulle enemmän kuin kaksitoistakymmentä legiota enkeleitä?","Taikka luuletkos, etten minä voisi vielä rukoilla minun Isääni, lähettämään minulle enemmän kuin kaksitoistakymmentä legiota enkeleitä?"],[26,54,"Kuinka siis Raamattu täytetään, että niin pitää tapahtuman?","Kuinka siis Raamattu täytetään, että niin pitää tapahtuman?"],[26,55,"Sillä hetkellä sanoi Jesus joukolle: niinkuin ryövärin tykö te läksitte miekoilla ja seipäillä minua kiinniottamaan: minä istuin teidän tykönänne joka päivä, opettain templissä, ja ette minua kiinniottaneet.","Sillä hetkellä sanoi Jesus joukolle: niinkuin ryövärin tykö te läksitte miekoilla ja seipäillä minua kiinniottamaan: minä istuin teidän tykönänne joka päivä, opettain templissä, ja ette minua kiinniottaneet."],[26,56,"Mutta tämä on kaikki tapahtunut, että prophetain kirjoitukset täytettäisiin. Silloin kaikki opetuslapset jättivät hänen ja pakenivat.","Mutta tämä on kaikki tapahtunut, että prophetain kirjoitukset täytettäisiin. Silloin kaikki opetuslapset jättivät hänen ja pakenivat."],[26,57,"Mutta ne, jotka Jesuksen olivat kiinniottaneet, veivät hänen Kaiphaan, ylimmäisen papin, tykö, kussa kirjanoppineet ja vanhimmat olivat kokoontuneet.","Mutta ne, jotka Jesuksen olivat kiinniottaneet, veivät hänen Kaiphaan, ylimmäisen papin, tykö, kussa kirjanoppineet ja vanhimmat olivat kokoontuneet."],[26,58,"Mutta Pietari seurasi häntä taampana hamaan ylimmäisen papin salin porstuaan, ja meni sisälle, ja istui palveliain sekaan, näkemään loppua.","Mutta Pietari seurasi häntä taampana hamaan ylimmäisen papin salin porstuaan, ja meni sisälle, ja istui palveliain sekaan, näkemään loppua."],[26,59,"Mutta pappein päämiehet ja vanhimmat ja kaikki raati etsivät väärää todistusta Jesusta vastaan, saadaksensa häntä tappaa;","Mutta pappein päämiehet ja vanhimmat ja kaikki raati etsivät väärää todistusta Jesusta vastaan, saadaksensa häntä tappaa;"],[26,60,"Ja ei löytäneet. Ja vaikka monta väärää todistajaa tuli, niin ei he sittenkään löytäneet. Mutta viimein tuli kaksi väärää todistajaa,","Ja ei löytäneet. Ja vaikka monta väärää todistajaa tuli, niin ei he sittenkään löytäneet. Mutta viimein tuli kaksi väärää todistajaa,"],[26,61,"Ja sanoivat: tämä on sanonut: minä voin maahan jaottaa Jumalan templin, ja kolmena päivänä sen rakentaa ylös.","Ja sanoivat: tämä on sanonut: minä voin maahan jaottaa Jumalan templin, ja kolmena päivänä sen rakentaa ylös."],[26,62,"Ja pappein päämies nousi ja sanoi hänelle: etkös mitään vastaa, mitä nämät sinua vastaan todistavat?","Ja pappein päämies nousi ja sanoi hänelle: etkös mitään vastaa, mitä nämät sinua vastaan todistavat?"],[26,63,"Mutta Jesus oli ääneti. Ja pappein päämies vastasi ja sanoi hänelle: minä vannotan sinua elävän Jumalan kautta, ettäs sanot meille, jos olet Kristus, Jumalan Poika.","Mutta Jesus oli ääneti. Ja pappein päämies vastasi ja sanoi hänelle: minä vannotan sinua elävän Jumalan kautta, ettäs sanot meille, jos olet Kristus, Jumalan Poika."],[26,64,"Sanoi Jesus hänelle: sinäpä sen sanoit; kuitenkin sanon minä teille: tästedes pitää teidän näkemän Ihmisen Pojan istuvan voiman oikialla puolella ja tulevan taivaan pilvissä.","Sanoi Jesus hänelle: sinäpä sen sanoit; kuitenkin sanon minä teille: tästedes pitää teidän näkemän Ihmisen Pojan istuvan voiman oikialla puolella ja tulevan taivaan pilvissä."],[26,65,"Silloin repäisi pappein päämies vaatteensa, sanoen: hän on pilkannut (Jumalaa); mitä me silleen todistajia tarvitsemme? Katso, nyt te kuulitte hänen pilkkansa.","Silloin repäisi pappein päämies vaatteensa, sanoen: hän on pilkannut (Jumalaa); mitä me silleen todistajia tarvitsemme? Katso, nyt te kuulitte hänen pilkkansa."],[26,66,"Mitä te luulette? Mutta he vastasivat ja sanoivat: hän on vikapää kuolemaan.","Mitä te luulette? Mutta he vastasivat ja sanoivat: hän on vikapää kuolemaan."],[26,67,"Silloin he syljeskelivät hänen kasvoillensa ja löivät häntä poskelle, ja muutamat pieksivät häntä sauvoillansa.","Silloin he syljeskelivät hänen kasvoillensa ja löivät häntä poskelle, ja muutamat pieksivät häntä sauvoillansa."],[26,68,"Sanoen: arvaa meille, Kristus, kuka on, joka sinua löi?","Sanoen: arvaa meille, Kristus, kuka on, joka sinua löi?"],[26,69,"Mutta Pietari istui ulkona salista, ja hänen tykönsä tuli yksi piika ja sanoi: sinä olit myös Jesuksen kanssa Galileasta.","Mutta Pietari istui ulkona salista, ja hänen tykönsä tuli yksi piika ja sanoi: sinä olit myös Jesuksen kanssa Galileasta."],[26,70,"Mutta hän kielsi kaikkein edessä ja sanoi: en minä tiedä, mitäs sanot.","Mutta hän kielsi kaikkein edessä ja sanoi: en minä tiedä, mitäs sanot."],[26,71,"Kuin hän läksi ulos ovesta, näki hänen toinen piika ja sanoi niille, jotka siellä olivat: ja tämä oli Jesuksen Natsaretilaisen kanssa.","Kuin hän läksi ulos ovesta, näki hänen toinen piika ja sanoi niille, jotka siellä olivat: ja tämä oli Jesuksen Natsaretilaisen kanssa."],[26,72,"Ja hän kielsi taas vannotulla valalla: en tunne minä sitä ihmistä.","Ja hän kielsi taas vannotulla valalla: en tunne minä sitä ihmistä."],[26,73,"Mutta vähän hetken perästä tulivat ne, jotka siellä seisoivat ja sanoivat Pietarille: totisesti olet sinä myös yksi heistä; sillä sinun puheeskin ilmoittaa sinun.","Mutta vähän hetken perästä tulivat ne, jotka siellä seisoivat ja sanoivat Pietarille: totisesti olet sinä myös yksi heistä; sillä sinun puheeskin ilmoittaa sinun."],[26,74,"Niin hän rupesi itsiänsä sadattelemaan ja vannomaan: en tunne minä sitä ihmistä. Ja kohta kukko lauloi.","Niin hän rupesi itsiänsä sadattelemaan ja vannomaan: en tunne minä sitä ihmistä. Ja kohta kukko lauloi."],[26,75,"Niin Pietari muisti Jesuksen sanan, joka oli hänelle sanonut: ennenkuin kukko laulaa, kolmasti sinä minun kiellät. Ja hän meni ulos ja itki katkerasti.","Niin Pietari muisti Jesuksen sanan, joka oli hänelle sanonut: ennenkuin kukko laulaa, kolmasti sinä minun kiellät. Ja hän meni ulos ja itki katkerasti."],[27,1,"Mutta kuin aamu tuli, pitivät kaikki pappein päämiehet ja kansan vanhimmat neuvoa Jesusta vastaan, häntä kuolettaaksensa,","Mutta kuin aamu tuli, pitivät kaikki pappein päämiehet ja kansan vanhimmat neuvoa Jesusta vastaan, häntä kuolettaaksensa,"],[27,2,"Ja sitoivat hänen, menivät pois ja ylönantoivat hänen maaherralle Pontius Pilatukselle.","Ja sitoivat hänen, menivät pois ja ylönantoivat hänen maaherralle Pontius Pilatukselle."],[27,3,"Kuin Juudas, joka hänen petti, näki hänen kuolemaan tuomituksi, katui hän, ja toi jälleen ne kolmekymmentä hopiapenninkiä pappein päämiehille ja vanhimmille,","Kuin Juudas, joka hänen petti, näki hänen kuolemaan tuomituksi, katui hän, ja toi jälleen ne kolmekymmentä hopiapenninkiä pappein päämiehille ja vanhimmille,"],[27,4,"Sanoen: minä pahasti tein, että minä petin viattoman veren. Mutta he sanoivat: mitä meidän siihen tulee? katso itsiäs.","Sanoen: minä pahasti tein, että minä petin viattoman veren. Mutta he sanoivat: mitä meidän siihen tulee? katso itsiäs."],[27,5,"Ja hän heitti hopiapenningit templiin, läksi sieltä, meni pois ja hirtti itsensä.","Ja hän heitti hopiapenningit templiin, läksi sieltä, meni pois ja hirtti itsensä."],[27,6,"Mutta pappein päämiehet ottivat hopiapenningit ja sanoivat: ei näitä sovi panna uhriarkkuun; sillä se on veren hinta.","Mutta pappein päämiehet ottivat hopiapenningit ja sanoivat: ei näitä sovi panna uhriarkkuun; sillä se on veren hinta."],[27,7,"Niin he pitivät neuvoa, ja ostivat niillä savenvalajan pellon, vierasten hautaamiseksi.","Niin he pitivät neuvoa, ja ostivat niillä savenvalajan pellon, vierasten hautaamiseksi."],[27,8,"Sentähden se pelto on kutsuttu tähän päivään asti veripelloksi.","Sentähden se pelto on kutsuttu tähän päivään asti veripelloksi."],[27,9,"Silloin täytettiin se mikä sanottu oli Jeremias prophetalta, joka sanoo: ja he ottivat kolmekymmentä hopiapenninkiä, sen arvatun hinnan, jonka he arvasivat Israelin lapsilta,","Silloin täytettiin se mikä sanottu oli Jeremias prophetalta, joka sanoo: ja he ottivat kolmekymmentä hopiapenninkiä, sen arvatun hinnan, jonka he arvasivat Israelin lapsilta,"],[27,10,"Ja antoivat ne savenvalajan pellosta, niinkuin Herra on minun käskenyt.","Ja antoivat ne savenvalajan pellosta, niinkuin Herra on minun käskenyt."],[27,11,"Mutta Jesus seisoi maaherran edessä. Niin maaherra kysyi häneltä, sanoen: oletkos sinä Juudalaisten kuningas? Jesus sanoi hänelle: sinäpä sen sanot.","Mutta Jesus seisoi maaherran edessä. Niin maaherra kysyi häneltä, sanoen: oletkos sinä Juudalaisten kuningas? Jesus sanoi hänelle: sinäpä sen sanot."],[27,12,"Ja kuin hänen päällensä kannettiin pappein päämiehiltä ja vanhimmilta, ei hän mitään vastannut.","Ja kuin hänen päällensä kannettiin pappein päämiehiltä ja vanhimmilta, ei hän mitään vastannut."],[27,13,"Silloin sanoi Pilatus hänelle: etkös kuule, kuinka paljon he sinua vastaan todistavat?","Silloin sanoi Pilatus hänelle: etkös kuule, kuinka paljon he sinua vastaan todistavat?"],[27,14,"Ja ei hän vastannut häntä yhtäkään sanaa, niin että maaherra suuresti ihmetteli.","Ja ei hän vastannut häntä yhtäkään sanaa, niin että maaherra suuresti ihmetteli."],[27,15,"Mutta juhlana oli maaherra tottunut päästämään kansalle jonkun vangin irralle, jonka he tahtoivat.","Mutta juhlana oli maaherra tottunut päästämään kansalle jonkun vangin irralle, jonka he tahtoivat."],[27,16,"Niin oli heillä silloin yksi kuuluisa vanki sidottuna, joka kutsuttiin Barabbas.","Niin oli heillä silloin yksi kuuluisa vanki sidottuna, joka kutsuttiin Barabbas."],[27,17,"Kuin he siis koossa olivat, sanoi Pilatus heille: kumman te tahdotte, että minä päästän teille? Barabbaan, taikka Jesuksen, joka kutsutaan Kristus?","Kuin he siis koossa olivat, sanoi Pilatus heille: kumman te tahdotte, että minä päästän teille? Barabbaan, taikka Jesuksen, joka kutsutaan Kristus?"],[27,18,"Sillä hän tiesi, että he hänen kateuden tähden olivat antaneet ylön.","Sillä hän tiesi, että he hänen kateuden tähden olivat antaneet ylön."],[27,19,"Mutta kuin hän tuomio-istuimelle istui, lähetti hänen emäntänsä hänen tykönsä, sanoen: älä sinä mitään tee sille vanhurskaalle; sillä minä olen paljon kärsinyt tänäpänä unessani hänen tähtensä.","Mutta kuin hän tuomio-istuimelle istui, lähetti hänen emäntänsä hänen tykönsä, sanoen: älä sinä mitään tee sille vanhurskaalle; sillä minä olen paljon kärsinyt tänäpänä unessani hänen tähtensä."],[27,20,"Mutta pappein päämiehet ja vanhimmat yllyttivät kansaa anomaan Barabbasta, mutta Jesusta hukkaamaan.","Mutta pappein päämiehet ja vanhimmat yllyttivät kansaa anomaan Barabbasta, mutta Jesusta hukkaamaan."],[27,21,"Niin vastasi maaherra ja sanoi heille: kumman näistä kahdesta te tahdotte, että minä päästän teille? mutta he sanoivat: Barabbaan.","Niin vastasi maaherra ja sanoi heille: kumman näistä kahdesta te tahdotte, että minä päästän teille? mutta he sanoivat: Barabbaan."],[27,22,"Pilatus sanoi heille: mitä siis minun pitää tekemän Jesukselle, joka kutsutaan Kristus? Sanoivat he kaikki hänelle: ristiinnaulittakaan.","Pilatus sanoi heille: mitä siis minun pitää tekemän Jesukselle, joka kutsutaan Kristus? Sanoivat he kaikki hänelle: ristiinnaulittakaan."],[27,23,"Niin sanoi maaherra: mitä hän pahaa teki? Mutta he huusivat sitä enemmin ja sanoivat: ristiinnaulittakaan.","Niin sanoi maaherra: mitä hän pahaa teki? Mutta he huusivat sitä enemmin ja sanoivat: ristiinnaulittakaan."],[27,24,"Kuin Pilatus näki, ettei hän mitään auttaa taitanut, mutta enempi pauhina tuli, otti hän vettä ja pesi kätensä kansan edessä, sanoen: viatoin olen minä tämän vanhurskaan vereen: katsokaat itsiänne.","Kuin Pilatus näki, ettei hän mitään auttaa taitanut, mutta enempi pauhina tuli, otti hän vettä ja pesi kätensä kansan edessä, sanoen: viatoin olen minä tämän vanhurskaan vereen: katsokaat itsiänne."],[27,25,"Ja kaikki kansa vastasi ja sanoi: hänen verensä tulkaan meidän päällemme ja lastemme päälle.","Ja kaikki kansa vastasi ja sanoi: hänen verensä tulkaan meidän päällemme ja lastemme päälle."],[27,26,"Silloin päästi hän heille Barabbaan; mutta Jesuksen, kuin hän hänen ruoskinut oli, antoi hän ylön ristiinnaulittaa.","Silloin päästi hän heille Barabbaan; mutta Jesuksen, kuin hän hänen ruoskinut oli, antoi hän ylön ristiinnaulittaa."],[27,27,"Silloin maaherran huovit veivät Jesuksen raastupaan, ja kokosivat hänen tykönsä kaiken joukon.","Silloin maaherran huovit veivät Jesuksen raastupaan, ja kokosivat hänen tykönsä kaiken joukon."],[27,28,"Ja kuin he olivat hänen riisuneet, puettivat he hänen purpuraiseen kaapuun,","Ja kuin he olivat hänen riisuneet, puettivat he hänen purpuraiseen kaapuun,"],[27,29,"Ja tekivät orjantappuroista kruunun ja panivat hänen päähänsä ja ruovon hänen oikiaan käteensä, ja kumarsivat polviansa hänen edessänsä, pilkkasivat häntä ja sanoivat: terve, Juudalaisten kuningas!","Ja tekivät orjantappuroista kruunun ja panivat hänen päähänsä ja ruovon hänen oikiaan käteensä, ja kumarsivat polviansa hänen edessänsä, pilkkasivat häntä ja sanoivat: terve, Juudalaisten kuningas!"],[27,30,"Ja kuin he olivat sylkeneet hänen päällensä, ottivat he ruovon ja löivät häntä päähän.","Ja kuin he olivat sylkeneet hänen päällensä, ottivat he ruovon ja löivät häntä päähän."],[27,31,"Ja sittekuin he olivat häntä pilkanneet, riisuivat he häneltä kaapun, ja puettivat hänen omiin vaatteisiinsa, ja veivät hänen ristiinnaulittaa.","Ja sittekuin he olivat häntä pilkanneet, riisuivat he häneltä kaapun, ja puettivat hänen omiin vaatteisiinsa, ja veivät hänen ristiinnaulittaa."],[27,32,"Mutta kuin he menivät ulos, löysivät he yhden miehen Kyrenistä, nimeltä Simon: sen he vaativat hänen ristiänsä kantamaan.","Mutta kuin he menivät ulos, löysivät he yhden miehen Kyrenistä, nimeltä Simon: sen he vaativat hänen ristiänsä kantamaan."],[27,33,"Ja tulivat siihen paikkaan, joka kutsutaan Golgata, se on: pääkallon paikka.","Ja tulivat siihen paikkaan, joka kutsutaan Golgata, se on: pääkallon paikka."],[27,34,"He antoivat hänelle etikkaa juoda sapella sekoitettua; ja kuin hän maisti, niin ei hän tahtonut juoda.","He antoivat hänelle etikkaa juoda sapella sekoitettua; ja kuin hän maisti, niin ei hän tahtonut juoda."],[27,35,"Mutta sitte kuin he olivat hänen ristiinnaulinneet, jakoivat he hänen vaatteensa ja heittivät arpaa, että täytettäisiin, mitä sanottu oli prophetan kautta; he ovat minun vaatteeni jakaneet, ja minun vaatteistani ovat he heittäneet arpaa.","Mutta sitte kuin he olivat hänen ristiinnaulinneet, jakoivat he hänen vaatteensa ja heittivät arpaa, että täytettäisiin, mitä sanottu oli prophetan kautta; he ovat minun vaatteeni jakaneet, ja minun vaatteistani ovat he heittäneet arpaa."],[27,36,"Ja istuen he vartioitsivat häntä siinä.","Ja istuen he vartioitsivat häntä siinä."],[27,37,"Ja he panivat hänen päänsä päälle hänen syynsä kirjoitetun: TÄMÄ ON JESUS, JUUDALAISTEN KUNINGAS.","Ja he panivat hänen päänsä päälle hänen syynsä kirjoitetun: TÄMÄ ON JESUS, JUUDALAISTEN KUNINGAS."],[27,38,"Silloin ristiinnaulittiin kaksi ryöväriä hänen kanssansa, yksi oikialle puolelle ja toinen vasemmalle.","Silloin ristiinnaulittiin kaksi ryöväriä hänen kanssansa, yksi oikialle puolelle ja toinen vasemmalle."],[27,39,"Mutta ohitsekäyväiset pilkkasivat häntä, vääntelivät päätänsä,","Mutta ohitsekäyväiset pilkkasivat häntä, vääntelivät päätänsä,"],[27,40,"Ja sanoivat: sinä joka maahan jaotat Jumalan templin ja kolmena päivänä sen rakennat, auta itsiäs: jos olet Jumalan Poika, niin astu alas rististä.","Ja sanoivat: sinä joka maahan jaotat Jumalan templin ja kolmena päivänä sen rakennat, auta itsiäs: jos olet Jumalan Poika, niin astu alas rististä."],[27,41,"Niin myös pappein päämiehet, kirjanoppineitten ja vanhimmitten kanssa, pilkkasivat häntä ja sanoivat:","Niin myös pappein päämiehet, kirjanoppineitten ja vanhimmitten kanssa, pilkkasivat häntä ja sanoivat:"],[27,42,"Muita hän on auttanut, itsiänsä ei hän voi auttaa. Jos hän on Israelin kuningas, niin astukaan nyt alas rististä, niin me uskomme hänen.","Muita hän on auttanut, itsiänsä ei hän voi auttaa. Jos hän on Israelin kuningas, niin astukaan nyt alas rististä, niin me uskomme hänen."],[27,43,"Hän turvasi Jumalaan: päästäköön nyt hänen, jos hän mielistyy häneen. Sillä hän sanoi: Jumalan Poika minä olen.","Hän turvasi Jumalaan: päästäköön nyt hänen, jos hän mielistyy häneen. Sillä hän sanoi: Jumalan Poika minä olen."],[27,44,"Sitä myös ryövärit hänelle soimasivat, jotka olivat ristiinnaulitut hänen kanssansa.","Sitä myös ryövärit hänelle soimasivat, jotka olivat ristiinnaulitut hänen kanssansa."],[27,45,"Mutta kuudennesta hetkestä hamaan yhdeksänteen asti oli pimiä kaikessa maassa.","Mutta kuudennesta hetkestä hamaan yhdeksänteen asti oli pimiä kaikessa maassa."],[27,46,"Ja liki yhdeksättä hetkeä huusi Jesus suurella äänellä, sanoen: Eli, Eli, lamma sabaktani? se on: minun Jumalani, minun Jumalani, miksis minun ylenannoit?","Ja liki yhdeksättä hetkeä huusi Jesus suurella äänellä, sanoen: Eli, Eli, lamma sabaktani? se on: minun Jumalani, minun Jumalani, miksis minun ylenannoit?"],[27,47,"Mutta muutamat niistä, jotka siinä seisoivat, kuin he sen kuulivat, sanoivat: Eliasta hän huutaa.","Mutta muutamat niistä, jotka siinä seisoivat, kuin he sen kuulivat, sanoivat: Eliasta hän huutaa."],[27,48,"Ja kohta juoksi yksi heistä ja otti sienen, ja täytti sen etikalla, pani sen ruovon päähän, ja antoi hänen juoda.","Ja kohta juoksi yksi heistä ja otti sienen, ja täytti sen etikalla, pani sen ruovon päähän, ja antoi hänen juoda."],[27,49,"Mutta muut sanoivat: pidäs, katsokaamme, jos Elias tulee häntä päästämään.","Mutta muut sanoivat: pidäs, katsokaamme, jos Elias tulee häntä päästämään."],[27,50,"Niin Jesus taas huusi suurella äänellä, ja antoi henkensä.","Niin Jesus taas huusi suurella äänellä, ja antoi henkensä."],[27,51,"Ja katso, templin esivaate repesi kahtia ylhäältä hamaan alas, ja maa järisi, ja kalliot halkesivat,","Ja katso, templin esivaate repesi kahtia ylhäältä hamaan alas, ja maa järisi, ja kalliot halkesivat,"],[27,52,"Ja haudat aukenivat, ja monta pyhäin ruumista, jotka maanneet olivat, nousi ylös,","Ja haudat aukenivat, ja monta pyhäin ruumista, jotka maanneet olivat, nousi ylös,"],[27,53,"Ja läksivät ulos haudoista, hänen ylösnousemisensa jälkeen, tulivat pyhään kaupunkiin, ja ilmestyivät monelle.","Ja läksivät ulos haudoista, hänen ylösnousemisensa jälkeen, tulivat pyhään kaupunkiin, ja ilmestyivät monelle."],[27,54,"Mutta kuin sadanpäämies ja ne, jotka hänen kanssansa olivat vartioitsemassa Jesusta, näkivät maan järinän ja ne, mitkä tapahtuivat, pelkäsivät he suuresti ja sanoivat: totisesti oli tämä Jumalan Poika.","Mutta kuin sadanpäämies ja ne, jotka hänen kanssansa olivat vartioitsemassa Jesusta, näkivät maan järinän ja ne, mitkä tapahtuivat, pelkäsivät he suuresti ja sanoivat: totisesti oli tämä Jumalan Poika."],[27,55,"Mutta siellä oli paljo vaimoja taampana katselemassa, jotka Jesusta olivat seuranneet Galileasta, palvellen häntä,","Mutta siellä oli paljo vaimoja taampana katselemassa, jotka Jesusta olivat seuranneet Galileasta, palvellen häntä,"],[27,56,"Joiden seassa oli Maria Magdalena, ja Maria Jakobin ja Joseen äiti, ja Zebedeuksen poikain äiti.","Joiden seassa oli Maria Magdalena, ja Maria Jakobin ja Joseen äiti, ja Zebedeuksen poikain äiti."],[27,57,"Mutta kuin ehtoo tuli, tuli yksi rikas mies Arimatiasta, jonka nimi oli Joseph, joka myös itse oli Jesuksen opetuslapsi.","Mutta kuin ehtoo tuli, tuli yksi rikas mies Arimatiasta, jonka nimi oli Joseph, joka myös itse oli Jesuksen opetuslapsi."],[27,58,"Tämä meni Pilatuksen tykö ja pyysi Jesuksen ruumista. Silloin Pilatus käski annettaa ruumiin.","Tämä meni Pilatuksen tykö ja pyysi Jesuksen ruumista. Silloin Pilatus käski annettaa ruumiin."],[27,59,"Ja kuin Joseph oli ruumiin ottanut, kääri hän sen puhtaasen liinaan,","Ja kuin Joseph oli ruumiin ottanut, kääri hän sen puhtaasen liinaan,"],[27,60,"Ja pani omaan uuteen hautaansa, jonka hän oli hakannut kallioon, ja vieritti suuren kiven haudan ovelle, ja meni pois.","Ja pani omaan uuteen hautaansa, jonka hän oli hakannut kallioon, ja vieritti suuren kiven haudan ovelle, ja meni pois."],[27,61,"Silloin olivat siellä Maria Magdalena ja toinen Maria, ja istuivat haudan kohdalla.","Silloin olivat siellä Maria Magdalena ja toinen Maria, ja istuivat haudan kohdalla."],[27,62,"Mutta toisena päivänä valmistuksen päivästä kokoontuivat pappein päämiehet ja Pharisealaiset Pilatuksen tykö,","Mutta toisena päivänä valmistuksen päivästä kokoontuivat pappein päämiehet ja Pharisealaiset Pilatuksen tykö,"],[27,63,"Sanoen: herra, me muistamme sen vietteliän sanoneen eläissänsä: kolmen päivän perästä minä nousen.","Sanoen: herra, me muistamme sen vietteliän sanoneen eläissänsä: kolmen päivän perästä minä nousen."],[27,64,"Käske siis varjeltaa hautaa kolmanteen päivään asti, ettei hänen opetuslapsensa tulisi yöllä ja varastaisi häntä, ja sanoisi kansalle: hän nousi kuolleista: ja niin jälkimäinen villitys tulee pahemmaksi kuin ensimäinen.","Käske siis varjeltaa hautaa kolmanteen päivään asti, ettei hänen opetuslapsensa tulisi yöllä ja varastaisi häntä, ja sanoisi kansalle: hän nousi kuolleista: ja niin jälkimäinen villitys tulee pahemmaksi kuin ensimäinen."],[27,65,"Pilatus sanoi heille: teillä on vartiat: menkäät, vartioitkaat niinkuin te tiedätte.","Pilatus sanoi heille: teillä on vartiat: menkäät, vartioitkaat niinkuin te tiedätte."],[27,66,"Mutta he menivät pois, ja vahvistivat haudan vartiain kanssa, ja lukitsivat kiven sinetillänsä.","Mutta he menivät pois, ja vahvistivat haudan vartiain kanssa, ja lukitsivat kiven sinetillänsä."],[28,1,"Mutta sabbatin päivän lopulla, joka rupesi valaisemaan toista sabbatia, tuli Maria Magdalena ja toinen Maria katsomaan hautaa.","Mutta sabbatin päivän lopulla, joka rupesi valaisemaan toista sabbatia, tuli Maria Magdalena ja toinen Maria katsomaan hautaa."],[28,2,"Ja katso, suuri maanjäristys tapahtui; sillä Herran enkeli astui alas taivaasta, tuli ja vieritti kiven ovelta, ja istui sen päälle.","Ja katso, suuri maanjäristys tapahtui; sillä Herran enkeli astui alas taivaasta, tuli ja vieritti kiven ovelta, ja istui sen päälle."],[28,3,"Ja hän oli nähdä niinkuin pitkäisen tuli ja hänen vaatteensa olivat valkiat niinkuin lumi.","Ja hän oli nähdä niinkuin pitkäisen tuli ja hänen vaatteensa olivat valkiat niinkuin lumi."],[28,4,"Mutta hänen pelvostansa hämmästyivät vartiat ja tulivat niinkuin he olisivat kuolleet.","Mutta hänen pelvostansa hämmästyivät vartiat ja tulivat niinkuin he olisivat kuolleet."],[28,5,"Mutta enkeli vastasi ja sanoi vaimoille: älkäät peljätkö, sillä minä tiedän teidän etsivän ristiinnaulittua Jesusta.","Mutta enkeli vastasi ja sanoi vaimoille: älkäät peljätkö, sillä minä tiedän teidän etsivän ristiinnaulittua Jesusta."],[28,6,"Ei hän ole tässä; sillä hän nousi ylös, niinkuin hän sanoi. Tulkaat, katsokaat siaa, kuhunka Herra pantu oli.","Ei hän ole tässä; sillä hän nousi ylös, niinkuin hän sanoi. Tulkaat, katsokaat siaa, kuhunka Herra pantu oli."],[28,7,"Ja menkäät pian ja sanokaat hänen opetuslapsillensa, että hän nousi kuolleista. Ja katso, hän menee teidän edellänne Galileaan: siellä teidän pitää hänen näkemän, katso, minä sen teille sanoin.","Ja menkäät pian ja sanokaat hänen opetuslapsillensa, että hän nousi kuolleista. Ja katso, hän menee teidän edellänne Galileaan: siellä teidän pitää hänen näkemän, katso, minä sen teille sanoin."],[28,8,"Ja he menivät nopiasti haudalta suurella pelvolla ja ilolla, ja juoksivat ilmoittamaan hänen opetuslapsillensa.","Ja he menivät nopiasti haudalta suurella pelvolla ja ilolla, ja juoksivat ilmoittamaan hänen opetuslapsillensa."],[28,9,"Mutta heidän mennessänsä ilmoittamaan hänen opetuslapsillensa, katso, niin tuli Jesus heitä vastaan ja sanoi: terve teille! Niin he tulivat ja rupesivat hänen jalkoihinsa, ja kumartaen rukoilivat häntä.","Mutta heidän mennessänsä ilmoittamaan hänen opetuslapsillensa, katso, niin tuli Jesus heitä vastaan ja sanoi: terve teille! Niin he tulivat ja rupesivat hänen jalkoihinsa, ja kumartaen rukoilivat häntä."],[28,10,"Silloin sanoi Jesus heille: älkäät peljätkö! menkäät, ilmoittakaat minun veljilleni, että he menisivät Galileaan: siellä he saavat minun nähdä.","Silloin sanoi Jesus heille: älkäät peljätkö! menkäät, ilmoittakaat minun veljilleni, että he menisivät Galileaan: siellä he saavat minun nähdä."],[28,11,"Mutta kuin he menivät pois, katso, niin tulivat muutamat vartioista kaupunkiin ja ilmoittivat ylimmäisille papeille kaikki, mitä tapahtunut oli.","Mutta kuin he menivät pois, katso, niin tulivat muutamat vartioista kaupunkiin ja ilmoittivat ylimmäisille papeille kaikki, mitä tapahtunut oli."],[28,12,"Niin he kokoontuivat vanhimpain kanssa, ja neuvoa pitivät, ja antoivat sotamiehille paljon rahaa,","Niin he kokoontuivat vanhimpain kanssa, ja neuvoa pitivät, ja antoivat sotamiehille paljon rahaa,"],[28,13,"Sanoen: sanokaat, että hänen opetuslapsensa tulivat yöllä ja varastivat hänen meidän maatessamme.","Sanoen: sanokaat, että hänen opetuslapsensa tulivat yöllä ja varastivat hänen meidän maatessamme."],[28,14,"Ja jos se tulee maaherran korville, niin me tahdomme hänen lepyttää ja saattaa teidät suruttomaksi.","Ja jos se tulee maaherran korville, niin me tahdomme hänen lepyttää ja saattaa teidät suruttomaksi."],[28,15,"Ja he ottivat rahan, ja tekivät niinkuin he olivat opetetut. Ja tämä puhe on ääneksi otettu Juudalaisten seassa hamaan tähän päivään asti.","Ja he ottivat rahan, ja tekivät niinkuin he olivat opetetut. Ja tämä puhe on ääneksi otettu Juudalaisten seassa hamaan tähän päivään asti."],[28,16,"Mutta ne yksitoistakymmentä opetuslasta menivät Galileaan, sille mäelle, jonka Jesus oli heille määrännyt.","Mutta ne yksitoistakymmentä opetuslasta menivät Galileaan, sille mäelle, jonka Jesus oli heille määrännyt."],[28,17,"Ja kuin he näkivät hänen, kumarsivat he häntä, mutta muutamat epäilivät.","Ja kuin he näkivät hänen, kumarsivat he häntä, mutta muutamat epäilivät."],[28,18,"Ja Jesus tuli ja puhutteli heitä, sanoen: minulle on annettu kaikki voima taivaassa ja maan päällä.","Ja Jesus tuli ja puhutteli heitä, sanoen: minulle on annettu kaikki voima taivaassa ja maan päällä."],[28,19,"Menkäät siis ja opettakaat* kaikkea kansaa, ja kastakaat heitä nimeen Isän ja Pojan ja Pyhän Hengen,","Menkäät siis ja opettakaat* kaikkea kansaa, ja kastakaat heitä nimeen Isän ja Pojan ja Pyhän Hengen,"],[28,20,"Ja opettakaat heitä pitämään kaikki, mitä minä olen teille käskenyt. Ja katso, minä olen teidän kanssanne joka päivä, maailman loppuun asti. Amen!","Ja opettakaat heitä pitämään kaikki, mitä minä olen teille käskenyt. Ja katso, minä olen teidän kanssanne joka päivä, maailman loppuun asti. Amen!"]]}};